def _configure_windows_app_identity():
    """Give the script its own Windows taskbar identity.

    When RiftSense is launched through python.exe, Windows can otherwise group
    the window under Python and show the Python executable icon in the taskbar.
    Setting a stable AppUserModelID before the first Tk window is created lets
    Windows treat RiftSense as its own desktop application.
    """
    if os.name != "nt":
        return
    try:
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(
            APP_USER_MODEL_ID
        )
    except (AttributeError, OSError):
        pass


def _apply_windows_native_window_icon(window):
    """Force the RiftSense icon onto the native Windows top-level HWND.

    Tk's iconbitmap/iconphoto can still leave a source-launched app grouped
    under python.exe on some Windows taskbars. WM_SETICON updates the native
    small/big window icons directly after Tk has created its wrapper HWND.
    """
    if os.name != "nt" or not WINDOWS_ICON_PATH.exists():
        return []

    handles = []
    try:
        window.update_idletasks()
        user32 = ctypes.windll.user32

        child_hwnd = int(window.winfo_id())
        parent_hwnd = int(user32.GetParent(child_hwnd) or 0)
        hwnd = parent_hwnd or child_hwnd

        IMAGE_ICON = 1
        LR_LOADFROMFILE = 0x0010
        WM_SETICON = 0x0080
        ICON_SMALL = 0
        ICON_BIG = 1

        for icon_kind, size in ((ICON_BIG, 32), (ICON_SMALL, 16)):
            hicon = user32.LoadImageW(
                None,
                str(WINDOWS_ICON_PATH),
                IMAGE_ICON,
                size,
                size,
                LR_LOADFROMFILE,
            )
            if hicon:
                user32.SendMessageW(
                    hwnd,
                    WM_SETICON,
                    icon_kind,
                    hicon,
                )
                # Tk can expose a child HWND beneath the wrapper. Updating both
                # avoids shell/version-specific differences in which HWND is read.
                if child_hwnd != hwnd:
                    user32.SendMessageW(
                        child_hwnd,
                        WM_SETICON,
                        icon_kind,
                        hicon,
                    )
                handles.append(hicon)
    except (AttributeError, OSError, tk.TclError, ValueError):
        return handles

    return handles

