def theme_palette(mode):
    mode = str(mode or "DARK").upper()
    if mode not in THEME_PALETTES:
        mode = "DARK"
    return dict(THEME_PALETTES[mode])


def apply_color_palette(mode):
    """Update module palette globals. Existing Tk widgets are recolored separately."""
    global BG, PANEL, PANEL_ALT, FG, MUTED, ACCENT, GOOD, DANGER
    global POS_BG, ORANGE_BG, NEG_BG, TIE_BG, BORDER, BUTTON_BG
    global BUTTON_ACTIVE, ENTRY_BG, SIDEBAR_BG, SIDEBAR_FG, SIDEBAR_MUTED, TOPBAR_BG, DEEP_BG
    global HEADER_BG, SELECT_BG, SUBTLE_BORDER, TAB_SELECTED_BG
    global TAB_ACTIVE_BG, BORDER_ACTIVE

    palette = theme_palette(mode)
    for key, value in palette.items():
        globals()[key] = value
    return palette


