def is_assassin_defensive_item(name):
    return normalize_name(name) in {
        normalize_name(item_name)
        for item_name in ASSASSIN_DEFENSIVE_ITEM_NAMES
    }


def is_assassin_offensive_item(
    name,
    dd=None,
):
    normalized = normalize_name(
        name
    )
    curated = set()
    for values in (
        ASSASSIN_BUILD_POOLS.values()
    ):
        curated.update(
            normalize_name(
                item_name
            )
            for item_name in values
        )
    for values in (
        ASSASSIN_BUILD_CORES.values()
    ):
        curated.update(
            normalize_name(
                item_name
            )
            for item_name in values
        )

    if normalized in curated:
        return True

    if dd is None:
        return False

    item_id = dd.item_id_for_name(
        name
    )
    meta = (
        dd.item_data.get(
            str(
                item_id
            ),
            {},
        )
        or {}
    )
    description = re.sub(
        r"<[^>]+>",
        " ",
        str(
            meta.get(
                "description",
                "",
            )
            or ""
        ),
    ).lower()

    return (
        "lethality"
        in description
        or "armor penetration"
        in description
    )


