def is_frontline_champion(name, dd=None):
    name = str(name or "")
    if name in FRONTLINE_NAMES or name in TANKISH_NAMES:
        return True
    if dd is not None:
        try:
            return "Tank" in set(dd.champion_tags(name) or [])
        except (AttributeError, TypeError, ValueError):
            pass
    return False


def allied_frontline_count(allies, active_champion, dd=None):
    active_key = normalize_name(active_champion)
    count = 0
    for ally in allies or []:
        name = ally.get("championName", "") if isinstance(ally, dict) else str(ally)
        if normalize_name(name) == active_key:
            continue
        if is_frontline_champion(name, dd):
            count += 1
    return count


def enemy_squishy_count(enemies, dd=None):
    count = 0
    for enemy in enemies or []:
        name = enemy.get("championName", "") if isinstance(enemy, dict) else str(enemy)
        if is_frontline_champion(name, dd):
            continue
        tags = set()
        if dd is not None:
            try:
                tags = set(dd.champion_tags(name) or [])
            except Exception:
                tags = set()
        if not tags or tags & SQUISHY_HINT_TAGS or "Support" in tags:
            count += 1
    return count


def live_build_identity(champion, allies, enemies, dd=None):
    """
    Return the intended job for the current composition.

    Nocturne is the first champion with two identities:
      - ASSASSIN when allied frontline already covers engage/durability
      - BRUISER when RiftSense still needs him to survive the first contact

    This is team-role coverage, not a claim that one style is always optimal.
    """
    frontline = allied_frontline_count(allies, champion, dd)
    squishies = enemy_squishy_count(enemies, dd)

    if champion == "Nocturne":
        if frontline >= 2:
            return {
                "mode": "ASSASSIN",
                "frontline": frontline,
                "squishies": squishies,
                "reason": f"frontline covered by {frontline} allies",
            }
        if frontline >= 1 and squishies >= 3:
            return {
                "mode": "ASSASSIN",
                "frontline": frontline,
                "squishies": squishies,
                "reason": f"{frontline} allied frontliner + {squishies} squishy enemies",
            }

        return {
            "mode": "BRUISER",
            "frontline": frontline,
            "squishies": squishies,
            "reason": "limited allied frontline",
        }

    return {
        "mode": "PROFILE",
        "frontline": frontline,
        "squishies": squishies,
        "reason": "champion profile",
    }


