def _legacy_data_candidates():
    """
    Find older extracted app versions near the current folder.

    This is intentionally shallow and local: no broad disk scan. It covers the
    common case where v34 and v35 are extracted next to each other in Downloads
    or on Desktop.
    """
    candidates = []

    def add_candidate(path):
        try:
            path = Path(path).resolve()
        except Exception:
            return
        if path == APP_DIR.resolve():
            return
        if path in candidates:
            return
        if (
            (path / "settings.json").exists()
            or (path / "history").exists()
            or (path / "cache").exists()
        ):
            candidates.append(path)

    # The current package itself can contain legacy defaults/data.
    if (
        (APP_DIR / "settings.json").exists()
        or (APP_DIR / "history").exists()
        or (APP_DIR / "cache").exists()
    ):
        candidates.append(APP_DIR)

    scan_roots = [
        APP_DIR.parent,
        Path.home() / "Downloads",
        Path.home() / "Desktop",
    ]
    seen_roots = set()

    for scan_root in scan_roots:
        try:
            scan_root = scan_root.resolve()
        except Exception:
            continue
        if scan_root in seen_roots or not scan_root.exists():
            continue
        seen_roots.add(scan_root)

        try:
            children = list(scan_root.iterdir())
        except Exception:
            continue

        for child in children:
            if not child.is_dir():
                continue
            name = child.name.lower()
            if (
                "rift_build_assistant" in name
                or "rift build assistant" in name
            ):
                add_candidate(child)

    def richness(path):
        score = 0
        try:
            settings = path / "settings.json"
            if settings.exists():
                score += 1000 + int(settings.stat().st_mtime)
            history = path / "history"
            if history.exists():
                score += 5000 * sum(
                    1
                    for item in history.rglob("*.json")
                    if item.is_file()
                )
            score += int(path.stat().st_mtime)
        except OSError:
            pass

        # Prefer a real previous extracted version over the pristine files that
        # ship inside the newly downloaded version.
        try:
            if path.resolve() == APP_DIR.resolve():
                score -= 10_000_000_000
        except OSError:
            pass

        return score

    return sorted(
        candidates,
        key=richness,
        reverse=True,
    )


def migrate_legacy_user_data():
    """
    Merge older local app data into the version-independent DATA_DIR.

    Existing persistent files always win. Missing history/raw-match/cache files
    are copied without deleting anything from older versions.
    """
    DATA_DIR.mkdir(
        parents=True,
        exist_ok=True,
    )

    candidates = _legacy_data_candidates()

    # Prefer the richest/newest previous settings file only when persistent
    # settings do not already exist.
    if not SETTINGS_PATH.exists():
        for legacy in candidates:
            legacy_settings = legacy / "settings.json"
            if legacy_settings.exists():
                try:
                    shutil.copy2(
                        legacy_settings,
                        SETTINGS_PATH,
                    )
                    break
                except OSError:
                    pass

    for legacy in candidates:
        legacy_history = legacy / "history"
        if legacy_history.exists():
            try:
                shutil.copytree(
                    legacy_history,
                    HISTORY_DIR,
                    dirs_exist_ok=True,
                    copy_function=shutil.copy2,
                )
            except OSError:
                pass

        legacy_cache = legacy / "cache"
        if legacy_cache.exists():
            try:
                shutil.copytree(
                    legacy_cache,
                    CACHE_DIR,
                    dirs_exist_ok=True,
                    copy_function=shutil.copy2,
                )
            except OSError:
                pass


migrate_legacy_user_data()

