_SECRET_PATTERNS = (
    (
        re.compile(
            r"RGAPI-[A-Za-z0-9_-]+",
            re.IGNORECASE,
        ),
        "RGAPI-[REDACTED]",
    ),
    (
        re.compile(
            r"(api[_ -]?key\s*[:=]\s*)(RGAPI-[^\s,;]+|[A-Za-z0-9_-]{30,})",
            re.IGNORECASE,
        ),
        r"\1[REDACTED]",
    ),
)


def redact_sensitive(
    value,
):
    text = str(
        value
        if value is not None
        else ""
    )
    for pattern, replacement in _SECRET_PATTERNS:
        text = pattern.sub(
            replacement,
            text,
        )
    return text


PERSISTED_SECRET_KEYS = (
    "api_key",
    "riot_api_key",
    "riotApiKey",
)


def strip_persisted_secrets(mapping):
    """Remove legacy session credentials from a mutable persisted mapping."""
    if not isinstance(mapping, dict):
        return False
    removed = False
    for key in PERSISTED_SECRET_KEYS:
        if key in mapping:
            mapping.pop(key, None)
            removed = True
    return removed


