def log_info(
    message,
):
    try:
        LOGGER.info(
            redact_sensitive(
                message
            )
        )
    except Exception:
        pass


def log_warning(
    message,
):
    try:
        LOGGER.warning(
            redact_sensitive(
                message
            )
        )
    except Exception:
        pass


def log_exception(
    context,
    exc=None,
):
    try:
        if exc is None:
            LOGGER.exception(
                redact_sensitive(
                    context
                )
            )
        else:
            LOGGER.error(
                "%s\n%s",
                redact_sensitive(
                    context
                ),
                redact_sensitive(
                    "".join(
                        traceback.format_exception(
                            type(
                                exc
                            ),
                            exc,
                            exc.__traceback__,
                        )
                    )
                ),
            )
    except Exception:
        pass


