def save_settings():
    """
    Persist settings atomically and report whether the write succeeded.

    Older versions swallowed filesystem errors, so the UI could say "Saved"
    even if settings.json had not actually been written.
    """
    global SETTINGS_SAVE_ERROR
    SETTINGS_SAVE_ERROR = ""

    # Defense in depth: session Riot credentials are never persisted even if a
    # future caller accidentally inserts a legacy key into SETTINGS.
    strip_persisted_secrets(
        SETTINGS
    )

    try:
        SETTINGS_PATH.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        temp_path = SETTINGS_PATH.with_suffix(
            SETTINGS_PATH.suffix
            + ".tmp"
        )
        temp_path.write_text(
            json.dumps(
                SETTINGS,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        temp_path.replace(
            SETTINGS_PATH
        )
        return True
    except Exception as exc:
        SETTINGS_SAVE_ERROR = str(
            exc
        )
        try:
            temp_path = SETTINGS_PATH.with_suffix(
                SETTINGS_PATH.suffix
                + ".tmp"
            )
            if temp_path.exists():
                temp_path.unlink()
        except Exception as exc:
            log_warning("Best-effort save_settings operation failed: " + str(exc))
        return False


def normalize_name(value):
    return (value or "").strip().lower()


CHAMPION_DISPLAY_ALIASES = {
    "monkeyking": "Wukong",
}


def champion_display_name(value):
    """
    Convert Riot/Data Dragon internal champion identifiers to player-facing
    champion names without changing the raw identifier used for icon lookup.
    """
    raw = str(
        value
        or ""
    ).strip()
    if not raw:
        return "-"
    return CHAMPION_DISPLAY_ALIASES.get(
        normalize_name(
            raw
        ),
        raw,
    )


def fetch_json(url: str, timeout: float = 4.0):
    req = Request(
        url,
        headers={"User-Agent": f"RiftSense/{APP_VERSION}", "Accept": "application/json"},
        method="GET",
    )
    with urlopen(req, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def download_file(url: str, dest: Path, timeout: float = 5.0):
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(dest.suffix + ".tmp")
    req = Request(url, headers={"User-Agent": "RiftSense/52.0"}, method="GET")
    with urlopen(req, timeout=timeout) as response:
        tmp.write_bytes(response.read())
    tmp.replace(dest)


def patch_prefix_from_game_version(game_version: str):
    parts = (game_version or "").split(".")
    if len(parts) >= 2 and parts[0].isdigit() and parts[1].isdigit():
        return f"{parts[0]}.{parts[1]}."
    return ""


def champion_in_list(name, values):
    n = normalize_name(name)
    return any(normalize_name(v) == n for v in values)


def damage_type(name):
    is_ap = champion_in_list(name, TRAITS.get("ap", []))
    is_ad = champion_in_list(name, TRAITS.get("ad", []))
    if is_ap and is_ad:
        return "MIXED"
    if is_ap:
        return "AP"
    if is_ad:
        return "AD"
    return "UNKNOWN"


