def visible_inventory_gold(player, dd):
    """
    Sum current non-consumable inventory value.

    This is intentionally visible item gold rather than total gold:
    Riot exposes currentGold only for the active player, not every player.
    """
    total = 0

    for live_item in player.get("items") or []:
        item_id = live_item.get("itemID")
        if not item_id:
            continue

        name = live_item.get("displayName") or dd.item_name(item_id)
        if normalize_name(name) in {
            "warding totem (trinket)",
            "oracle lens",
            "farsight alteration",
        }:
            continue

        meta = dd.item_data.get(str(item_id), {}) or {}
        tags = set(meta.get("tags", []) or [])
        if "Consumable" in tags:
            continue

        count = int(live_item.get("count", 1) or 1)
        ddragon_total = int((meta.get("gold", {}) or {}).get("total", 0) or 0)
        live_price = int(live_item.get("price", 0) or 0)
        unit_value = ddragon_total if ddragon_total > 0 else live_price
        total += max(0, unit_value) * max(1, count)

    return int(total)




def player_live_identifier(player):
    """Return the best Live Client identifier for a visible player."""
    player = player or {}
    riot_id = str(player.get("riotId") or "").strip()
    if riot_id:
        return riot_id

    game_name = str(player.get("riotIdGameName") or "").strip()
    tag_line = str(player.get("riotIdTagLine") or "").strip()
    if game_name and tag_line:
        return f"{game_name}#{tag_line}"

    return str(player.get("summonerName") or "").strip()


def player_has_jungle_companion_hint(player):
    """Detect a visible jungle starter/evolution without needing Data Dragon."""
    family_tokens = ("gustwalker", "mosstomper", "scorchclaw")
    for item in (player or {}).get("items") or []:
        combined = " ".join(
            str(item.get(key) or "")
            for key in ("displayName", "rawDisplayName")
        ).lower()
        if any(token in combined for token in family_tokens):
            return True
    return False


def jungle_identity_score(player):
    """Score only explicit jungle evidence; never use player-list order."""
    player = player or {}
    score = 0
    if player_has_smite(player):
        score += 100
    if str(player.get("position") or "").upper() == "JUNGLE":
        score += 50
    if player_has_jungle_companion_hint(player):
        score += 25
    return score


def lane_player_map(players):
    """
    Map Live Client players to the five Summoner's Rift roles.

    JUNGLE is never guessed from player-list order. We require explicit jungle
    evidence (Smite, Riot's JUNGLE position, or a visible jungle companion).
    If Riot has not exposed enough evidence yet, the jungle slot stays empty
    rather than displaying another player's CS as the enemy jungler's CS.
    """
    mapping = {}
    unassigned = []

    valid_positions = {
        key
        for key, _label in LANE_ORDER
    }

    # Pick the strongest explicit jungle candidate. Smite is weighted highest,
    # with position and a visible jungle companion acting as corroboration.
    jungle_candidates = [
        (jungle_identity_score(player), index, player)
        for index, player in enumerate(players or [])
    ]
    jungle_candidates = [
        row for row in jungle_candidates
        if row[0] > 0
    ]
    if jungle_candidates:
        jungle_candidates.sort(
            key=lambda row: (row[0], -row[1]),
            reverse=True,
        )
        mapping["JUNGLE"] = jungle_candidates[0][2]

    # Trust explicit Riot position values for lane roles.
    for player in players or []:
        if mapping.get("JUNGLE") is player:
            continue

        position = str(
            player.get("position")
            or ""
        ).upper()

        if (
            position in valid_positions
            and position != "JUNGLE"
            and position not in mapping
        ):
            mapping[position] = player
        else:
            unassigned.append(player)

    # Last-resort ordering is allowed only for unresolved lane roles. JUNGLE is
    # deliberately excluded: an unknown jungle slot is safer than false data.
    missing = [
        key
        for key, _label in LANE_ORDER
        if key not in mapping
        and key != "JUNGLE"
    ]

    for position, player in zip(missing, unassigned):
        mapping[position] = player

    return mapping


def signed_gold(value):
    value = int(value)
    if value > 0:
        return f"+{value:,}g"
    if value < 0:
        return f"-{abs(value):,}g"
    return "0g"


