def aggregate_players(players, dd):
    gold = sum(visible_inventory_gold(player, dd) for player in players)
    levels = [int(player.get("level", 0) or 0) for player in players]
    scores = [score_line(player) for player in players]
    return {
        "gold": gold,
        "level": sum(levels) / len(levels) if levels else 0.0,
        "kills": sum(x[0] for x in scores),
        "deaths": sum(x[1] for x in scores),
        "assists": sum(x[2] for x in scores),
        "cs": sum(x[3] for x in scores),
    }


def gank_lane_snapshot(lane_name, our_map, enemy_map, dd):
    positions = GANK_LANES[lane_name]
    ours = [our_map.get(p) for p in positions if our_map.get(p)]
    enemies = [enemy_map.get(p) for p in positions if enemy_map.get(p)]
    a = aggregate_players(ours, dd); b = aggregate_players(enemies, dd)
    return {
        "lane": lane_name, "ours": ours, "enemies": enemies,
        "our_gold": a["gold"], "enemy_gold": b["gold"], "gold_diff": a["gold"]-b["gold"],
        "our_level": a["level"], "enemy_level": b["level"], "level_diff": a["level"]-b["level"],
        "our_kills": a["kills"], "enemy_kills": b["kills"],
        "our_deaths": a["deaths"], "enemy_deaths": b["deaths"],
        "our_cs": a["cs"], "enemy_cs": b["cs"], "cs_diff": a["cs"]-b["cs"],
    }


def lane_trend_from_history(history, current_diff, now, lookback=75.0):
    eligible=[(t,d) for t,d in (history or []) if now-t <= lookback]
    if len(eligible)<3: return 0
    return int(current_diff-eligible[0][1])


def gank_priority_score(snapshot, trend, dd):
    lane=snapshot["lane"]; score=5.0; reasons=[]; warnings=[]
    gd=snapshot["gold_diff"]; ld=snapshot["level_diff"]; csd=snapshot["cs_diff"]

    if -2200 < gd < -250:
        score += min(1.15, abs(gd)/1500.0)
        reasons.append(f"lane is behind {abs(gd):,}g but still salvageable")
    elif gd <= -2200:
        score -= 1.2; warnings.append(f"lane is heavily behind ({abs(gd):,}g)")
    elif 350 < gd < 1900:
        score += .45; reasons.append(f"your lane is ahead {gd:,}g and can be snowballed")
    elif gd >= 1900:
        score -= .25; reasons.append("your lane is already strongly ahead")

    if trend <= -700:
        score += .55; reasons.append(f"lane lost {abs(trend):,}g of item-value ground recently")
    elif trend >= 700:
        score += .25; reasons.append(f"lane gained {trend:,}g of item-value ground recently")

    setup=0
    for p in snapshot["ours"]:
        name=p.get("championName","")
        if name in GANK_SETUP_NAMES or champion_in_list(name, TRAITS.get("highCC", [])): setup+=1
    if setup:
        score += min(.85,.50+.20*(setup-1)); reasons.append("your laner(s) have useful gank setup")

    squishy=mobile=tanky=0
    for p in snapshot["enemies"]:
        name=p.get("championName",""); tags=set(dd.champion_tags(name))
        if tags & SQUISHY_HINT_TAGS and name not in TANKISH_NAMES: squishy+=1
        if name in MOBILE_ESCAPE_NAMES: mobile+=1
        if name in TANKISH_NAMES: tanky+=1
    if squishy:
        score += min(.70,.35*squishy); reasons.append("enemy target(s) are relatively squishy")
    if mobile and setup==0:
        score -= min(.60,.30*mobile); warnings.append("enemy has mobility and your lane has limited setup")
    if tanky: score -= min(.45,.25*tanky)

    if ld >= 1.0:
        score += .25; reasons.append("your lane has a level advantage")
    elif ld <= -1.5:
        score -= .65; warnings.append("enemy lane has a meaningful level advantage")

    # Extra rescue penalty: far behind in both items and levels is often a trap.
    if gd <= -1200 and ld <= -1.5:
        score -= .85; warnings.append("rescue gank is risky because both items and levels are behind")

    if csd <= -25 and gd < 0:
        score += .15; reasons.append("your lane is also losing farm pressure")
    if snapshot["enemy_deaths"] >= 2:
        score += min(.45,snapshot["enemy_deaths"]*.10); reasons.append("enemy lane has already been punishable")
    if lane=="BOT": score += .20
    if gd <= -2600 and ld <= -1.5:
        score -= .70; warnings.append("high 2v2/3v3 risk if the enemy jungler appears")

    score=max(1.0,min(9.8,score))
    priority="HIGH" if score>=7.6 else "MED" if score>=6.0 else "LOW"
    risk="HIGH" if (gd<=-2200 or (gd<=-1200 and ld<=-1.5)) else "MED" if (gd<=-900 or mobile>=1) else "LOW"
    if not reasons: reasons.append("lane state is relatively neutral")
    return {"score":round(score,1),"priority":priority,"risk":risk,"reasons":reasons[:3],"warnings":warnings[:2],"trend":trend}



