def _clamp(value, low, high):
    return max(low, min(high, value))


def history_delta(history, now, lookback=90.0):
    samples = [
        (float(t), float(v))
        for t, v in (history or [])
        if float(now) - float(t) <= float(lookback)
    ]
    if len(samples) < 2:
        return 0
    return int(samples[-1][1] - samples[0][1])


def momentum_descriptor(delta):
    delta = int(delta or 0)
    if delta >= 900:
        return "SURGING ↑↑"
    if delta >= 350:
        return "GAINING ↑"
    if delta <= -900:
        return "SLIDING ↓↓"
    if delta <= -350:
        return "LOSING ↓"
    return "STABLE →"


def strategy_mode(total_diff, momentum):
    total_diff = int(total_diff or 0)
    momentum = int(momentum or 0)
    if total_diff >= 2800 or (total_diff >= 1500 and momentum >= 900):
        return "SNOWBALL"
    if total_diff <= -2800 or (total_diff <= -1500 and momentum <= -900):
        return "COMEBACK"
    return "STABLE"


def game_state_confidence(our_map, enemy_map, all_players, lane_history):
    """
    Confidence in the dashboard state, not confidence that a team will win.
    It measures how complete/stable the visible live data is.
    """
    players = list(all_players or [])
    visible_count = min(10, len(players))
    mapped = sum(1 for position, _ in LANE_ORDER if our_map.get(position))
    mapped += sum(1 for position, _ in LANE_ORDER if enemy_map.get(position))

    history_ready = sum(
        1 for lane in ("TOP", "MID", "BOT")
        if len((lane_history or {}).get(lane, [])) >= 3
    )

    item_rows = sum(
        1 for player in players
        if isinstance(player.get("items"), list)
    )

    score = (
        35
        + (visible_count / 10.0) * 25
        + (mapped / 10.0) * 20
        + (history_ready / 3.0) * 12
        + (min(10, item_rows) / 10.0) * 8
    )
    score = int(round(_clamp(score, 35, 100)))

    label = "HIGH" if score >= 85 else "MED" if score >= 68 else "LOW"
    reason = (
        f"{visible_count}/10 players visible • {mapped}/10 roles mapped • "
        f"{history_ready}/3 lane trends established"
    )
    return score, label, reason


def role_strength_label(ours, enemy, dd, trend=0):
    our_gold = visible_inventory_gold(ours or {}, dd)
    enemy_gold = visible_inventory_gold(enemy or {}, dd)
    gd = our_gold - enemy_gold

    our_level = float((ours or {}).get("level", 0) or 0)
    enemy_level = float((enemy or {}).get("level", 0) or 0)
    ld = our_level - enemy_level

    _ok, _od, _oa, our_cs = score_line(ours or {})
    _ek, _ed, _ea, enemy_cs = score_line(enemy or {})
    csd = our_cs - enemy_cs

    score = gd / 1000.0 + ld * 0.65 + csd / 45.0 + int(trend or 0) / 1800.0

    if score >= 1.05:
        return "STRONG", GOOD, score
    if score <= -1.05:
        return "WEAK", DANGER, score
    return "NEUTRAL", ACCENT, score


def champion_threat_type(player, dd):
    champion = (player or {}).get("championName", "?")
    damage = damage_type(champion)
    _team, per_enemy = analyze_enemy_inventory([player or {}], dd)
    metrics = (per_enemy[0].get("metrics") if per_enemy else {}) or {}

    labels = []
    if damage == "AP":
        labels.append("AP")
    elif damage == "AD":
        labels.append("AD")
    elif damage == "MIXED":
        labels.append("MIXED")

    if float(metrics.get("crit", 0) or 0) >= 0.75:
        labels.append("CRIT")
    elif float(metrics.get("attack_speed", 0) or 0) >= 0.70:
        labels.append("AA/DPS")
    elif float(metrics.get("burst", 0) or 0) >= 0.60 or float(metrics.get("magic_burst", 0) or 0) >= 0.55:
        labels.append("BURST")

    if float(metrics.get("healing", 0) or 0) >= 0.55:
        labels.append("SUSTAIN")

    if champion in TRUE_DAMAGE_THREATS:
        labels.append("TRUE")

    if champion_in_list(champion, TRAITS.get("highCC", [])) and len(labels) < 3:
        labels.append("CC")

    if not labels:
        labels = ["GENERAL"]

    return " / ".join(labels[:3])


def objective_score_from_parts(total_diff, jungle, mid, side):
    # A visible-data fight-readiness score centered at 50.
    score = 50.0
    score += _clamp(total_diff / 4500.0, -1.0, 1.0) * 20.0
    score += _clamp(jungle / 1800.0, -1.0, 1.0) * 15.0
    score += _clamp(mid / 2200.0, -1.0, 1.0) * 7.5
    score += _clamp(side / 3200.0, -1.0, 1.0) * 7.5
    return int(round(_clamp(score, 0, 100)))


def objective_label(score):
    if score >= 66:
        return "FAVORABLE", GOOD
    if score <= 34:
        return "HIGH RISK", DANGER
    return "CONTESTABLE", ACCENT


def gank_profile_adjustment(champion, snapshot, dd, phase):
    profile = JUNGLE_GANK_PROFILES.get(champion)
    if not profile:
        return 0.0, []

    adjustment = float(profile.get("phase", {}).get(phase, 0.0) or 0.0)
    reasons = []

    setup = 0
    for player in snapshot.get("ours", []):
        name = player.get("championName", "")
        if name in GANK_SETUP_NAMES or champion_in_list(name, TRAITS.get("highCC", [])):
            setup += 1

    squishy = 0
    tanky = 0
    for player in snapshot.get("enemies", []):
        name = player.get("championName", "")
        tags = set(dd.champion_tags(name))
        if tags & SQUISHY_HINT_TAGS and name not in TANKISH_NAMES:
            squishy += 1
        if name in TANKISH_NAMES:
            tanky += 1

    if squishy:
        bonus = float(profile.get("squishy", 0.0) or 0.0) * squishy
        adjustment += bonus
        if bonus >= 0.15:
            reasons.append(f"{champion} profile likes vulnerable targets")

    if tanky:
        adjustment += float(profile.get("tank", 0.0) or 0.0) * tanky

    setup_need = float(profile.get("setup_need", 0.0) or 0.0)
    if setup_need > 0 and not setup:
        adjustment -= setup_need
        if setup_need >= 0.15:
            reasons.append(f"{champion} prefers more lane setup")
    elif setup_need < 0 and not setup:
        adjustment += abs(setup_need) * 0.5

    phase_bonus = float(profile.get("phase", {}).get(phase, 0.0) or 0.0)
    if abs(phase_bonus) >= 0.30:
        reasons.append(f"{phase.lower()} game fits {champion}'s gank profile")

    return adjustment, reasons[:2]


def rank_gank_lanes(
    our_map,
    enemy_map,
    dd,
    history,
    now,
    carry_lane=None,
    jungler_champion=None,
    strategy="STABLE",
):
    ranked = []
    phase = game_phase(now)

    for lane in ("TOP", "MID", "BOT"):
        snap = gank_lane_snapshot(
            lane,
            our_map,
            enemy_map,
            dd,
        )
        trend = lane_trend_from_history(
            history.get(lane, []),
            snap["gold_diff"],
            now,
        )
        result = gank_priority_score(
            snap,
            trend,
            dd,
        )

        # Champion-specific jungle identity.
        profile_adjustment, profile_reasons = gank_profile_adjustment(
            jungler_champion or "",
            snap,
            dd,
            phase,
        )
        result["score"] += profile_adjustment
        if profile_reasons:
            result["reasons"] = (
                profile_reasons
                + list(result.get("reasons") or [])
            )[:3]

        # Protect / snowball the strongest visible ally carry.
        if carry_lane and lane == carry_lane:
            result["score"] += 0.45
            result["reasons"] = (
                ["your strongest ally carry is on this side"]
                + list(result.get("reasons") or [])
            )[:3]

        # Strategic mode changes risk appetite.
        gd = snap.get("gold_diff", 0)
        if strategy == "SNOWBALL":
            if gd >= 250:
                result["score"] += 0.25
                result["reasons"] = (
                    ["snowball mode favors converting your strong side"]
                    + list(result.get("reasons") or [])
                )[:3]
            if result.get("risk") == "HIGH":
                result["score"] -= 0.25
        elif strategy == "COMEBACK":
            if result.get("risk") == "HIGH":
                result["score"] -= 0.65
                result["warnings"] = (
                    ["comeback mode avoids high-variance rescue ganks"]
                    + list(result.get("warnings") or [])
                )[:2]
            elif -1800 < gd < -250:
                result["score"] += 0.20
                result["reasons"] = (
                    ["comeback mode values a still-salvageable lane"]
                    + list(result.get("reasons") or [])
                )[:3]

        # Later game: isolated lane ganks lose relative value.
        if phase == "MID":
            result["score"] -= 0.15
        elif phase == "LATE":
            result["score"] -= 0.65
            result["warnings"] = (
                list(result.get("warnings") or [])
                + ["late game: grouped objective play has higher collapse risk"]
            )[:2]

        result["score"] = round(
            _clamp(float(result["score"]), 1.0, 9.8),
            1,
        )
        score = float(result["score"])
        result["priority"] = (
            "HIGH" if score >= 7.6
            else "MED" if score >= 6.0
            else "LOW"
        )
        result["lane"] = lane
        result["snapshot"] = snap
        result["phase"] = phase
        result["strategy"] = strategy
        result["jungler"] = jungler_champion or "-"
        result["momentum_label"] = momentum_descriptor(trend)
        ranked.append(result)

    risk_order = {"LOW": 0, "MED": 1, "HIGH": 2}
    ranked.sort(
        key=lambda item: (
            -item["score"],
            risk_order.get(item["risk"], 9),
            item["lane"],
        )
    )
    return ranked


def gank_opportunity_label(item):
    if item.get("risk") == "HIGH":
        return "HIGH RISK"
    score = float(item.get("score", 0) or 0)
    if score >= 7.3:
        return "FAVORABLE"
    if score >= 5.8:
        return "POSSIBLE"
    return "LOW VALUE"


def important_game_events(events):
    """Keep objective / major map events already exposed by Riot's event data."""
    allowed = {
        "DragonKill", "BaronKill", "HeraldKill", "HordeKill", "VoidGrubKill",
        "TurretKilled", "InhibKilled", "FirstBlood", "GameEnd",
    }
    return [event for event in (events or []) if event.get("EventName") in allowed]


def format_event_text(event):
    name = event.get("EventName", "Event")
    when = format_time(event.get("EventTime", 0))
    killer = event.get("KillerName") or event.get("Acer") or ""
    victim = event.get("VictimName") or ""
    if name == "DragonKill":
        dtype = event.get("DragonType") or "Dragon"
        detail = f"{dtype} killed"
    elif name == "BaronKill":
        detail = "Baron killed"
    elif name == "HeraldKill":
        detail = "Rift Herald killed"
    elif name in {"HordeKill", "VoidGrubKill"}:
        detail = "Void objective killed"
    elif name == "TurretKilled":
        detail = "Turret destroyed"
    elif name == "InhibKilled":
        detail = "Inhibitor destroyed"
    elif name == "FirstBlood":
        detail = "First Blood"
    elif name == "GameEnd":
        detail = "Game ended"
    else:
        detail = name
    actors = ""
    if killer and victim:
        actors = f" — {killer} → {victim}"
    elif killer:
        actors = f" — {killer}"
    return f"{when}  {detail}{actors}"



