def game_phase(game_time_seconds):
    seconds = float(game_time_seconds or 0)
    if seconds < 14 * 60:
        return "EARLY"
    if seconds < 28 * 60:
        return "MID"
    return "LATE"



RUNE_PAGE_DEFAULT_SHARDS = [
    5008,  # adaptive force
    5008,  # adaptive force
    5001,  # health scaling / defensive shard family
]


def rune_choices_for(
    champion,
):
    """
    Return the curated recommended + alternative rune choices for a champion.

    Profiles are intentionally local/editable. They are not presented as live
    patch win-rate statistics.
    """
    profile = (
        RUNE_PROFILES.get(
            champion,
            {}
        )
        or {}
    )

    recommended = (
        profile.get(
            "recommended"
        )
        or {}
    )
    alternative = (
        profile.get(
            "alternative"
        )
        or {}
    )

    if not recommended:
        preset = (
            DRAFT_LOADOUTS.get(
                champion,
                {}
            )
            or {}
        )
        rune_text = str(
            preset.get(
                "runes",
                "",
            )
            or ""
        ).strip()
        if rune_text:
            recommended = {
                "label": (
                    "Local champion preset"
                ),
                "runes": rune_text,
            }

    return {
        "recommended": recommended,
        "alternative": alternative,
    }


def rune_choices_for_role(
    champion,
    role,
):
    """Return rune choices that are valid for the requested role.

    Existing flat rune_profiles.json entries are legacy jungle presets. Future
    profiles may opt into a role-aware schema via ``roles: {ROLE: {...}}``.
    For non-jungle roles, never silently reuse a jungle preset.
    """
    role_key = draft_role_key(
        role
    )
    profile = (
        RUNE_PROFILES.get(
            champion,
            {},
        )
        or {}
    )
    role_profiles = (
        profile.get(
            "roles",
            {},
        )
        or {}
    )
    if role_key and role_key in role_profiles:
        role_profile = (
            role_profiles.get(
                role_key,
                {},
            )
            or {}
        )
        return {
            "recommended": role_profile.get(
                "recommended"
            )
            or {},
            "alternative": role_profile.get(
                "alternative"
            )
            or {},
        }

    if role_key == "JUNGLE":
        return rune_choices_for(
            champion
        )

    return {
        "recommended": {},
        "alternative": {},
    }


def parse_rune_profile_text(
    rune_text,
):
    text = str(
        rune_text
        or ""
    ).strip()

    if "|" not in text:
        return None, (
            "Rune profile must contain "
            "primary | secondary runes."
        )

    primary_text, secondary_text = (
        text.split(
            "|",
            1,
        )
    )

    def names(value):
        return [
            part.strip()
            for part in re.split(
                r"\s*[•·]\s*",
                value.strip(),
            )
            if part.strip()
        ]

    primary = names(
        primary_text
    )
    secondary = names(
        secondary_text
    )

    if len(primary) != 4:
        return None, (
            "Expected 4 primary runes; "
            f"found {len(primary)}."
        )

    if len(secondary) != 2:
        return None, (
            "Expected 2 secondary runes; "
            f"found {len(secondary)}."
        )

    return {
        "primary": primary,
        "secondary": secondary,
    }, ""


def build_rune_page_selection(
    dd,
    rune_text,
    stat_shards=None,
):
    parsed, error = parse_rune_profile_text(
        rune_text
    )
    if not parsed:
        return None, error

    if not dd.rune_name_to_id:
        if dd.version:
            dd.load_runes(
                dd.version
            )

    if not dd.rune_name_to_id:
        return None, (
            "Riot rune catalog is not loaded."
        )

    missing = []
    primary_ids = []
    secondary_ids = []

    for name in parsed[
        "primary"
    ]:
        rune_id = dd.rune_id_for_name(
            name
        )
        if not rune_id:
            missing.append(
                name
            )
        else:
            primary_ids.append(
                int(
                    rune_id
                )
            )

    for name in parsed[
        "secondary"
    ]:
        rune_id = dd.rune_id_for_name(
            name
        )
        if not rune_id:
            missing.append(
                name
            )
        else:
            secondary_ids.append(
                int(
                    rune_id
                )
            )

    if missing:
        return None, (
            "Rune names not found in current "
            "Riot Data Dragon: "
            + ", ".join(
                missing
            )
        )

    primary_slots = [
        dd.rune_slot_for_name(
            name
        )
        for name in parsed[
            "primary"
        ]
    ]
    secondary_slots = [
        dd.rune_slot_for_name(
            name
        )
        for name in parsed[
            "secondary"
        ]
    ]

    if (
        primary_slots != [
            0,
            1,
            2,
            3,
        ]
    ):
        return None, (
            "Primary rune profile must select "
            "one rune from each row in order."
        )

    if (
        any(
            slot is None
            or slot <= 0
            for slot in secondary_slots
        )
        or len(
            set(
                secondary_slots
            )
        ) != 2
    ):
        return None, (
            "Secondary runes must come from "
            "two different non-keystone rows."
        )

    primary_styles = {
        dd.rune_style_for_name(
            name
        )
        for name in parsed[
            "primary"
        ]
    }
    secondary_styles = {
        dd.rune_style_for_name(
            name
        )
        for name in parsed[
            "secondary"
        ]
    }
    primary_styles.discard(
        None
    )
    secondary_styles.discard(
        None
    )

    if len(
        primary_styles
    ) != 1:
        return None, (
            "Primary runes do not belong "
            "to one rune tree."
        )

    if len(
        secondary_styles
    ) != 1:
        return None, (
            "Secondary runes do not belong "
            "to one rune tree."
        )

    primary_style = next(
        iter(
            primary_styles
        )
    )
    secondary_style = next(
        iter(
            secondary_styles
        )
    )

    if (
        primary_style
        == secondary_style
    ):
        return None, (
            "Primary and secondary rune trees "
            "must be different."
        )

    shards = [
        int(
            shard
        )
        for shard in (
            stat_shards
            or RUNE_PAGE_DEFAULT_SHARDS
        )
        if int(
            shard
            or 0
        )
        > 0
    ][:3]

    while len(
        shards
    ) < 3:
        shards.append(
            RUNE_PAGE_DEFAULT_SHARDS[
                len(
                    shards
                )
            ]
        )

    return {
        "primaryStyleId": int(
            primary_style
        ),
        "subStyleId": int(
            secondary_style
        ),
        "selectedPerkIds": (
            primary_ids
            + secondary_ids
            + shards
        ),
        "primaryNames": parsed[
            "primary"
        ],
        "secondaryNames": parsed[
            "secondary"
        ],
        "statShards": shards,
    }, ""


def draft_team_identity(champion_names):
    names = [name for name in champion_names if name]
    if not names:
        return {
            "labels": ["Unknown"],
            "strengths": [],
            "weaknesses": ["not enough visible picks"],
            "text": "Unknown",
        }

    needs = team_needs(names)
    counts = {
        "Dive": sum(name in DRAFT_DIVE_NAMES for name in names),
        "Teamfight": sum(name in DRAFT_AOE_NAMES for name in names),
        "Pick": sum(name in DRAFT_PICK_NAMES for name in names),
        "Poke": sum(name in DRAFT_POKE_NAMES for name in names),
        "Protect/Scale": sum(name in DRAFT_PROTECT_NAMES or name in HYPERCARRY_ALLIES for name in names),
    }

    labels = [
        label for label, _count in sorted(
            counts.items(),
            key=lambda pair: (-pair[1], pair[0]),
        )
        if _count > 0
    ][:2]
    if not labels:
        labels = ["Balanced"]

    strengths = []
    if needs["frontline"] >= 1:
        strengths.append("frontline")
    if needs["engage"] >= 1:
        strengths.append("engage")
    if needs["cc"] >= 2:
        strengths.append("CC")
    if needs["ap"] >= 1 and needs["ad"] >= 1:
        strengths.append("mixed damage")
    if counts["Teamfight"] >= 2:
        strengths.append("AoE follow-up")

    weaknesses = []
    if needs["frontline"] == 0:
        weaknesses.append("low frontline")
    if needs["engage"] == 0:
        weaknesses.append("low engage")
    if needs["ap"] == 0:
        weaknesses.append("no visible AP")
    if needs["ad"] == 0:
        weaknesses.append("no visible AD")
    if not any(name in DRAFT_PROTECT_NAMES for name in names):
        weaknesses.append("limited disengage/protection")

    return {
        "labels": labels,
        "strengths": strengths[:3],
        "weaknesses": weaknesses[:2],
        "text": " / ".join(labels),
    }


def draft_loadout_for(
    champion,
    enemy_names,
    dd,
    role=None,
):
    role_key = draft_role_key(
        role
    )
    preset = (
        DRAFT_LOADOUTS.get(
            champion,
            {},
        )
        or {}
    )
    role_presets = (
        preset.get(
            "roles",
            {},
        )
        or {}
    )
    if role_key and role_key in role_presets:
        preset = (
            role_presets.get(
                role_key,
                {},
            )
            or {}
        )
    elif role_key != "JUNGLE":
        # Existing flat draft_loadouts.json entries are jungle presets.
        preset = {}

    rune_choices = rune_choices_for_role(
        champion,
        role_key,
    )
    recommended_runes = (
        (
            rune_choices.get(
                "recommended"
            )
            or {}
        ).get(
            "runes"
        )
        or preset.get(
            "runes"
        )
        or ""
    )

    if role_key == "JUNGLE":
        default_summoners = "Flash + Smite"
    elif role_key:
        default_summoners = "Role-dependent summoners"
    else:
        default_summoners = "Summoners unavailable until role is known"

    if not preset and not recommended_runes:
        return {
            "champion": champion,
            "runes": "No role-specific local rune preset",
            "summoners": default_summoners,
            "note": "no role-specific preset; auto import blocked",
        }

    shape = enemy_shape(
        enemy_names,
        dd,
    )
    note_bits = []
    if shape["high_cc"] >= 3:
        note_bits.append(
            "enemy CC is high"
        )
    if shape["squishy"] >= 3:
        note_bits.append(
            "enemy team is relatively squishy"
        )
    if shape["tanks"] >= 2:
        note_bits.append(
            "enemy team has multiple tanks"
        )

    return {
        "champion": champion,
        "runes": recommended_runes or "-",
        "summoners": preset.get(
            "summoners",
            default_summoners,
        ),
        "note": (
            ", ".join(
                note_bits
            )
            if note_bits
            else "standard local preset"
        ),
    }


def player_power_score(player, dd):
    gold = visible_inventory_gold(player or {}, dd)
    kills, deaths, assists, cs = score_line(player or {})
    level = float((player or {}).get("level", 0) or 0)

    # A transparent heuristic, not MMR/win probability.
    score = (
        gold / 1000.0
        + kills * 0.58
        + assists * 0.18
        - deaths * 0.22
        + level * 0.08
        + cs * 0.0025
    )
    return round(score, 2)


def duel_matchup_state(
    active_player,
    enemy,
    dd,
):
    """
    Estimate whether YOU are currently stronger than one visible enemy.

    This is intentionally separate from lane power. Lane power compares the two
    players assigned to the same role; this duel state compares the active
    player directly against each enemy so the enemy column can answer the user's
    practical "who can I 1v1?" question.

    It is a visible-data heuristic, not a guaranteed duel outcome. It cannot know
    hidden cooldowns, summoner spells, exact spell availability, nearby allies,
    fog-of-war information or player execution.
    """
    if not active_player or not enemy:
        return {
            "label": "WAITING",
            "color": MUTED,
            "bg": PANEL_ALT,
            "score": 0.0,
            "power_diff": 0.0,
            "gold_diff": 0,
            "level_diff": 0.0,
            "reason": "Waiting for both players.",
        }

    our_power = float(
        player_power_score(
            active_player,
            dd,
        )
    )
    enemy_power = float(
        player_power_score(
            enemy,
            dd,
        )
    )
    power_diff = (
        our_power
        - enemy_power
    )

    our_gold = visible_inventory_gold(
        active_player,
        dd,
    )
    enemy_gold = visible_inventory_gold(
        enemy,
        dd,
    )
    gold_diff = (
        our_gold
        - enemy_gold
    )

    our_level = float(
        active_player.get(
            "level",
            0,
        )
        or 0
    )
    enemy_level = float(
        enemy.get(
            "level",
            0,
        )
        or 0
    )
    level_diff = (
        our_level
        - enemy_level
    )

    # player_power_score already contains visible items / KDA / level / CS.
    # Gold and level get only a small extra weight here so a clear item/level
    # breakpoint matters without being counted twice too aggressively.
    duel_score = (
        power_diff
        + gold_diff / 2500.0
        + level_diff * 0.28
    )

    if duel_score >= 1.0:
        label = "FAVORABLE"
        color = GOOD
        bg = POS_BG
    elif duel_score <= -1.0:
        label = "RISKY"
        color = DANGER
        bg = NEG_BG
    else:
        label = "CLOSE"
        color = ACCENT
        bg = TIE_BG

    return {
        "label": label,
        "color": color,
        "bg": bg,
        "score": round(
            duel_score,
            2,
        ),
        "power_diff": round(
            power_diff,
            2,
        ),
        "gold_diff": int(
            gold_diff
        ),
        "level_diff": round(
            level_diff,
            1,
        ),
        "reason": (
            f"YOU vs {enemy.get('championName', '?')} • "
            f"power Δ {power_diff:+.2f} • "
            f"items {signed_gold(gold_diff)} • "
            f"level Δ {level_diff:+.0f}"
        ),
    }


def rank_live_players(players, dd):
    ranked = []
    for player in players:
        ranked.append({
            "champion": player.get("championName", "?"),
            "position": str(player.get("position") or "").upper(),
            "item_gold": visible_inventory_gold(player, dd),
            "power": player_power_score(player, dd),
            "threat_type": champion_threat_type(player, dd),
            "player": player,
        })
    ranked.sort(
        key=lambda item: (
            -item["power"],
            -item["item_gold"],
            item["champion"],
        )
    )
    return ranked


def position_to_gank_lane(position):
    position = str(position or "").upper()
    if position == "TOP":
        return "TOP"
    if position == "MIDDLE":
        return "MID"
    if position in {"BOTTOM", "UTILITY"}:
        return "BOT"
    return None


def primary_threat_adjusted_options(options, per_enemy, threat_ranking):
    """
    Add a small main-carry weight to situational item scoring.

    The team-wide threat model remains the base. This only breaks close ties in
    favor of answers to the enemy who is currently strongest.
    """
    if not options or not threat_ranking:
        return options

    primary = threat_ranking[0]
    champion = primary.get("champion")
    info = next(
        (entry for entry in per_enemy if entry.get("champion") == champion),
        None,
    )
    if not info:
        return options

    local_metrics = info.get("metrics", {}) or {}
    adjusted = []

    for option in options:
        item = dict(option)
        weights = ADAPTIVE_ITEM_WEIGHTS.get(item.get("name"), {})
        bonus = 0.0

        for metric_name, weight in weights.items():
            threshold = THREAT_THRESHOLDS.get(metric_name, 1.0)
            local_value = float(local_metrics.get(metric_name, 0.0) or 0.0)
            local_norm = max(0.0, min(1.0, local_value / max(0.01, threshold * 0.45)))
            bonus += float(weight) * local_norm * 0.23

        bonus = min(0.75, bonus)
        if bonus >= 0.12:
            item["score"] = round(min(9.8, float(item.get("score", 0)) + bonus), 1)
            reasons = list(item.get("reasons") or [])
            reasons.insert(0, f"answers primary threat {champion}")
            item["reasons"] = reasons[:2]

        adjusted.append(item)

    adjusted.sort(key=lambda item: (-float(item.get("score", 0)), item.get("name", "")))
    return adjusted


def add_option_confidence(options):
    """
    Relative heuristic confidence. This is NOT a win-rate probability.
    """
    if not options:
        return options

    scores = [float(option.get("score", 0) or 0) for option in options]
    top = max(scores)

    for index, option in enumerate(options):
        score = float(option.get("score", 0) or 0)
        next_best = max(
            [other for i, other in enumerate(scores) if i != index] or [score]
        )
        separation = max(0.0, score - next_best) if score >= top else max(0.0, top - score)
        if score >= top:
            confidence = 58 + (score - 5.0) * 7.0 + separation * 8.0
        else:
            confidence = 52 + (score - 5.0) * 6.0 - (top - score) * 8.0
        option["confidence"] = int(max(45, min(95, round(confidence))))

    return options


def build_response_text(metrics):
    signals = []

    if float(metrics.get("healing", 0) or 0) >= 1.1:
        signals.append("SUSTAIN HIGH → anti-heal gains value")
    if float(metrics.get("armor", 0) or 0) >= 1.5:
        signals.append("ARMOR HIGH → armor penetration / Black Cleaver gains value")
    if float(metrics.get("magic", 0) or 0) >= 5.0 or float(metrics.get("magic_burst", 0) or 0) >= 1.6:
        signals.append("MAGIC HIGH → MR option gains value")
    if float(metrics.get("physical", 0) or 0) >= 5.0:
        signals.append("PHYSICAL HIGH → armor option gains value")
    if float(metrics.get("crit", 0) or 0) >= 1.5:
        signals.append("CRIT HIGH → anti-crit armor gains value")
    if float(metrics.get("attack_speed", 0) or 0) >= 1.8:
        signals.append("ATTACK SPEED HIGH → anti-AA defense gains value")

    if not signals:
        return "COUNTER RESPONSE: no extreme itemization signal yet"

    return "COUNTER RESPONSE: " + "  |  ".join(signals[:3])


def _profile_boot_candidates(
    profile,
    enemies,
):
    _path, _title, _items, boots, _comp = chosen_baseline_path(
        profile,
        enemies,
    )
    result = []
    for name in boots:
        name = str(
            name
            or ""
        ).strip()
        if (
            name
            and normalize_name(
                name
            )
            not in {
                normalize_name(
                    existing
                )
                for existing in result
            }
        ):
            result.append(
                name
            )
    return result


def _fallback_boot_name(
    profile,
    enemies,
):
    """
    Pick a deterministic boot name without requiring Data Dragon metadata.

    This is used only while current-patch item data is still loading. The
    recommendation is revalidated and rerendered as soon as Data Dragon is
    available, but slot 1 never disappears from the build in the meantime.
    """
    comp = live_composition(
        enemies
    )
    candidates = _profile_boot_candidates(
        profile,
        enemies,
    )

    # Prefer the profile's own path first.
    if candidates:
        return candidates[
            0
        ]

    # Conservative emergency fallback for a profile with incomplete boot data.
    if (
        comp.get(
            "CC",
            0,
        )
        >= 3
        or comp.get(
            "AP",
            0,
        )
        > comp.get(
            "AD",
            0,
        )
    ):
        return "Mercury's Treads"

    return "Plated Steelcaps"


def adaptive_boot_choice(
    champion,
    profile,
    player_items,
    enemies,
    dd,
):
    owned = completed_item_names(
        player_items,
        dd,
    )
    owned_boots = [
        name
        for name in owned
        if is_boot_item_name(
            name
        )
    ]
    if owned_boots:
        return (
            owned_boots[
                0
            ],
            "OWNED",
        )

    metrics, _per_enemy = analyze_enemy_inventory(
        enemies,
        dd,
    )
    comp = live_composition(
        enemies
    )

    physical_pressure = (
        float(
            metrics.get(
                "physical",
                0,
            )
            or 0
        )
        + float(
            metrics.get(
                "crit",
                0,
            )
            or 0
        )
        * 1.5
        + float(
            metrics.get(
                "attack_speed",
                0,
            )
            or 0
        )
        * 1.1
    )
    magic_pressure = (
        float(
            metrics.get(
                "magic",
                0,
            )
            or 0
        )
        + float(
            metrics.get(
                "magic_burst",
                0,
            )
            or 0
        )
        * 1.4
        + float(
            comp.get(
                "CC",
                0,
            )
            or 0
        )
        * 0.55
    )

    # Item metadata may be unavailable for a few seconds after a patch refresh.
    # Never suppress the boots slot because of that transient state.
    item_data_ready = bool(
        getattr(
            dd,
            "item_data",
            None,
        )
    )

    preferred = []

    if (
        magic_pressure
        >= physical_pressure
        * 1.08
        or comp.get(
            "CC",
            0,
        )
        >= 3
    ):
        preferred.append(
            (
                "Mercury's Treads",
                "ADAPTIVE BOOTS",
            )
        )

    if (
        physical_pressure
        > magic_pressure
    ):
        preferred.append(
            (
                "Plated Steelcaps",
                "ADAPTIVE BOOTS",
            )
        )

    for boot_name in _profile_boot_candidates(
        profile,
        enemies,
    ):
        preferred.append(
            (
                boot_name,
                "BASELINE BOOTS",
            )
        )

    # Deduplicate while preserving priority.
    seen = set()
    ordered = []
    for boot_name, source in preferred:
        key = normalize_name(
            boot_name
        )
        if (
            not key
            or key in seen
        ):
            continue
        seen.add(
            key
        )
        ordered.append(
            (
                boot_name,
                source,
            )
        )

    if item_data_ready:
        for boot_name, source in ordered:
            if current_sr_item_id(
                dd,
                boot_name,
                require_completed=False,
            ):
                return (
                    boot_name,
                    source,
                )

    # Data Dragon is not ready, or its current item cache is being repaired.
    # Show a named boot recommendation immediately and let the next refresh
    # attach the current-patch item id/icon.
    fallback = (
        ordered[
            0
        ][
            0
        ]
        if ordered
        else _fallback_boot_name(
            profile,
            enemies,
        )
    )
    return (
        fallback,
        "BOOTS • LOADING DATA"
        if not item_data_ready
        else "BASELINE BOOTS",
    )



def objective_fight_readiness(our_map, enemy_map, dd, game_time_seconds):
    def lane_diff(position):
        ours = our_map.get(position)
        enemy = enemy_map.get(position)
        return (
            visible_inventory_gold(ours or {}, dd)
            - visible_inventory_gold(enemy or {}, dd)
        )

    total_our = sum(
        visible_inventory_gold(player, dd)
        for player in our_map.values()
        if player
    )
    total_enemy = sum(
        visible_inventory_gold(player, dd)
        for player in enemy_map.values()
        if player
    )
    total_diff = total_our - total_enemy

    jungle = lane_diff("JUNGLE")
    mid = lane_diff("MIDDLE")
    bot = lane_diff("BOTTOM") + lane_diff("UTILITY")
    top = lane_diff("TOP")

    dragon_score = objective_score_from_parts(
        total_diff,
        jungle,
        mid,
        bot,
    )
    dragon_label, dragon_color = objective_label(dragon_score)

    if float(game_time_seconds or 0) < 20 * 60:
        baron_score = objective_score_from_parts(
            total_diff,
            jungle,
            mid,
            top,
        )
        baron_label, baron_color = "LATER", MUTED
    else:
        baron_score = objective_score_from_parts(
            total_diff,
            jungle,
            mid,
            top,
        )
        baron_label, baron_color = objective_label(baron_score)

    return {
        "dragon": dragon_label,
        "dragon_color": dragon_color,
        "dragon_score": dragon_score,
        "dragon_breakdown": {
            "team": total_diff,
            "jungle": jungle,
            "mid": mid,
            "side": bot,
            "side_label": "BOT+SUPPORT",
        },
        "baron": baron_label,
        "baron_color": baron_color,
        "baron_score": baron_score,
        "baron_breakdown": {
            "team": total_diff,
            "jungle": jungle,
            "mid": mid,
            "side": top,
            "side_label": "TOP",
        },
    }


def game_state_label(total_diff):
    if total_diff >= 1800:
        return "AHEAD", GOOD
    if total_diff <= -1800:
        return "BEHIND", DANGER
    return "EVEN", ACCENT



def live_composition(enemies):
    ap = ad = cc = unknown = 0
    for enemy in enemies:
        name = enemy.get("championName", "")
        dt = damage_type(name)
        if dt in {"AP", "MIXED"}:
            ap += 1
        if dt in {"AD", "MIXED"}:
            ad += 1
        if dt == "UNKNOWN":
            unknown += 1
        if champion_in_list(name, TRAITS.get("highCC", [])):
            cc += 1
    return {"AP": ap, "AD": ad, "CC": cc, "Unknown": unknown}



def strip_html(text):
    """Small dependency-free HTML tag remover for Data Dragon descriptions."""
    text = text or ""
    return re.sub(r"<[^>]+>", " ", text).replace("&nbsp;", " ").replace("&amp;", "&")


def item_meta_from_live_item(dd, live_item):
    item_id = str(live_item.get("itemID", "") or "")
    if not item_id:
        return {}
    return dd.item_data.get(item_id, {}) or {}


def empty_threat_metrics():
    return {
        "physical": 0.0,
        "magic": 0.0,
        "crit": 0.0,
        "attack_speed": 0.0,
        "healing": 0.0,
        "armor": 0.0,
        "mr": 0.0,
        "cc": 0.0,
        "burst": 0.0,
        "magic_burst": 0.0,
        "visible_items": 0,
    }


def add_threat_metrics(target, source):
    for key in target:
        target[key] += float(source.get(key, 0.0) or 0.0)


def analyze_enemy_inventory(enemies, dd):
    """
    Build both team-wide and per-enemy threat profiles from scoreboard-visible
    champions and item inventories.
    """
    metrics = empty_threat_metrics()
    per_enemy = []

    for enemy in enemies:
        champion = enemy.get("championName", "?")
        dt = damage_type(champion)
        local = empty_threat_metrics()

        # Champion baseline keeps the panel useful before completed items appear.
        if dt in {"AD", "MIXED"}:
            local["physical"] += 1.0
        if dt in {"AP", "MIXED"}:
            local["magic"] += 1.0
        if champion_in_list(champion, TRAITS.get("highCC", [])):
            local["cc"] += 1.0

        enemy_items = []

        for live_item in enemy.get("items") or []:
            item_id = live_item.get("itemID")
            if not item_id:
                continue

            live_name = live_item.get("displayName", "")
            if normalize_name(live_name) in {
                "warding totem (trinket)",
                "oracle lens",
                "farsight alteration",
            }:
                continue

            meta = item_meta_from_live_item(dd, live_item)
            name = meta.get("name") or live_name or str(item_id)
            stats = meta.get("stats", {}) or {}
            description = strip_html(meta.get("description", "")).lower()
            tags = set(meta.get("tags", []) or [])

            if "Consumable" in tags:
                continue

            local["visible_items"] += 1
            enemy_items.append((item_id, name))

            ad = float(stats.get("FlatPhysicalDamageMod", 0) or 0)
            ap = float(stats.get("FlatMagicDamageMod", 0) or 0)
            crit = float(stats.get("FlatCritChanceMod", 0) or 0)
            attack_speed = float(stats.get("PercentAttackSpeedMod", 0) or 0)
            armor = float(stats.get("FlatArmorMod", 0) or 0)
            mr = float(stats.get("FlatSpellBlockMod", 0) or 0)
            lifesteal = float(stats.get("PercentLifeStealMod", 0) or 0)

            local["physical"] += min(ad / 45.0, 1.6)
            local["magic"] += min(ap / 80.0, 1.6)
            local["crit"] += max(0.0, crit * 4.0)
            local["attack_speed"] += max(0.0, attack_speed * 2.0)
            local["armor"] += max(0.0, armor / 60.0)
            local["mr"] += max(0.0, mr / 50.0)

            if lifesteal > 0:
                local["healing"] += min(1.0, lifesteal * 5.0)

            if "omnivamp" in description or "life steal" in description:
                local["healing"] += 0.45
            if "critical strike" in description and crit <= 0:
                local["crit"] += 0.35
            if "attack speed" in description and attack_speed <= 0:
                local["attack_speed"] += 0.25
            if "lethality" in description or "armor penetration" in description:
                local["physical"] += 0.35
                local["burst"] += 0.35
            if "magic penetration" in description:
                local["magic"] += 0.35
                local["magic_burst"] += 0.35

            if ad >= 50 or ap >= 90:
                local["burst"] += 0.25
            if ap >= 90:
                local["magic_burst"] += 0.20

        add_threat_metrics(metrics, local)

        per_enemy.append({
            "champion": champion,
            "items": enemy_items,
            "metrics": local,
            "damage_type": dt,
        })

    return metrics, per_enemy

def normalized_threat(metric_name, metrics):
    threshold = THREAT_THRESHOLDS.get(metric_name, 1.0)
    value = float(metrics.get(metric_name, 0.0) or 0.0)
    return max(0.0, min(1.0, value / threshold))


THREAT_REASON_TEXT = {
    "physical": "visible enemy builds lean toward physical damage",
    "magic": "visible enemy builds lean toward magic damage",
    "crit": "the enemy team is building notable critical-strike chance",
    "attack_speed": "enemy items show strong attack-speed/basic-attack pressure",
    "healing": "enemy items show meaningful lifesteal or sustain",
    "armor": "the enemy team is stacking armor",
    "mr": "the enemy team is stacking magic resistance",
    "cc": "the enemy composition has heavy crowd control",
    "burst": "visible offensive items indicate higher burst pressure",
    "magic_burst": "visible AP/penetration items indicate magic burst pressure",
}


def generic_item_threat_fit(
    item_name,
    metrics,
    dd,
):
    item_id = dd.item_id_for_name(
        item_name
    )
    meta = (
        dd.item_data.get(
            str(
                item_id
            ),
            {},
        )
        or {}
    )
    stats = (
        meta.get(
            "stats",
            {}
        )
        or {}
    )
    description = re.sub(
        r"<[^>]+>",
        " ",
        str(
            meta.get(
                "description",
                "",
            )
            or ""
        ),
    ).lower()

    fit = 0.38

    armor = float(
        stats.get(
            "FlatArmorMod",
            0,
        )
        or 0
    )
    mr = float(
        stats.get(
            "FlatSpellBlockMod",
            0,
        )
        or 0
    )

    if armor > 0:
        fit += 0.32 * normalized_threat(
            "physical",
            metrics,
        )
        fit += 0.10 * normalized_threat(
            "crit",
            metrics,
        )
    if mr > 0:
        fit += 0.34 * normalized_threat(
            "magic",
            metrics,
        )
        fit += 0.12 * normalized_threat(
            "magic_burst",
            metrics,
        )
    if (
        "armor penetration"
        in description
        or "lethality"
        in description
    ):
        fit += 0.28 * normalized_threat(
            "armor",
            metrics,
        )
    if (
        "grievous wounds"
        in description
    ):
        fit += 0.32 * normalized_threat(
            "healing",
            metrics,
        )
    if (
        "spell shield"
        in description
        or "spellshield"
        in description
    ):
        fit += 0.24 * normalized_threat(
            "cc",
            metrics,
        )
    if (
        "attack speed"
        in description
        and armor > 0
    ):
        fit += 0.18 * normalized_threat(
            "attack_speed",
            metrics,
        )

    return max(
        0.0,
        min(
            1.0,
            fit,
        ),
    )


def adaptive_item_options(
    champion,
    player_items,
    enemies,
    dd,
    allies=None,
    strategy_mode="STABLE",
):
    """
    Return up to 3 situational item options.

    V51 ranking blend:
      35% current meta consensus
      25% team-role/composition fit
      20% visible enemy matchup/threat fit
      15% descriptive personal-history signal
       5% current live-game state

    Missing online data is neutral rather than fatal; the curated local profile
    remains a fallback.
    """
    metrics, per_enemy = analyze_enemy_inventory(
        enemies,
        dd,
    )
    identity = live_build_identity(
        champion,
        allies or [],
        enemies,
        dd,
    )
    mode = identity.get(
        "mode",
        "PROFILE",
    )

    if (
        mode == "ASSASSIN"
        and champion in ASSASSIN_BUILD_POOLS
    ):
        pool = list(
            ASSASSIN_BUILD_POOLS[
                champion
            ]
        )
        weight_map = ASSASSIN_THREAT_WEIGHTS
        base_bonus_map = ASSASSIN_BASE_BONUS
    else:
        pool = list(
            ADAPTIVE_ITEM_POOLS.get(
                champion,
                [],
            )
        )
        weight_map = ADAPTIVE_ITEM_WEIGHTS
        base_bonus_map = {}

    meta_payload = load_meta_consensus(
        champion
    )
    meta_candidates = meta_build_candidates(
        champion
    )

    # Meta data proposes candidates; team-role fit still has veto power.
    for item_name in meta_candidates:
        if normalize_name(
            item_name
        ) in {
            normalize_name(
                existing
            )
            for existing in pool
        }:
            continue
        if not current_sr_item_id(
            dd,
            item_name,
            require_completed=True,
        ):
            continue
        role_fit = item_role_fit(
            champion,
            item_name,
            mode,
            dd,
        )
        if mode == "ASSASSIN":
            if (
                not is_assassin_offensive_item(
                    item_name,
                    dd,
                )
                and not is_assassin_defensive_item(
                    item_name
                )
            ):
                continue
            if (
                role_fit < 0.42
                and not is_assassin_defensive_item(
                    item_name
                )
            ):
                continue
        pool.append(
            item_name
        )

    owned_names = set()
    for live_item in player_items or []:
        meta = item_meta_from_live_item(
            dd,
            live_item,
        )
        name = (
            meta.get(
                "name"
            )
            or live_item.get(
                "displayName"
            )
            or ""
        )
        if name:
            owned_names.add(
                normalize_name(
                    name
                )
            )

    scored = []
    for order, item_name in enumerate(
        pool
    ):
        if normalize_name(
            item_name
        ) in owned_names:
            continue

        item_id = current_sr_item_id(
            dd,
            item_name,
            require_completed=True,
        )
        if not item_id:
            continue

        weights = weight_map.get(
            item_name,
            {},
        )
        contributions = []
        weighted_threat = 0.0

        for metric_name, weight in weights.items():
            contribution = (
                float(
                    weight
                )
                * normalized_threat(
                    metric_name,
                    metrics,
                )
            )
            if contribution > 0:
                contributions.append(
                    (
                        contribution,
                        metric_name,
                    )
                )
                weighted_threat += contribution

        known_threat_fit = min(
            1.0,
            weighted_threat / 1.35,
        )
        generic_fit = generic_item_threat_fit(
            item_name,
            metrics,
            dd,
        )
        threat_fit = max(
            known_threat_fit,
            generic_fit,
        )

        raw_meta_fit = meta_item_score(
            champion,
            item_name,
        )
        if meta_payload:
            meta_fit = (
                raw_meta_fit
                if raw_meta_fit > 0
                else 0.22
            )
        else:
            meta_fit = 0.50

        role_fit = item_role_fit(
            champion,
            item_name,
            mode,
            dd,
        )
        personal_fit = personal_item_signal(
            champion,
            item_name,
            dd,
        )
        live_fit = item_live_state_fit(
            item_name,
            mode,
            strategy_mode,
            dd,
        )

        blended = (
            0.35 * meta_fit
            + 0.25 * role_fit
            + 0.20 * threat_fit
            + 0.15 * personal_fit
            + 0.05 * live_fit
        )

        # Small curated-profile prior prevents a weak/partial scrape from
        # immediately replacing a known-valid local champion item.
        curated = item_name in (
            ADAPTIVE_ITEM_POOLS.get(
                champion,
                []
            )
            + ASSASSIN_BUILD_POOLS.get(
                champion,
                []
            )
        )
        base_bonus = min(
            0.35,
            float(
                base_bonus_map.get(
                    item_name,
                    0.0,
                )
                or 0.0
            )
            * 0.12,
        )
        score = (
            4.0
            + blended * 6.0
            + (
                0.12
                if curated
                else 0.0
            )
            + base_bonus
        )

        contributions.sort(
            reverse=True
        )
        reasons = []

        source_count = int(
            (
                meta_payload.get(
                    "item_source_count",
                    {}
                )
                or {}
            ).get(
                item_name,
                0,
            )
            or 0
        )
        if (
            raw_meta_fit >= 0.45
            and source_count
        ):
            reasons.append(
                (
                    f"meta consensus {source_count}/"
                    f"{meta_payload.get('source_count', source_count)} sources"
                )
            )

        for contribution, metric_name in contributions:
            if (
                contribution >= 0.12
                and len(
                    reasons
                )
                < 2
            ):
                reasons.append(
                    THREAT_REASON_TEXT.get(
                        metric_name,
                        metric_name,
                    )
                )

        if (
            len(
                reasons
            )
            < 2
            and role_fit >= 0.72
        ):
            reasons.append(
                (
                    f"fits {mode.lower()} job for this team"
                    if mode
                    in {
                        "ASSASSIN",
                        "BRUISER",
                    }
                    else "fits the current champion role"
                )
            )

        if (
            len(
                reasons
            )
            < 2
            and personal_fit >= 0.56
        ):
            reasons.append(
                "positive signal in your saved ranked history"
            )

        if not reasons:
            reasons = [
                "balanced fit across meta, composition and visible threats"
            ]

        scored.append({
            "name": item_name,
            "item_id": item_id,
            "score": round(
                min(
                    9.8,
                    score,
                ),
                1,
            ),
            "reasons": reasons[:2],
            "build_mode": mode,
            "identity_reason": identity.get(
                "reason",
                "",
            ),
            "meta_fit": round(
                meta_fit,
                3,
            ),
            "role_fit": round(
                role_fit,
                3,
            ),
            "threat_fit": round(
                threat_fit,
                3,
            ),
            "personal_fit": round(
                personal_fit,
                3,
            ),
            "live_fit": round(
                live_fit,
                3,
            ),
            "_order": order,
        })

    scored.sort(
        key=lambda item: (
            -item[
                "score"
            ],
            item.get(
                "_order",
                0,
            ),
        )
    )

    for item in scored:
        item.pop(
            "_order",
            None,
        )

    return (
        scored[:3],
        metrics,
        per_enemy,
        identity,
    )



def threat_level(value, medium, high):
    if value >= high:
        return "HIGH"
    if value >= medium:
        return "MED"
    return "LOW"


def threat_summary_text(metrics):
    physical = threat_level(metrics.get("physical", 0), 3.5, 6.0)
    magic = threat_level(metrics.get("magic", 0), 3.5, 6.0)
    crit = threat_level(metrics.get("crit", 0), 0.8, 1.8)
    healing = threat_level(metrics.get("healing", 0), 0.5, 1.3)
    armor = threat_level(metrics.get("armor", 0), 0.8, 1.8)
    attack_speed = threat_level(metrics.get("attack_speed", 0), 0.8, 2.0)

    return (
        f"Threat profile • PHY {physical} • MAGIC {magic} • CRIT {crit} • "
        f"AS {attack_speed} • SUSTAIN {healing} • ARMOR {armor}"
    )




def smite_spell_info(player):
    spells = player.get("summonerSpells") or {}
    for spell in (
        spells.get("summonerSpellOne") or {},
        spells.get("summonerSpellTwo") or {},
    ):
        # `displayName` can be localized. Always inspect Riot's raw fields as
        # well so a non-English client cannot make the jungler disappear.
        name = str(
            spell.get("displayName")
            or spell.get("rawDisplayName")
            or ""
        )
        combined = " ".join(
            str(spell.get(key) or "")
            for key in (
                "displayName",
                "rawDisplayName",
                "description",
                "rawDescription",
            )
        ).lower()

        if "smite" not in combined:
            continue

        # Final jungle quest evolution. Current seasonal tuning uses the fully
        # upgraded Smite at 1400 monster damage; "Primal Smite" remains a useful
        # explicit signal where the Live Client exposes the display name.
        if "primal smite" in combined or "1400" in combined:
            return {
                "has_smite": True,
                "state": "completed",
                "name": name or "Primal Smite",
            }

        if "unleashed smite" in combined or "1000" in combined:
            return {
                "has_smite": True,
                "state": "evolving",
                "name": name or "Unleashed Smite",
            }

        return {
            "has_smite": True,
            "state": "base",
            "name": name or "Smite",
        }

    return {
        "has_smite": False,
        "state": "none",
        "name": "",
    }


def player_has_smite(player):
    return smite_spell_info(player)["has_smite"]


def jungle_quest_completed(player):
    return smite_spell_info(player)["state"] == "completed"


def owned_jungle_companion(player_items, dd):
    """
    Detect the selected jungle companion from visible inventory.

    Match both the current starter names and companion-family names so a Riot
    naming change / evolved inventory label does not leave all three choices visible.
    """
    exact_names = {
        normalize_name(data["name"]): color
        for color, data in JUNGLE_COMPANIONS.items()
    }
    family_tokens = {
        "gustwalker": "Blue",
        "mosstomper": "Green",
        "scorchclaw": "Red",
    }

    for item in player_items or []:
        item_id = item.get("itemID")
        name = item.get("displayName") or (
            dd.item_name(item_id) if item_id else ""
        )
        normalized = normalize_name(name)

        color = exact_names.get(normalized)
        if color:
            return color

        for token, token_color in family_tokens.items():
            if token in normalized:
                return token_color

    return None


def score_jungle_companions(champion, enemies):
    """
    Rank Blue / Green / Red using champion preference plus current enemy composition.
    """
    comp = live_composition(enemies)
    prefs = JUNGLE_COMPANION_PREFERENCES.get(
        champion,
        {"Blue": 0.45, "Green": 0.45, "Red": 0.45},
    )

    enemy_names = [x.get("championName", "") for x in enemies]
    tanky = sum(name in TANKISH_NAMES for name in enemy_names)
    squishy = sum(
        1 for name in enemy_names
        if name and name not in TANKISH_NAMES
    )

    scores = {}
    reasons = {"Blue": [], "Green": [], "Red": []}

    for color in ("Blue", "Green", "Red"):
        scores[color] = 6.0 + float(prefs.get(color, 0.0)) * 2.0

    # Green gains value into heavy CC / mixed pressure and for frontline jobs.
    if comp["CC"] >= 3:
        scores["Green"] += 0.8
        reasons["Green"].append("enemy team has heavy crowd control")
    if comp["AP"] >= 2 and comp["AD"] >= 2:
        scores["Green"] += 0.35
        reasons["Green"].append("enemy damage profile is mixed")

    # Blue gains value when map access/chase matters, especially into squishier teams.
    if squishy >= 3:
        scores["Blue"] += 0.45
        reasons["Blue"].append("enemy team has several squishy targets")
    if comp["CC"] <= 1:
        scores["Blue"] += 0.20
        reasons["Blue"].append("lower enemy CC makes mobility easier to exploit")

    # Red gains value when fights are likely to be damage races / sticky skirmishes.
    if tanky >= 2:
        scores["Red"] += 0.35
        reasons["Red"].append("extra offensive pressure helps into a tankier team")
    if comp["CC"] <= 2:
        scores["Red"] += 0.20
        reasons["Red"].append("you can prioritize more offensive pressure")

    # Champion-preference reason.
    best_pref = max(prefs, key=prefs.get)
    reasons[best_pref].insert(0, f"strong fit for {champion}'s default jungle profile")

    ranked = []
    for color in ("Blue", "Green", "Red"):
        ranked.append({
            "color": color,
            "name": JUNGLE_COMPANIONS[color]["name"],
            "short": JUNGLE_COMPANIONS[color]["short"],
            "description": JUNGLE_COMPANIONS[color]["description"],
            "score": round(max(1.0, min(9.8, scores[color])), 1),
            "reasons": (reasons[color] or [JUNGLE_COMPANIONS[color]["description"]])[:2],
        })

    ranked.sort(key=lambda x: (-x["score"], x["color"]))
    return ranked


def jungle_companion_item_id(dd, companion_name):
    return dd.item_id_for_name(companion_name)


def enemy_threat_tags(enemy_info):
    """Return two compact tags such as 'Physical HIGH' or 'Crit MED'."""
    metrics = enemy_info.get("metrics", {}) or {}

    specs = [
        ("Physical", "physical", 0.9, 2.0),
        ("Magic", "magic", 0.9, 2.0),
        ("Crit", "crit", 0.30, 0.85),
        ("Attack speed", "attack_speed", 0.35, 0.85),
        ("Sustain", "healing", 0.25, 0.65),
        ("Armor", "armor", 0.35, 0.90),
        ("MR", "mr", 0.35, 0.90),
        ("CC", "cc", 0.8, 1.4),
        ("Burst", "burst", 0.25, 0.70),
    ]

    candidates = []
    for label, key, medium, high in specs:
        value = float(metrics.get(key, 0.0) or 0.0)
        if value >= high:
            candidates.append((2, value / high, f"{label} HIGH"))
        elif value >= medium:
            candidates.append((1, value / medium, f"{label} MED"))

    candidates.sort(key=lambda x: (-x[0], -x[1], x[2]))
    tags = [x[2] for x in candidates[:2]]

    if not tags:
        dt = enemy_info.get("damage_type", "UNKNOWN")
        if dt == "AD":
            tags = ["Physical LOW"]
        elif dt == "AP":
            tags = ["Magic LOW"]
        elif dt == "MIXED":
            tags = ["Mixed damage"]
        else:
            tags = ["Low visible threat"]

    return tags


def common_core_items(profile):
    """
    Treat the longest common prefix across balanced/magic/physical paths as CORE.
    This keeps the core stable while the later items remain situational.
    """
    paths = [
        list(profile.get("balanced", []) or []),
        list(profile.get("magic", []) or []),
        list(profile.get("physical", []) or []),
    ]
    paths = [p for p in paths if p]
    if not paths:
        return []

    core = []
    for group in zip(*paths):
        if all(x == group[0] for x in group):
            core.append(group[0])
        else:
            break

    # A profile should still expose at least one core item when its first item is
    # intentionally different between paths.
    if not core and paths[0]:
        core = [paths[0][0]]

    return core


def chosen_baseline_path(profile, enemies):
    comp = live_composition(enemies)
    path = choose_item_path(comp)
    if path == "magic":
        boots_text = profile.get("bootsMagic", "")
        title = "MAGIC / CC-HEAVY"
    elif path == "physical":
        boots_text = profile.get("bootsPhysical", "")
        title = "PHYSICAL-HEAVY"
    else:
        boots_text = profile.get("bootsBalanced", "")
        title = "BALANCED"

    items = list(profile.get(path, []) or [])
    boots = [x.strip() for x in boots_text.split("/") if x.strip()]
    return path, title, items, boots, comp


def item_total_gold(dd, item_id):
    meta = dd.item_data.get(str(item_id), {}) or {}
    return int((meta.get("gold", {}) or {}).get("total", 0) or 0)


def item_is_purchasable(dd, item_id):
    meta = dd.item_data.get(str(item_id), {}) or {}
    gold = meta.get("gold", {}) or {}
    return bool(gold.get("purchasable", True))


MODE_ONLY_RECOMMENDATION_BLOCKLIST = {
    "lightning rod",
}


def current_sr_item_id(
    dd,
    item_name,
    require_completed=False,
):
    """
    Resolve only normal current Summoner's Rift store items.

    Data Dragon is a broad static-data catalogue. It can contain legacy,
    alternate-mode, generated, champion-specific and special-distribution
    entries in addition to normal SR shop items. Recommendation code therefore
    uses a stricter filter than "name exists + purchasable".
    """
    normalized_name = normalize_name(
        item_name
    )
    if (
        not normalized_name
        or normalized_name
        in MODE_ONLY_RECOMMENDATION_BLOCKLIST
    ):
        return None

    item_id = dd.item_id_for_name(
        item_name
    )
    if not item_id:
        return None

    item_id_text = str(
        item_id
    ).strip()

    try:
        numeric_item_id = int(
            item_id_text
        )
    except Exception:
        numeric_item_id = None

    # Normal League shop item IDs are in the ordinary low numeric range.
    # Arena/prismatic/special-distribution entries use extended IDs such as
    # Lightning Rod (447119). They must never enter an SR recommendation even
    # if a Data Dragon build happens to mark them purchasable or omits a map
    # restriction.
    if (
        numeric_item_id is not None
        and numeric_item_id >= 10000
    ):
        return None

    meta = (
        dd.item_data.get(
            item_id_text,
            {},
        )
        or {}
    )
    gold = (
        meta.get(
            "gold",
            {},
        )
        or {}
    )
    maps = (
        meta.get(
            "maps",
            {},
        )
        or {}
    )
    tags = set(
        meta.get(
            "tags",
            [],
        )
        or []
    )

    # Must be a real store purchase, not a generated transform/masterwork.
    if not bool(
        gold.get(
            "purchasable",
            False,
        )
    ):
        return None

    if meta.get(
        "inStore"
    ) is False:
        return None

    if meta.get(
        "hideFromAll"
    ) is True:
        return None

    # Map 11 is Summoner's Rift. If the item metadata exposes map flags, an
    # explicit false for SR is definitive.
    if isinstance(
        maps,
        dict,
    ) and (
        "11" in maps
        or 11 in maps
    ):
        sr_enabled = (
            maps.get(
                "11"
            )
            if "11" in maps
            else maps.get(
                11
            )
        )
        if not bool(
            sr_enabled
        ):
            return None

    # Reject entries whose own static text identifies alternate-mode/special
    # distribution. This catches bad/partial map metadata without depending on
    # one specific item name.
    searchable_text = " ".join([
        str(
            meta.get(
                "name",
                "",
            )
            or ""
        ),
        str(
            meta.get(
                "plaintext",
                "",
            )
            or ""
        ),
        str(
            meta.get(
                "description",
                "",
            )
            or ""
        ),
    ]).lower()

    mode_only_markers = (
        "prismatic item",
        "prismatic anvil",
        "item anvil",
        "arena only",
        "in arena",
    )
    if any(
        marker in searchable_text
        for marker in mode_only_markers
    ):
        return None

    # Do not recommend champion-bound shop entries or non-build utility items.
    if str(
        meta.get(
            "requiredChampion",
            "",
        )
        or ""
    ).strip():
        return None

    if tags.intersection({
        "Consumable",
        "Trinket",
    }):
        return None

    total = int(
        gold.get(
            "total",
            0,
        )
        or 0
    )
    if total <= 0:
        return None

    if require_completed:
        # A normal full-build recommendation must not still build into another
        # regular item. Boots are the deliberate exception because tiering
        # metadata varies between patches.
        builds_into = list(
            meta.get(
                "into",
                [],
            )
            or []
        )
        if (
            builds_into
            and not is_boot_item_name(
                item_name
            )
        ):
            return None

        if (
            total < 900
            and not is_boot_item_name(
                item_name
            )
        ):
            return None

    return item_id_text




def current_sr_item_rejection_reason(
    dd,
    item_name,
    require_completed=True,
):
    """
    Human-readable reason for the pre-push recommendation audit.

    The actual recommendation gate remains current_sr_item_id(); this helper
    only explains why a candidate was rejected.
    """
    name = str(
        item_name
        or ""
    ).strip()
    normalized = normalize_name(
        name
    )
    if not normalized:
        return "empty item name"
    if normalized in MODE_ONLY_RECOMMENDATION_BLOCKLIST:
        return "explicit mode-only blocklist"

    item_id = dd.item_id_for_name(
        name
    )
    if not item_id:
        return "not present in current Data Dragon"

    item_id_text = str(
        item_id
    ).strip()
    try:
        numeric_item_id = int(
            item_id_text
        )
    except Exception:
        numeric_item_id = None

    if (
        numeric_item_id is not None
        and numeric_item_id >= 10000
    ):
        return f"extended/mode-only item id {item_id_text}"

    meta = (
        dd.item_data.get(
            item_id_text,
            {},
        )
        or {}
    )
    gold = (
        meta.get(
            "gold",
            {},
        )
        or {}
    )
    maps = (
        meta.get(
            "maps",
            {},
        )
        or {}
    )
    tags = set(
        meta.get(
            "tags",
            [],
        )
        or []
    )

    if not bool(
        gold.get(
            "purchasable",
            False,
        )
    ):
        return "not purchasable"
    if meta.get(
        "inStore"
    ) is False:
        return "not in store"
    if meta.get(
        "hideFromAll"
    ) is True:
        return "hidden item"

    if isinstance(
        maps,
        dict,
    ) and (
        "11" in maps
        or 11 in maps
    ):
        sr_enabled = (
            maps.get(
                "11"
            )
            if "11" in maps
            else maps.get(
                11
            )
        )
        if not bool(
            sr_enabled
        ):
            return "disabled on Summoner's Rift (map 11)"

    searchable_text = " ".join([
        str(
            meta.get(
                "name",
                "",
            )
            or ""
        ),
        str(
            meta.get(
                "plaintext",
                "",
            )
            or ""
        ),
        str(
            meta.get(
                "description",
                "",
            )
            or ""
        ),
    ]).lower()

    for marker in (
        "prismatic item",
        "prismatic anvil",
        "item anvil",
        "arena only",
        "in arena",
    ):
        if marker in searchable_text:
            return f"alternate-mode marker: {marker}"

    if str(
        meta.get(
            "requiredChampion",
            "",
        )
        or ""
    ).strip():
        return "champion-specific item"

    if tags.intersection({
        "Consumable",
        "Trinket",
    }):
        return "consumable/trinket"

    total = int(
        gold.get(
            "total",
            0,
        )
        or 0
    )
    if total <= 0:
        return "zero/invalid total gold"

    if require_completed:
        builds_into = list(
            meta.get(
                "into",
                [],
            )
            or []
        )
        if (
            builds_into
            and not is_boot_item_name(
                name
            )
        ):
            return "component that still builds into another item"
        if (
            total < 900
            and not is_boot_item_name(
                name
            )
        ):
            return "too cheap to be a completed build slot"

    return "rejected by current SR validator"


def _split_profile_item_value(
    value,
):
    text = str(
        value
        or ""
    ).strip()
    if not text:
        return []
    return [
        part.strip()
        for part in text.split(
            "/"
        )
        if part.strip()
    ]


def recommendation_item_candidates():
    """
    Return every static/cached item name that can feed RiftSense's build engine.

    The audit intentionally looks upstream of current_sr_item_id() so stale
    profile/meta names are visible even though the runtime validator blocks
    them from rendering.
    """
    sources = {}

    def add(
        name,
        source,
    ):
        name = str(
            name
            or ""
        ).strip()
        if not name:
            return
        sources.setdefault(
            name,
            set(),
        ).add(
            source
        )

    for champion, profile in (
        PROFILES
        or {}
    ).items():
        if not isinstance(
            profile,
            dict,
        ):
            continue

        for path_name in (
            "balanced",
            "magic",
            "physical",
        ):
            for name in (
                profile.get(
                    path_name,
                    [],
                )
                or []
            ):
                add(
                    name,
                    f"profiles.json:{champion}:{path_name}",
                )

        for boot_key in (
            "bootsBalanced",
            "bootsMagic",
            "bootsPhysical",
        ):
            for name in _split_profile_item_value(
                profile.get(
                    boot_key,
                    "",
                )
            ):
                add(
                    name,
                    f"profiles.json:{champion}:{boot_key}",
                )

    for pool_name, pool in (
        (
            "ADAPTIVE_ITEM_POOLS",
            ADAPTIVE_ITEM_POOLS,
        ),
        (
            "ASSASSIN_BUILD_POOLS",
            ASSASSIN_BUILD_POOLS,
        ),
        (
            "ASSASSIN_BUILD_CORES",
            ASSASSIN_BUILD_CORES,
        ),
    ):
        for champion, names in (
            pool
            or {}
        ).items():
            for name in (
                names
                or []
            ):
                add(
                    name,
                    f"{pool_name}:{champion}",
                )

    for name in (
        ADAPTIVE_ITEM_WEIGHTS.keys()
    ):
        add(
            name,
            "ADAPTIVE_ITEM_WEIGHTS",
        )

    for name in (
        ASSASSIN_THREAT_WEIGHTS.keys()
    ):
        add(
            name,
            "ASSASSIN_THREAT_WEIGHTS",
        )

    # Existing third-party cache is audited too. Runtime scraping already uses
    # the strict SR catalogue, but this exposes stale cache entries before push.
    try:
        cache_files = list(
            META_CONSENSUS_DIR.glob(
                "*.json"
            )
        )
    except Exception:
        cache_files = []

    for cache_path in cache_files:
        try:
            payload = json.loads(
                cache_path.read_text(
                    encoding="utf-8"
                )
            )
        except Exception:
            continue

        if not isinstance(
            payload,
            dict,
        ):
            continue

        for key in (
            "items",
            "core",
            "boots",
        ):
            value = payload.get(
                key
            )
            if isinstance(
                value,
                str,
            ):
                value = [
                    value
                ]
            for name in (
                value
                or []
            ):
                add(
                    name,
                    f"meta_cache:{cache_path.stem}:{key}",
                )

        for name in (
            (
                payload.get(
                    "item_source_count",
                    {},
                )
                or {}
            ).keys()
        ):
            add(
                name,
                f"meta_cache:{cache_path.stem}:item_source_count",
            )

    return {
        name: sorted(
            entries
        )
        for name, entries in sorted(
            sources.items(),
            key=lambda pair: pair[
                0
            ].lower(),
        )
    }


def audit_recommendation_items(
    dd,
):
    candidates = recommendation_item_candidates()
    valid = []
    invalid = []

    for name, sources in (
        candidates.items()
    ):
        is_boot = is_boot_item_name(
            name
        )
        item_id = current_sr_item_id(
            dd,
            name,
            require_completed=(
                not is_boot
            ),
        )
        if item_id:
            valid.append({
                "name": name,
                "item_id": str(
                    item_id
                ),
                "sources": sources,
            })
        else:
            invalid.append({
                "name": name,
                "reason": current_sr_item_rejection_reason(
                    dd,
                    name,
                    require_completed=(
                        not is_boot
                    ),
                ),
                "sources": sources,
            })

    return {
        "patch": str(
            getattr(
                dd,
                "version",
                "",
            )
            or ""
        ),
        "total": len(
            candidates
        ),
        "valid": valid,
        "invalid": invalid,
        "passed": not invalid,
    }



def current_sr_item_name(
    dd,
    item_name,
    require_completed=False,
):
    return (
        item_name
        if current_sr_item_id(
            dd,
            item_name,
            require_completed=require_completed,
        )
        else None
    )


def item_children(dd, item_id):
    meta = dd.item_data.get(str(item_id), {}) or {}
    return [str(x) for x in (meta.get("from", []) or [])]


def live_inventory_counter(player_items):
    counter = Counter()
    for item in player_items or []:
        item_id = item.get("itemID")
        if item_id:
            counter[str(item_id)] += 1
    return counter


def consume_tree_credit(dd, item_id, inventory):
    """
    Match owned components against one copy of an item recipe.
    Returns (gold credit, consumed item ids) and mutates inventory.
    """
    item_id = str(item_id)

    if inventory.get(item_id, 0) > 0:
        inventory[item_id] -= 1
        return item_total_gold(dd, item_id), [item_id]

    credit = 0
    consumed = []
    for child in item_children(dd, item_id):
        child_credit, child_consumed = consume_tree_credit(dd, child, inventory)
        credit += child_credit
        consumed.extend(child_consumed)

    return credit, consumed


def completion_cost(dd, target_id, inventory):
    target_id = str(target_id)
    inv = Counter(inventory)
    credit, _ = consume_tree_credit(dd, target_id, inv)
    return max(0, item_total_gold(dd, target_id) - credit)


def required_recipe_nodes(dd, item_id, inventory):
    """
    Return unsatisfied recipe nodes. If an owned component satisfies a branch, that
    branch stops expanding.
    """
    item_id = str(item_id)

    if inventory.get(item_id, 0) > 0:
        inventory[item_id] -= 1
        return []

    nodes = [item_id]
    for child in item_children(dd, item_id):
        nodes.extend(required_recipe_nodes(dd, child, inventory))
    return nodes


def simulate_purchase(dd, item_id, inventory):
    """
    Consume owned sub-components used by item_id and add the newly purchased item.
    """
    new_inventory = Counter(inventory)
    _credit, _consumed = consume_tree_credit(dd, item_id, new_inventory)
    new_inventory[str(item_id)] += 1
    return new_inventory



def is_boot_item_name(name):
    n = normalize_name(name)
    boot_tokens = (
        "boots", "treads", "steelcaps", "greaves", "sorcerer's shoes",
        "ionian boots", "swifties",
    )
    return any(token in n for token in boot_tokens)


def completed_item_names(player_items, dd):
    """
    Return visible owned item names that look like completed non-consumable items.
    Jungle companion starters and trinkets are excluded.
    """
    result = []
    companion_names = {
        normalize_name(data["name"])
        for data in JUNGLE_COMPANIONS.values()
    }

    for live_item in player_items or []:
        item_id = live_item.get("itemID")
        if not item_id:
            continue

        name = (
            live_item.get("displayName")
            or dd.item_name(item_id)
            or ""
        )
        n = normalize_name(name)

        if not n:
            continue
        if n in companion_names:
            continue
        if n in {
            "warding totem (trinket)",
            "oracle lens",
            "farsight alteration",
        }:
            continue

        meta = dd.item_data.get(str(item_id), {}) or {}
        children = meta.get("into", []) or []
        tags = set(meta.get("tags", []) or [])
        gold = meta.get("gold", {}) or {}
        total = int(gold.get("total", 0) or 0)

        # Completed items typically have no 'into' upgrades. This also keeps boots.
        if not children and "Consumable" not in tags and total >= 900:
            result.append(name)

    return result


def adaptive_full_build(
    champion,
    profile,
    player_items,
    enemies,
    adaptive_options,
    dd,
    allies=None,
):
    """
    Build a 6-slot target:
      1 boots + 5 non-boots items.

    V50 first decides the champion's job for the current team, then adapts the
    later slots. This prevents carry champions from accidentally stacking
    durability when allied tanks already cover frontline.
    """
    identity = live_build_identity(
        champion,
        allies or [],
        enemies,
        dd,
    )
    mode = identity.get(
        "mode",
        "PROFILE",
    )

    _path, title, baseline_items, boots, comp = chosen_baseline_path(
        profile,
        enemies,
    )
    profile_core = common_core_items(
        profile
    )
    meta_payload = load_meta_consensus(
        champion
    )
    meta_core = [
        name
        for name in (
            meta_payload.get(
                "core",
                []
            )
            or []
        )
        if current_sr_item_id(
            dd,
            name,
            require_completed=True,
        )
    ]
    meta_candidates = [
        name
        for name in (
            meta_payload.get(
                "items",
                []
            )
            or []
        )
        if current_sr_item_id(
            dd,
            name,
            require_completed=True,
        )
    ]

    owned_completed = completed_item_names(
        player_items,
        dd,
    )

    chosen_boots, boots_source = adaptive_boot_choice(
        champion,
        profile,
        player_items,
        enemies,
        dd,
    )

    if (
        mode == "ASSASSIN"
        and champion in ASSASSIN_BUILD_CORES
    ):
        preferred_core = [
            name
            for name in ASSASSIN_BUILD_CORES[
                champion
            ]
            if current_sr_item_id(
                dd,
                name,
                require_completed=True,
            )
        ]

        # Meta can replace/augment the local assassin core only when the item
        # actually fits the assassin job for this team.
        meta_offensive_core = [
            name
            for name in meta_core
            if is_assassin_offensive_item(
                name,
                dd,
            )
            and item_role_fit(
                champion,
                name,
                mode,
                dd,
            )
            >= 0.68
            and not is_assassin_defensive_item(
                name
            )
        ]
        core = []
        for name in (
            meta_offensive_core
            + preferred_core
        ):
            if normalize_name(
                name
            ) not in {
                normalize_name(
                    current
                )
                for current in core
            }:
                core.append(
                    name
                )
            if len(
                core
            ) >= 2:
                break

        if not core:
            core = profile_core

        title = (
            "ASSASSIN • "
            + identity.get(
                "reason",
                "frontline covered",
            )
        )
    else:
        # Meta consensus becomes the baseline when available, while local
        # profile items remain a safe fallback for missing/blocked sources.
        core = []
        for name in (
            meta_core
            + profile_core
        ):
            if normalize_name(
                name
            ) in {
                normalize_name(
                    current
                )
                for current in core
            }:
                continue
            core.append(
                name
            )
            if len(
                core
            ) >= 2:
                break

        if not core:
            core = profile_core

        if mode == "BRUISER":
            title = (
                "BRUISER • "
                + identity.get(
                    "reason",
                    "limited frontline",
                )
            )
        elif meta_payload:
            title = (
                "META BASELINE • "
                f"{meta_payload.get('source_count', 0)}/"
                f"{meta_payload.get('enabled_source_count', 5)} sources"
            )

    target_non_boots = []
    sources = {}
    defensive_count = 0

    def add_item(
        name,
        source,
        allow_missing=False,
    ):
        nonlocal defensive_count

        if not name:
            return
        if is_boot_item_name(
            name
        ):
            return

        normalized = normalize_name(
            name
        )
        if normalized in {
            normalize_name(
                existing
            )
            for existing in target_non_boots
        }:
            return
        if len(
            target_non_boots
        ) >= 5:
            return

        # Assassin mode may use one defensive damage item when the threat
        # clearly warrants it, but not three durability slots in a row.
        is_defensive = (
            is_assassin_defensive_item(
                name
            )
        )
        if (
            mode == "ASSASSIN"
            and source != "OWNED"
            and is_defensive
            and defensive_count >= 1
        ):
            return

        if (
            not allow_missing
            and not current_sr_item_id(
                dd,
                name,
                require_completed=True,
            )
        ):
            return

        target_non_boots.append(
            name
        )
        sources[
            name
        ] = source
        if (
            mode == "ASSASSIN"
            and is_defensive
        ):
            defensive_count += 1

    # Never recommend selling completed items in the middle of a game.
    for name in owned_completed:
        if not is_boot_item_name(
            name
        ):
            add_item(
                name,
                "OWNED",
                allow_missing=True,
            )

    for name in core:
        add_item(
            name,
            (
                "ASSASSIN CORE"
                if mode == "ASSASSIN"
                else "CORE"
            ),
        )

    for option in adaptive_options or []:
        add_item(
            option[
                "name"
            ],
            (
                "OFFENSE"
                if mode == "ASSASSIN"
                and normalize_name(
                    option[
                        "name"
                    ]
                )
                not in {
                    normalize_name(
                        defensive_name
                    )
                    for defensive_name
                    in ASSASSIN_DEFENSIVE_ITEM_NAMES
                }
                else "ADAPTIVE"
            ),
        )

    if mode == "ASSASSIN":
        # Meta candidates are allowed only when they preserve the selected job.
        for name in meta_candidates:
            if (
                is_assassin_offensive_item(
                    name,
                    dd,
                )
                and item_role_fit(
                    champion,
                    name,
                    mode,
                    dd,
                )
                >= 0.62
                and not is_assassin_defensive_item(
                    name
                )
            ):
                add_item(
                    name,
                    "META",
                )

        # Fill with offensive candidates before touching the bruiser baseline.
        for name in ASSASSIN_BUILD_POOLS.get(
            champion,
            [],
        ):
            add_item(
                name,
                "OFFENSE",
            )
    else:
        for name in meta_candidates:
            add_item(
                name,
                "META",
            )

        for name in baseline_items:
            add_item(
                name,
                "BASELINE",
            )

        for key in (
            "balanced",
            "magic",
            "physical",
        ):
            for name in profile.get(
                key,
                [],
            ) or []:
                add_item(
                    name,
                    "FALLBACK",
                )

    # Last-resort fill if an assassin item was renamed/removed on a new patch.
    if len(
        target_non_boots
    ) < 5:
        for name in baseline_items:
            add_item(
                name,
                "FALLBACK",
            )

    full = []

    if not chosen_boots:
        chosen_boots = _fallback_boot_name(
            profile,
            enemies,
        )
        boots_source = "BOOTS • LOADING DATA"

    full.append({
        "name": chosen_boots,
        "source": boots_source,
    })

    for name in target_non_boots[:5]:
        full.append({
            "name": name,
            "source": sources.get(
                name,
                "BASELINE",
            ),
        })

    for item in full:
        item[
            "item_id"
        ] = (
            dd.item_id_for_name(
                item[
                    "name"
                ]
            )
            if item.get(
                "source"
            )
            == "OWNED"
            else current_sr_item_id(
                dd,
                item[
                    "name"
                ],
                require_completed=(
                    not is_boot_item_name(
                        item[
                            "name"
                        ]
                    )
                ),
            )
        )

    return {
        "items": full[:6],
        "baseline_title": title,
        "comp": comp,
        "core": core,
        "identity": identity,
    }



def first_unowned_full_build_target(full_build_items, player_items, dd):
    """
    Pick the first missing target from the displayed adaptive full build.
    Jungle companion handling stays separate and can still override this.
    """
    owned_names = []
    for item in player_items or []:
        item_id = item.get("itemID")
        name = item.get("displayName") or (dd.item_name(item_id) if item_id else "")
        if name:
            owned_names.append(normalize_name(name))

    for item in full_build_items:
        name = item.get("name", "")
        if normalize_name(name) not in owned_names:
            return name
    return None


def build_purchase_plan(dd, target_id, player_items, current_gold, max_steps=3):
    """
    Create a small recall purchase plan for one target item.

    It uses Riot Data Dragon recipe trees and the player's current visible inventory.
    """
    target_id = str(target_id)
    try:
        budget = max(0, int(float(current_gold)))
    except Exception:
        budget = 0

    inventory = live_inventory_counter(player_items)
    remaining_before = completion_cost(dd, target_id, inventory)
    target_name = dd.item_name(target_id)

    if remaining_before <= 0:
        return {
            "target": target_name,
            "remaining_before": 0,
            "purchases": [],
            "gold_after": budget,
            "message": "Target item is already completed.",
            "save_for": None,
        }

    # If the whole target can be completed now, that is the cleanest shop action.
    if remaining_before <= budget:
        return {
            "target": target_name,
            "remaining_before": remaining_before,
            "purchases": [{
                "item_id": target_id,
                "name": target_name,
                "cost": remaining_before,
                "complete": True,
            }],
            "gold_after": budget - remaining_before,
            "message": "You can complete the target item on this recall.",
            "save_for": None,
        }

    purchases = []
    virtual_inventory = Counter(inventory)
    virtual_budget = budget

    for _ in range(max_steps):
        # A previous component purchase may make the full target affordable.
        target_cost_now = completion_cost(dd, target_id, virtual_inventory)
        if target_cost_now <= virtual_budget and target_cost_now > 0:
            purchases.append({
                "item_id": target_id,
                "name": target_name,
                "cost": target_cost_now,
                "complete": True,
            })
            virtual_budget -= target_cost_now
            virtual_inventory = simulate_purchase(dd, target_id, virtual_inventory)
            break

        required = required_recipe_nodes(
            dd,
            target_id,
            Counter(virtual_inventory),
        )

        # Target itself is handled separately above.
        candidates = []
        seen = set()
        for node_id in required:
            node_id = str(node_id)
            if node_id == target_id or node_id in seen:
                continue
            seen.add(node_id)

            if not item_is_purchasable(dd, node_id):
                continue

            cost = completion_cost(dd, node_id, virtual_inventory)
            if cost <= 0 or cost > virtual_budget:
                continue

            total_value = item_total_gold(dd, node_id)
            # Prefer the largest useful upgrade the current recall can afford.
            candidates.append((cost, total_value, node_id))

        if not candidates:
            break

        candidates.sort(key=lambda x: (-x[0], -x[1], x[2]))
        cost, _total, node_id = candidates[0]

        purchases.append({
            "item_id": node_id,
            "name": dd.item_name(node_id),
            "cost": cost,
            "complete": False,
        })
        virtual_budget -= cost
        virtual_inventory = simulate_purchase(dd, node_id, virtual_inventory)

    # If nothing was affordable, identify the cheapest useful recipe node to save for.
    save_for = None
    if not purchases:
        required = required_recipe_nodes(dd, target_id, Counter(inventory))
        options = []
        seen = set()
        for node_id in required:
            node_id = str(node_id)
            if node_id == target_id or node_id in seen:
                continue
            seen.add(node_id)
            if not item_is_purchasable(dd, node_id):
                continue
            cost = completion_cost(dd, node_id, inventory)
            if cost > 0:
                options.append((cost, item_total_gold(dd, node_id), node_id))

        if options:
            options.sort(key=lambda x: (x[0], -x[1], x[2]))
            cost, _total, node_id = options[0]
            save_for = {
                "item_id": node_id,
                "name": dd.item_name(node_id),
                "cost": cost,
                "missing_gold": max(0, cost - budget),
            }

    return {
        "target": target_name,
        "remaining_before": remaining_before,
        "purchases": purchases,
        "gold_after": virtual_budget,
        "message": (
            "Buy the shown components now."
            if purchases
            else "No useful target component is affordable yet."
        ),
        "save_for": save_for,
    }


def first_unowned_named_item(item_names, player_items, dd):
    owned = []
    for item in player_items or []:
        item_id = item.get("itemID")
        name = item.get("displayName") or (dd.item_name(item_id) if item_id else "")
        if name:
            owned.append(normalize_name(name))

    for name in item_names:
        if normalize_name(name) not in owned:
            return name
    return None


def choose_item_path(comp):
    if comp["AP"] >= 3 or (comp["AP"] >= 2 and comp["CC"] >= 3):
        return "magic"
    if comp["AD"] >= 3 and comp["AP"] <= 1:
        return "physical"
    if comp["CC"] >= 4:
        return "magic"
    return "balanced"


def format_time(seconds):
    try:
        seconds = max(0, int(float(seconds)))
    except Exception:
        seconds = 0
    return f"{seconds // 60}:{seconds % 60:02d}"


class DataDragon:
    def __init__(self):
        self.version = None
        self.items_version = None
        self.champions_version = None
        self.item_data = {}
        self.item_name_to_id = {}
        self.champion_data = {}
        self.champion_id_to_name = {}
        self.champion_name_to_key = {}
        self.runes_version = None
        self.rune_styles = []
        self.rune_name_to_id = {}
        self.rune_id_to_name = {}
        self.rune_name_to_style_id = {}
        self.rune_name_to_slot_index = {}
        self.rune_style_name_to_id = {}
        self.latest_available_version = None
        self.requested_patch_prefix = ""

    def resolve_version(self, game_version=""):
        prefix = patch_prefix_from_game_version(game_version)
        self.requested_patch_prefix = prefix
        cached_versions = META_CACHE_DIR / "versions.json"
        versions = None

        try:
            versions = fetch_json(f"{DDRAGON_BASE}/api/versions.json")
            cached_versions.write_text(json.dumps(versions), encoding="utf-8")
        except Exception:
            if cached_versions.exists():
                try:
                    versions = json.loads(cached_versions.read_text(encoding="utf-8"))
                except Exception:
                    versions = None

        if not versions:
            return self.version

        self.latest_available_version = versions[0] if versions else None

        if prefix:
            for version in versions:
                if version.startswith(prefix):
                    self.version = version
                    return version

        self.version = versions[0]
        return self.version

    def load_static_data(self, version):
        if not version:
            return False
        items_ok = self.load_items(version)
        champs_ok = self.load_champions(version)
        runes_ok = self.load_runes(version)
        return items_ok or champs_ok or runes_ok

    def load_items(self, version):
        if self.item_data and self.items_version == version:
            return True

        cache = META_CACHE_DIR / f"item-{version}.json"
        payload = None
        try:
            payload = fetch_json(f"{DDRAGON_BASE}/cdn/{version}/data/en_US/item.json")
            cache.write_text(json.dumps(payload), encoding="utf-8")
        except Exception:
            if cache.exists():
                try:
                    payload = json.loads(cache.read_text(encoding="utf-8"))
                except Exception:
                    payload = None

        if not payload:
            return False

        self.version = version
        self.items_version = version
        self.item_data = payload.get("data", {}) or {}
        self._rebuild_item_name_index()
        return True

    @staticmethod
    def _item_name_candidate_score(item_id, item):
        """Prefer the normal purchasable Summoner's Rift variant of duplicate names."""
        item = item if isinstance(item, dict) else {}
        try:
            numeric_id = int(str(item_id))
        except (TypeError, ValueError):
            numeric_id = 999_999_999

        maps = item.get("maps", {}) or {}
        if isinstance(maps, dict) and ("11" in maps or 11 in maps):
            on_summoners_rift = bool(
                maps.get("11") if "11" in maps else maps.get(11)
            )
        else:
            on_summoners_rift = False

        gold = item.get("gold", {}) or {}
        purchasable = bool(gold.get("purchasable", False))
        normal_id = 0 < numeric_id < 10_000
        in_store = item.get("inStore") is not False
        visible = item.get("hideFromAll") is not True

        # The first five fields encode the same safety preferences used by the
        # runtime SR validator. The final field makes ties deterministic and
        # favors the ordinary lower numeric ID.
        return (
            int(normal_id),
            int(on_summoners_rift),
            int(purchasable),
            int(in_store),
            int(visible),
            -numeric_id,
        )

    def _rebuild_item_name_index(self):
        """Build a stable name -> ID index without depending on JSON order."""
        self.item_name_to_id = {}
        for item_id, item in self.item_data.items():
            name = normalize_name((item or {}).get("name"))
            if not name:
                continue

            existing_id = self.item_name_to_id.get(name)
            if existing_id is None:
                self.item_name_to_id[name] = str(item_id)
                continue

            existing_item = self.item_data.get(str(existing_id), {}) or {}
            if self._item_name_candidate_score(
                item_id,
                item,
            ) > self._item_name_candidate_score(
                existing_id,
                existing_item,
            ):
                self.item_name_to_id[name] = str(item_id)

    def load_champions(self, version):
        if self.champion_data and self.champions_version == version:
            return True

        cache = META_CACHE_DIR / f"champion-{version}.json"
        payload = None
        try:
            payload = fetch_json(f"{DDRAGON_BASE}/cdn/{version}/data/en_US/champion.json")
            cache.write_text(json.dumps(payload), encoding="utf-8")
        except Exception:
            if cache.exists():
                try:
                    payload = json.loads(cache.read_text(encoding="utf-8"))
                except Exception:
                    payload = None

        if not payload:
            return False

        self.version = version
        self.champions_version = version
        self.champion_data = payload.get("data", {}) or {}
        self.champion_id_to_name = {}
        self.champion_name_to_key = {}

        for key, champion in self.champion_data.items():
            champ_id = str(champion.get("key", ""))
            champ_name = champion.get("name") or key
            if champ_id:
                self.champion_id_to_name[champ_id] = champ_name
            self.champion_name_to_key[normalize_name(champ_name)] = key
            self.champion_name_to_key[normalize_name(key)] = key

        return True

    def load_runes(self, version):
        """
        Load Rune Reforged names/IDs/styles from Riot Data Dragon.

        Rune profile files store names rather than numeric IDs so they survive
        most patch changes. IDs are resolved against the current Data Dragon
        version before any League Client write is attempted.
        """
        if (
            self.rune_name_to_id
            and self.runes_version == version
        ):
            return True

        cache = (
            META_CACHE_DIR
            / f"runesReforged-{version}.json"
        )
        payload = None

        try:
            payload = fetch_json(
                f"{DDRAGON_BASE}/cdn/{version}/data/en_US/runesReforged.json"
            )
            cache.write_text(
                json.dumps(
                    payload,
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
        except Exception:
            if cache.exists():
                try:
                    payload = json.loads(
                        cache.read_text(
                            encoding="utf-8"
                        )
                    )
                except Exception:
                    payload = None

        if not isinstance(
            payload,
            list,
        ):
            return False

        self.runes_version = version
        self.rune_styles = payload
        self.rune_name_to_id = {}
        self.rune_id_to_name = {}
        self.rune_name_to_style_id = {}
        self.rune_name_to_slot_index = {}
        self.rune_style_name_to_id = {}

        for style in payload:
            try:
                style_id = int(
                    style.get(
                        "id",
                        0,
                    )
                    or 0
                )
            except Exception:
                style_id = 0

            style_name = str(
                style.get(
                    "name",
                    "",
                )
                or ""
            )
            if (
                style_id
                and style_name
            ):
                self.rune_style_name_to_id[
                    normalize_name(
                        style_name
                    )
                ] = style_id

            for slot_index, slot in enumerate(
                style.get(
                    "slots"
                )
                or []
            ):
                for rune in (
                    slot.get(
                        "runes"
                    )
                    or []
                ):
                    try:
                        rune_id = int(
                            rune.get(
                                "id",
                                0,
                            )
                            or 0
                        )
                    except Exception:
                        rune_id = 0

                    rune_name = str(
                        rune.get(
                            "name",
                            "",
                        )
                        or ""
                    )
                    key = normalize_name(
                        rune_name
                    )
                    if (
                        rune_id
                        and key
                    ):
                        self.rune_name_to_id[
                            key
                        ] = rune_id
                        self.rune_id_to_name[
                            rune_id
                        ] = rune_name
                        self.rune_name_to_style_id[
                            key
                        ] = style_id
                        self.rune_name_to_slot_index[
                            key
                        ] = int(
                            slot_index
                        )

        return bool(
            self.rune_name_to_id
        )

    def rune_id_for_name(
        self,
        name,
    ):
        return self.rune_name_to_id.get(
            normalize_name(
                name
            )
        )

    def rune_style_for_name(
        self,
        name,
    ):
        return self.rune_name_to_style_id.get(
            normalize_name(
                name
            )
        )

    def rune_slot_for_name(
        self,
        name,
    ):
        return self.rune_name_to_slot_index.get(
            normalize_name(
                name
            )
        )

    def rune_name(
        self,
        rune_id,
    ):
        try:
            rune_id = int(
                rune_id
            )
        except Exception:
            return str(
                rune_id
            )
        return self.rune_id_to_name.get(
            rune_id,
            str(
                rune_id
            ),
        )

    def item_id_for_name(self, name):
        return self.item_name_to_id.get(normalize_name(name))

    def item_name(self, item_id):
        return (self.item_data.get(str(item_id), {}) or {}).get("name") or str(item_id)

    def champion_name(self, champion_id):
        try:
            champion_id = int(champion_id)
        except Exception:
            return ""
        if champion_id <= 0:
            return ""
        return self.champion_id_to_name.get(str(champion_id), f"Champion {champion_id}")

    def champion_tags(self, champion_name):
        key = self.champion_name_to_key.get(normalize_name(champion_name))
        if not key:
            return []
        return (self.champion_data.get(key, {}) or {}).get("tags", []) or []

    def item_icon_path(self, item_id):
        if not self.version or not item_id:
            return None
        item_id = str(item_id)
        path = ITEM_CACHE_DIR / self.version / f"{item_id}.png"
        if path.exists() and path.stat().st_size > 100:
            return path
        try:
            download_file(
                f"{DDRAGON_BASE}/cdn/{self.version}/img/item/{item_id}.png",
                path,
            )
            return path
        except Exception:
            return None

    def champion_icon_path(self, champion_name):
        if not self.version or not champion_name:
            return None
        key = self.champion_name_to_key.get(normalize_name(champion_name))
        if not key:
            return None
        path = CHAMP_CACHE_DIR / self.version / f"{key}.png"
        if path.exists() and path.stat().st_size > 100:
            return path
        try:
            download_file(
                f"{DDRAGON_BASE}/cdn/{self.version}/img/champion/{key}.png",
                path,
            )
            return path
        except Exception:
            return None


