def item_role_fit(
    champion,
    item_name,
    mode,
    dd,
):
    item_id = dd.item_id_for_name(
        item_name
    )
    meta = (
        dd.item_data.get(
            str(
                item_id
            ),
            {},
        )
        or {}
    )
    stats = (
        meta.get(
            "stats",
            {}
        )
        or {}
    )
    tags = set(
        meta.get(
            "tags",
            []
        )
        or []
    )
    description = re.sub(
        r"<[^>]+>",
        " ",
        str(
            meta.get(
                "description",
                "",
            )
            or ""
        ),
    ).lower()

    ad = float(
        stats.get(
            "FlatPhysicalDamageMod",
            0,
        )
        or 0
    )
    ap = float(
        stats.get(
            "FlatMagicDamageMod",
            0,
        )
        or 0
    )
    hp = float(
        stats.get(
            "FlatHPPoolMod",
            0,
        )
        or 0
    )
    armor = float(
        stats.get(
            "FlatArmorMod",
            0,
        )
        or 0
    )
    mr = float(
        stats.get(
            "FlatSpellBlockMod",
            0,
        )
        or 0
    )

    offense = 0.0
    offense += min(
        0.45,
        ad / 120.0,
    )
    offense += min(
        0.30,
        ap / 180.0,
    )
    if "Damage" in tags:
        offense += 0.20
    if (
        "lethality"
        in description
        or "armor penetration"
        in description
    ):
        offense += 0.25

    defense = min(
        1.0,
        hp / 800.0
        + armor / 180.0
        + mr / 180.0,
    )

    if mode == "ASSASSIN":
        if is_assassin_defensive_item(
            item_name
        ):
            return max(
                0.55,
                min(
                    0.78,
                    0.55
                    + offense
                    * 0.25,
                ),
            )
        return max(
            0.10,
            min(
                1.0,
                0.42
                + offense
                - defense
                * 0.28,
            ),
        )

    if mode in {
        "BRUISER",
        "PROFILE",
    }:
        return max(
            0.20,
            min(
                1.0,
                0.45
                + offense
                * 0.45
                + defense
                * 0.45,
            ),
        )

    return 0.5


def item_live_state_fit(
    item_name,
    mode,
    strategy_mode,
    dd,
):
    role = item_role_fit(
        "",
        item_name,
        mode,
        dd,
    )
    state = str(
        strategy_mode
        or "STABLE"
    ).upper()

    defensive = is_assassin_defensive_item(
        item_name
    )
    if state in {
        "SNOWBALL",
        "AHEAD",
    }:
        return (
            0.40
            if defensive
            else min(
                1.0,
                0.65
                + role
                * 0.35,
            )
        )
    if state in {
        "RECOVER",
        "BEHIND",
    }:
        return (
            0.85
            if defensive
            else 0.48
        )
    return 0.5


def rune_keystone_composition_fit(
    champion,
    keystone,
    allies,
    enemies,
    dd,
):
    identity = live_build_identity(
        champion,
        allies,
        enemies,
        dd,
    )
    shape = {
        "tanks": sum(
            1
            for enemy in enemies or []
            if is_frontline_champion(
                (
                    enemy.get(
                        "championName",
                        "",
                    )
                    if isinstance(
                        enemy,
                        dict,
                    )
                    else enemy
                ),
                dd,
            )
        ),
        "squishies": enemy_squishy_count(
            enemies,
            dd,
        ),
    }
    key = normalize_name(
        keystone
    )
    mode = identity.get(
        "mode",
        "PROFILE",
    )

    if key in {
        normalize_name(
            "Electrocute"
        ),
        normalize_name(
            "Dark Harvest"
        ),
        normalize_name(
            "Hail of Blades"
        ),
    }:
        score = 0.55
        if mode == "ASSASSIN":
            score += 0.25
        if shape[
            "squishies"
        ] >= 3:
            score += 0.15
        return min(
            1.0,
            score,
        )

    if key == normalize_name(
        "Conqueror"
    ):
        score = 0.58
        if mode == "BRUISER":
            score += 0.18
        if shape[
            "tanks"
        ] >= 2:
            score += 0.18
        return min(
            1.0,
            score,
        )

    if key in {
        normalize_name(
            "Lethal Tempo"
        ),
        normalize_name(
            "Press the Attack"
        ),
    }:
        score = 0.58
        if shape[
            "tanks"
        ] >= 1:
            score += 0.10
        return min(
            1.0,
            score,
        )

    if key == normalize_name(
        "First Strike"
    ):
        return (
            0.72
            if shape[
                "squishies"
            ] >= 3
            else 0.52
        )

    return 0.5


def choose_meta_rune_profile(
    champion,
    allies,
    enemies,
    dd,
    role="JUNGLE",
):
    role_key = draft_role_key(
        role
    )
    local = rune_choices_for_role(
        champion,
        role_key,
    )
    if role_key != "JUNGLE":
        return local

    payload = load_meta_consensus(
        champion
    )
    candidates = []

    consensus = (
        payload.get(
            "runes",
            {}
        )
        or {}
    )
    if consensus.get(
        "text"
    ):
        candidates.append({
            "label": "Meta consensus",
            "runes": consensus[
                "text"
            ],
            "meta_support": float(
                consensus.get(
                    "support",
                    0.5,
                )
                or 0.5
            ),
            "source": "META",
        })

    for page in (
        payload.get(
            "source_rune_pages",
            []
        )
        or []
    ):
        text = str(
            page.get(
                "text",
                "",
            )
            or ""
        )
        if text:
            candidates.append({
                "label": page.get(
                    "source_name",
                    "Meta source",
                ),
                "runes": text,
                "meta_support": min(
                    1.0,
                    float(
                        page.get(
                            "weight",
                            0.0,
                        )
                        or 0.0
                    )
                    / 0.30,
                ),
                "source": page.get(
                    "source",
                    "META",
                ),
            })

    for key in (
        "recommended",
        "alternative",
    ):
        choice = (
            local.get(
                key
            )
            or {}
        )
        text = str(
            choice.get(
                "runes",
                "",
            )
            or ""
        )
        if text:
            candidates.append({
                "label": choice.get(
                    "label",
                    "Local preset",
                ),
                "runes": text,
                "meta_support": 0.45,
                "source": "LOCAL",
            })

    deduped = []
    seen = set()
    for candidate in candidates:
        key = normalize_name(
            candidate[
                "runes"
            ]
        )
        if key in seen:
            continue
        seen.add(
            key
        )
        selection, _error = build_rune_page_selection(
            dd,
            candidate[
                "runes"
            ],
        )
        if not selection:
            continue
        parsed, _error = parse_rune_profile_text(
            candidate[
                "runes"
            ]
        )
        keystone = (
            parsed[
                "primary"
            ][0]
            if parsed
            else ""
        )
        candidate[
            "keystone"
        ] = keystone
        deduped.append(
            candidate
        )

    if not deduped:
        return local

    for candidate in deduped:
        meta_fit = float(
            candidate.get(
                "meta_support",
                0.5,
            )
            or 0.5
        )
        comp_fit = rune_keystone_composition_fit(
            champion,
            candidate.get(
                "keystone",
                "",
            ),
            allies,
            enemies,
            dd,
        )
        personal_fit = personal_keystone_signal(
            champion,
            candidate.get(
                "keystone",
                "",
            ),
            dd,
        )

        # Rune pages do not have a distinct current-item-state term, so the
        # weighting is normalized across meta + composition/matchup + history.
        candidate[
            "score"
        ] = (
            0.50
            * meta_fit
            + 0.35
            * comp_fit
            + 0.15
            * personal_fit
        )

    deduped.sort(
        key=lambda candidate: (
            -candidate.get(
                "score",
                0.0,
            ),
            candidate.get(
                "label",
                "",
            ),
        )
    )

    recommended = dict(
        deduped[
            0
        ]
    )
    recommended[
        "label"
    ] = (
        f"{recommended.get('label', 'Meta')} "
        f"• fit {recommended.get('score', 0) * 10:.1f}/10"
    )

    alternative = (
        dict(
            deduped[
                1
            ]
        )
        if len(
            deduped
        )
        > 1
        else {}
    )
    if alternative:
        alternative[
            "label"
        ] = (
            f"{alternative.get('label', 'Alternative')} "
            f"• fit {alternative.get('score', 0) * 10:.1f}/10"
        )

    return {
        "recommended": recommended,
        "alternative": alternative,
    }








def find_active_player(data):
    active = data.get("activePlayer") or {}
    active_ids = {
        normalize_name(active.get("riotId")),
        normalize_name(active.get("summonerName")),
        normalize_name(active.get("riotIdGameName")),
    }
    active_ids.discard("")

    for player in data.get("allPlayers") or []:
        candidates = {
            normalize_name(player.get("riotId")),
            normalize_name(player.get("summonerName")),
            normalize_name(player.get("riotIdGameName")),
        }
        if active_ids & candidates:
            return player
    return None


def visible_team_names(team_entries, dd):
    result = []
    for entry in team_entries or []:
        name = dd.champion_name(entry.get("championId", 0))
        if name:
            result.append(name)
    return result


def role_label(value):
    value = (value or "").strip()
    if not value:
        return "Unknown"
    mapping = {
        "top": "Top",
        "jungle": "Jungle",
        "middle": "Mid",
        "mid": "Mid",
        "bottom": "ADC",
        "utility": "Support",
        "support": "Support",
    }
    return mapping.get(value.lower(), value.title())



DRAFT_ROLE_KEY_MAP = dict(ROLE_KEY_MAP)
DRAFT_ROLE_KEYS = tuple(ROLE_KEYS)


def draft_role_key(value: str | None) -> str:
    return canonical_role(value)




