def draft_profile_role_keys(profile):
    result = set()
    for value in ((profile or {}).get("role", ["ANY"]) or ["ANY"]):
        raw = str(value or "").strip().upper()
        if raw == "ANY":
            result.add("ANY")
            continue
        canonical = draft_role_key(raw)
        if canonical != "UNKNOWN":
            result.add(canonical)
    return result or {"ANY"}


def draft_role_display(role_key: str | None) -> str:
    return role_display(role_key)


def _clean_champion_list(values):
    result = []
    seen = set()
    for value in values or []:
        name = str(value or "").strip()
        key = normalize_name(name)
        if not name or not key or key in seen:
            continue
        seen.add(key)
        result.append(name)
    return result


def migrated_role_pool_map(settings=None):
    """
    Return a normalized role-specific pool map.

    Older RiftSense builds stored one global champion_pool. On first use this
    function maps curated champions to their declared roles; generic/ANY
    champions are copied to all roles so an upgrade never silently removes a
    champion the user previously configured.
    """
    settings = settings if isinstance(settings, dict) else SETTINGS
    raw = settings.get("champion_pool_by_role") or {}

    result = {
        role: []
        for role in DRAFT_ROLE_KEYS
    }

    if isinstance(raw, dict):
        has_role_data = False
        for raw_role, champions in raw.items():
            role = draft_role_key(raw_role)
            if role not in result or not isinstance(champions, list):
                continue
            result[role] = _clean_champion_list(champions)
            if result[role]:
                has_role_data = True

        if has_role_data:
            return result

    legacy = _clean_champion_list(
        settings.get("champion_pool")
        or DRAFT_PROFILES.keys()
    )

    for champion in legacy:
        profile = DRAFT_PROFILES.get(champion)
        roles = draft_profile_role_keys(profile or {"role": ["ANY"]})

        if "ANY" in roles:
            target_roles = DRAFT_ROLE_KEYS
        else:
            target_roles = [
                role
                for role in DRAFT_ROLE_KEYS
                if role in roles
            ]

        if not target_roles:
            target_roles = DRAFT_ROLE_KEYS

        for role in target_roles:
            if champion not in result[role]:
                result[role].append(champion)

    return result


def draft_user_pool_for_role(role):
    role_key = draft_role_key(role)
    role_map = migrated_role_pool_map(SETTINGS)

    if role_key in role_map:
        return list(role_map[role_key])

    # Unknown role: retain the legacy union rather than inventing a role.
    return _clean_champion_list(
        SETTINGS.get("champion_pool")
        or []
    )


def draft_fit_confidence(score, source, relationships):
    """
    Draft-fit confidence, not win probability.

    Confidence is based only on RiftSense's deterministic fit score plus the
    amount of visible matchup/synergy evidence and whether the champion comes
    from the user's configured role pool.
    """
    try:
        value = 38.0 + (
            max(1.0, min(9.8, float(score))) - 1.0
        ) / 8.8 * 56.0
    except Exception:
        value = 55.0

    if source == "MY_POOL":
        value += 4.0
    elif source == "ROLE_FALLBACK":
        value -= 6.0

    relationships = relationships or {}
    value += min(
        4.0,
        1.5 * len(relationships.get("synergy", []) or []),
    )
    value += min(
        4.0,
        1.5 * len(relationships.get("good_into", []) or []),
    )
    value -= min(
        5.0,
        2.0 * len(relationships.get("bad_into", []) or []),
    )

    value = int(round(max(35.0, min(96.0, value))))
    label = (
        "HIGH"
        if value >= 80
        else "MEDIUM"
        if value >= 60
        else "LOW"
    )
    return value, label


def draft_pick_context(session, local_cell, role, their_team, dd):
    """
    Describe whether the recommendation is being made as a blind/safe pick or
    with the opposing role already visible.

    This is advisory only and never performs a pick.
    """
    role_key = draft_role_key(role)

    if role_key != "UNKNOWN":
        for entry in their_team or []:
            enemy_role = draft_role_key(
                entry.get("assignedPosition")
            )
            champion = dd.champion_name(
                entry.get("championId", 0)
            )
            if (
                enemy_role == role_key
                and champion
            ):
                return {
                    "key": "COUNTER",
                    "label": "COUNTER PICK",
                    "detail": (
                        f"Enemy {draft_role_display(role_key)} is visible as {champion}."
                    ),
                    "enemy": champion,
                }

    actions = []
    for group in (session or {}).get("actions") or []:
        if isinstance(group, list):
            actions.extend(
                action
                for action in group
                if isinstance(action, dict)
            )

    pick_actions = [
        action
        for action in actions
        if str(action.get("type", "")).lower() == "pick"
    ]
    local_action = next(
        (
            action
            for action in pick_actions
            if action.get("actorCellId") == local_cell
            and not action.get("completed", False)
        ),
        None,
    )

    if local_action is not None:
        ordered = sorted(
            pick_actions,
            key=lambda action: int(action.get("id", 9999) or 9999),
        )
        try:
            position = ordered.index(local_action)
        except ValueError:
            position = 99

        if position <= 2:
            return {
                "key": "BLIND",
                "label": "SAFE PICK",
                "detail": "Your pick is early and the lane opponent is not visible yet.",
                "enemy": "",
            }

    return {
        "key": "OPEN",
        "label": "SAFE PICK",
        "detail": "No same-role enemy is visible yet; prioritize a stable role fit.",
        "enemy": "",
    }


def team_needs(ally_names):
    ap = sum(damage_type(x) in {"AP", "MIXED"} for x in ally_names)
    ad = sum(damage_type(x) in {"AD", "MIXED"} for x in ally_names)
    cc = sum(champion_in_list(x, TRAITS.get("highCC", [])) for x in ally_names)
    frontline = sum(x in FRONTLINE_NAMES for x in ally_names)
    engage = sum(x in ENGAGE_NAMES for x in ally_names)
    return {
        "ap": ap,
        "ad": ad,
        "cc": cc,
        "frontline": frontline,
        "engage": engage,
    }


def enemy_shape(enemy_names, dd):
    tanks = sum(x in TANKISH_NAMES for x in enemy_names)
    squishy = 0
    high_cc = 0
    for name in enemy_names:
        tags = set(dd.champion_tags(name))
        if tags & SQUISHY_HINT_TAGS and name not in TANKISH_NAMES:
            squishy += 1
        if champion_in_list(name, TRAITS.get("highCC", [])):
            high_cc += 1
    return {"tanks": tanks, "squishy": squishy, "high_cc": high_cc}


def champion_tier(champion_name):
    meta_tier = meta_tier_for(
        champion_name
    ) if "meta_tier_for" in globals() else ""
    if meta_tier:
        return meta_tier

    tiers = TIER_DATA.get(
        "tiers",
        {},
    ) or {}
    return str(
        tiers.get(
            champion_name,
            "?",
        )
    ).upper()


def tier_source_label():
    return (
        "Tier source: Meta Consensus when cached • "
        "local tier_data.json fallback"
    )



AOE_FOLLOWUP_CHAMPIONS = {
    "Annie", "Brand", "Diana", "Galio", "Katarina", "Kennen", "Miss Fortune",
    "Neeko", "Orianna", "Rumble", "Samira", "Seraphine", "Swain", "Syndra",
    "Viktor", "Yasuo", "Yone", "Ziggs",
}

HYPERCARRY_ALLIES = {
    "Aphelios", "Jinx", "Kai'Sa", "Kog'Maw", "Samira", "Smolder",
    "Tristana", "Twitch", "Vayne", "Xayah", "Zeri",
}

DISENGAGE_ENEMIES = {
    "Alistar", "Gragas", "Janna", "Lulu", "Milio", "Poppy", "Renata Glasc",
    "Taliyah", "Thresh", "Zilean",
}

DIVER_CANDIDATES = {
    "Wukong", "Nocturne", "Jarvan IV", "Warwick", "Vi", "Jax",
}


def _unique_in_team(preferred_names, actual_names, limit=3):
    actual = set(actual_names)
    result = []
    for name in preferred_names:
        if name in actual and name not in result:
            result.append(name)
            if len(result) >= limit:
                break
    return result


def draft_relationship_details(candidate, profile, ally_names, enemy_names, dd):
    """
    Explain candidate-specific ally synergy and enemy matchups.

    Explicit editable relationships are combined with composition/archetype
    heuristics. These are draft-fit heuristics, not live win-rate claims.
    """
    rel = DRAFT_RELATIONSHIPS.get(candidate, {}) or {}

    synergy = _unique_in_team(
        rel.get("synergyWith", []),
        ally_names,
        limit=3,
    )
    good_into = _unique_in_team(
        rel.get("goodInto", []),
        enemy_names,
        limit=3,
    )
    bad_into = _unique_in_team(
        rel.get("badInto", []),
        enemy_names,
        limit=3,
    )

    frontline = int(profile.get("frontline", 0))
    engage = int(profile.get("engage", 0))
    cc = int(profile.get("cc", 0))
    knockup = int(profile.get("knockup", 0))
    anti_squishy = int(profile.get("antiSquishy", 0))
    anti_tank = int(profile.get("antiTank", 0))

    # Team-specific synergy: engage champions work well with allied AoE follow-up.
    if engage >= 2:
        for ally in ally_names:
            if ally in AOE_FOLLOWUP_CHAMPIONS and ally not in synergy:
                synergy.append(ally)
                if len(synergy) >= 3:
                    break

    # Frontline is particularly valuable next to a visible hypercarry.
    if frontline >= 3 and len(synergy) < 3:
        for ally in ally_names:
            if ally in HYPERCARRY_ALLIES and ally not in synergy:
                synergy.append(ally)
                if len(synergy) >= 3:
                    break

    # Yasuo is especially relevant to knock-up junglers.
    if knockup >= 2 and "Yasuo" in ally_names and "Yasuo" not in synergy:
        synergy.insert(0, "Yasuo")
        synergy = synergy[:3]

    # Generic enemy-fit additions from Riot champion tags / local traits.
    for enemy in enemy_names:
        if enemy in good_into or enemy in bad_into:
            continue

        tags = set(dd.champion_tags(enemy))
        is_tank = enemy in TANKISH_NAMES or "Tank" in tags
        is_squishy = bool(tags & SQUISHY_HINT_TAGS) and not is_tank

        if anti_squishy >= 3 and is_squishy and len(good_into) < 3:
            good_into.append(enemy)
            continue

        if anti_tank >= 3 and is_tank and len(good_into) < 3:
            good_into.append(enemy)
            continue

        if (
            candidate in DIVER_CANDIDATES
            and enemy in DISENGAGE_ENEMIES
            and len(bad_into) < 3
        ):
            bad_into.append(enemy)

    # Small score contribution: relationships help ranking, but do not overpower
    # the broader composition-needs model.
    score_delta = 0.0
    score_delta += min(0.45, 0.16 * len(synergy))
    score_delta += min(0.45, 0.18 * len(good_into))
    score_delta -= min(0.60, 0.22 * len(bad_into))

    if synergy:
        synergy_text = "Synergy: " + ", ".join(synergy)
    else:
        synergy_text = "Synergy: no strong specific pair detected yet"

    matchup_parts = []
    if good_into:
        matchup_parts.append("Good vs " + ", ".join(good_into))
    if bad_into:
        matchup_parts.append("Harder vs " + ", ".join(bad_into))
    matchup_text = " | ".join(matchup_parts) if matchup_parts else "Matchups: neutral so far"

    identity = draft_team_identity(list(ally_names) + [candidate])

    return {
        "synergy": synergy,
        "good_into": good_into,
        "bad_into": bad_into,
        "synergy_text": synergy_text,
        "matchup_text": matchup_text,
        "score_delta": score_delta,
        "identity": identity,
    }


def score_draft_pick(candidate, profile, ally_names, enemy_names, dd):
    score = float(profile.get("base", 6.0))
    reasons = []

    # Patch-meta strength is a modest draft signal, not the decision-maker.
    # Cached five-source consensus is preferred; local tier_data.json is the
    # offline fallback. Composition/matchup still has more room to move the score.
    tier = champion_tier(
        candidate
    )
    tier_adjustment = {
        "S+": 0.55,
        "S": 0.45,
        "S-": 0.35,
        "A+": 0.25,
        "A": 0.15,
        "A-": 0.05,
        "B": 0.00,
        "C": -0.15,
        "D": -0.30,
    }.get(
        tier,
        0.0,
    )
    score += tier_adjustment
    if tier in {
        "S+",
        "S",
        "S-",
    }:
        reasons.append(
            f"{tier} meta tier"
        )

    needs = team_needs(ally_names)
    enemy = enemy_shape(enemy_names, dd)

    candidate_damage = profile.get("damage", "AD")
    frontline = int(profile.get("frontline", 0))
    engage = int(profile.get("engage", 0))
    cc = int(profile.get("cc", 0))

    # Damage balance
    if needs["ap"] == 0 and candidate_damage in {"AP", "MIXED"}:
        score += 1.05
        reasons.append("adds needed magic damage")
    elif needs["ad"] == 0 and candidate_damage in {"AD", "MIXED"}:
        score += 0.75
        reasons.append("adds needed physical damage")
    elif needs["ap"] >= 3 and candidate_damage == "AP":
        score -= 0.35
    elif needs["ad"] >= 3 and candidate_damage == "AD":
        score -= 0.25

    # Team structure
    if needs["frontline"] == 0 and frontline >= 2:
        score += 0.28 * frontline
        reasons.append("gives your team a frontline")
    elif needs["frontline"] <= 1 and frontline >= 3:
        score += 0.30

    if needs["engage"] == 0 and engage >= 2:
        score += 0.22 * engage
        reasons.append("adds reliable engage")

    if needs["cc"] == 0 and cc >= 2:
        score += 0.18 * cc
        reasons.append("adds hard crowd control")

    # Existing direct synergy.
    if "Yasuo" in ally_names and int(profile.get("knockup", 0)) >= 2:
        score += 0.75
        reasons.append("strong Yasuo knock-up synergy")

    # Enemy composition shape.
    if enemy["squishy"] >= 3 and int(profile.get("antiSquishy", 0)) >= 3:
        score += 0.45
        reasons.append("good access to a squishy enemy back line")

    if enemy["tanks"] >= 2 and int(profile.get("antiTank", 0)) >= 3:
        score += 0.40
        reasons.append("handles a tankier enemy composition well")

    if enemy["high_cc"] >= 3 and frontline >= 3:
        score += 0.25
        reasons.append("durable into their CC-heavy composition")

    # NEW: exact visible ally synergies + favorable/unfavorable enemy picks.
    relationships = draft_relationship_details(
        candidate,
        profile,
        ally_names,
        enemy_names,
        dd,
    )
    score += relationships["score_delta"]

    if relationships["synergy"]:
        reasons.append(
            "specific synergy with " + ", ".join(relationships["synergy"][:2])
        )

    if relationships["good_into"]:
        reasons.append(
            "good into " + ", ".join(relationships["good_into"][:2])
        )

    if relationships["bad_into"]:
        reasons.append(
            "watch " + ", ".join(relationships["bad_into"][:2])
        )

    # Do not suggest a champion already visibly selected by either team.
    if candidate in ally_names or candidate in enemy_names:
        return -99.0, ["already selected"], relationships

    score = max(1.0, min(9.8, score))
    if not reasons:
        reasons.append(profile.get("summary", "solid composition fit"))

    return round(score, 1), reasons[:3], relationships



def all_champion_names(dd):
    """
    Return every champion known to the currently loaded Riot Data Dragon data.
    Curated local profiles are included as a fallback if static data is offline.
    """
    names = set(DRAFT_PROFILES.keys())
    for champion in (getattr(dd, "champion_data", {}) or {}).values():
        name = champion.get("name")
        if name:
            names.add(name)
    return sorted(names)


def generic_draft_profile(champion, dd):
    """
    Build a conservative composition profile for a champion that does not yet
    have a hand-tuned draft_profiles.json entry.

    Generic profiles are only used for champions the user explicitly adds to
    MY POOL. They are intentionally less opinionated than curated profiles.
    """
    tags = set(dd.champion_tags(champion) or [])
    known_damage = damage_type(champion)

    if known_damage != "UNKNOWN":
        damage = known_damage
    elif "Mage" in tags and "Marksman" not in tags:
        damage = "AP"
    elif "Marksman" in tags:
        damage = "AD"
    elif "Assassin" in tags or "Fighter" in tags:
        damage = "MIXED"
    else:
        damage = "MIXED"

    is_tank = champion in FRONTLINE_NAMES or "Tank" in tags
    is_engage = champion in ENGAGE_NAMES
    has_cc = champion_in_list(champion, TRAITS.get("highCC", []))

    anti_squishy = 3 if ("Assassin" in tags or "Marksman" in tags) else 2
    anti_tank = 3 if "Fighter" in tags else 2

    return {
        "role": ["ANY"],
        "damage": damage,
        "frontline": 3 if is_tank else 1,
        "engage": 3 if is_engage else 1,
        "cc": 3 if has_cc else 1,
        "knockup": 0,
        "antiSquishy": anti_squishy,
        "antiTank": anti_tank,
        "base": 5.4,
        "summary": "generic profile generated from Riot champion tags",
        "profileSource": "GENERIC",
    }


def draft_profile_for_candidate(champion, dd):
    curated = DRAFT_PROFILES.get(champion)
    if curated:
        profile = dict(curated)
        profile.setdefault("profileSource", "CURATED")
        return profile
    return generic_draft_profile(champion, dd)


def rank_draft_picks(
    role: str | None,
    ally_names: list[str],
    enemy_names: list[str],
    dd,
    excluded_names: list[str] | None = None,
    pick_context: dict | None = None,
) -> list[DraftSuggestion]:
    role_key = draft_role_key(role)

    if role_key == "UNKNOWN":
        return []

    excluded = {
        normalize_name(name)
        for name in (excluded_names or [])
        if str(name or "").strip()
    }

    user_pool = draft_user_pool_for_role(
        role_key
    )

    results = []
    seen = set()

    def consider(candidate, profile, source):
        candidate = str(candidate or "").strip()
        key = normalize_name(candidate)

        if (
            not candidate
            or key in excluded
            or key in seen
            or key in {"unknown", "-"}
        ):
            return

        profile = dict(
            profile
            or generic_draft_profile(
                candidate,
                dd,
            )
        )

        # Role-specific MY POOL is an explicit user declaration. Trust it even
        # when an older curated profile only listed another role.
        if (
            source == "MY_POOL"
            and role_key in DRAFT_ROLE_KEYS
        ):
            profile["role"] = [
                role_key
            ]

        allowed_roles = draft_profile_role_keys(
            profile
        )
        if (
            role_key != "UNKNOWN"
            and "ANY" not in allowed_roles
            and role_key not in allowed_roles
        ):
            return

        score, reasons, relationships = score_draft_pick(
            candidate,
            profile,
            ally_names,
            enemy_names,
            dd,
        )
        reasons = list(reasons or [])
        relationships = dict(
            relationships
            or {}
        )

        context = dict(
            pick_context
            or {}
        )
        if (
            context.get("key") == "COUNTER"
            and context.get("enemy")
        ):
            lane_enemy = context.get("enemy")
            if lane_enemy in (
                relationships.get(
                    "good_into",
                    [],
                )
                or []
            ):
                score = min(
                    9.8,
                    float(score) + 0.45,
                )
                reasons.insert(
                    0,
                    f"counter fit into {lane_enemy}",
                )
            elif lane_enemy in (
                relationships.get(
                    "bad_into",
                    [],
                )
                or []
            ):
                score = max(
                    1.0,
                    float(score) - 0.55,
                )
                reasons.insert(
                    0,
                    f"riskier into {lane_enemy}",
                )

        if source == "ROLE_FALLBACK":
            role_name = draft_role_display(
                role_key
            )
            reasons.insert(
                0,
                f"fits assigned {role_name} role",
            )
        elif source == "MY_POOL":
            reasons.insert(
                0,
                f"in your {draft_role_display(role_key)} pool",
            )

        reasons = reasons[:3]

        if score > 0:
            confidence, confidence_label = draft_fit_confidence(
                score,
                source,
                relationships,
            )
            relationships["source"] = source
            relationships["role_key"] = role_key
            relationships["confidence"] = confidence
            relationships["confidence_label"] = confidence_label
            relationships["pick_context"] = dict(
                pick_context
                or {}
            )
            relationships["why_reasons"] = list(
                reasons
            )

            seen.add(key)
            results.append(
                DraftSuggestion(
                    score=float(score),
                    champion=candidate,
                    reasons=list(reasons),
                    profile=dict(profile),
                    relationships=dict(relationships),
                )
            )

    # 1) Prefer the user's explicit pool for the assigned role.
    for candidate in user_pool:
        consider(
            candidate,
            draft_profile_for_candidate(
                candidate,
                dd,
            ),
            "MY_POOL",
        )

    # 2) Fill missing slots with conservative role-specific fallback picks.
    if role_key in DRAFT_ROLE_FALLBACK_POOL and len(results) < 3:
        for candidate in DRAFT_ROLE_FALLBACK_POOL[role_key]:
            if len(results) >= 3:
                break

            profile = generic_draft_profile(
                candidate,
                dd,
            )
            profile["role"] = [
                role_key
            ]
            profile["profileSource"] = "ROLE_FALLBACK"
            profile["base"] = max(
                5.6,
                float(
                    profile.get(
                        "base",
                        5.4,
                    )
                    or 5.4
                ),
            )

            consider(
                candidate,
                profile,
                "ROLE_FALLBACK",
            )

    # MY POOL is authoritative. Fallback suggestions fill empty slots but
    # never jump above a viable champion the user explicitly configured for
    # this role.
    results.sort(
        key=lambda item: (
            0
            if (
                item[4]
                or {}
            ).get(
                "source"
            )
            == "MY_POOL"
            else 1,
            -item[0],
            item[1],
        )
    )
    return results[:3]



