DEFAULT_RANKED_SEASON = {
    "year_name": "2026 Ranked Year",
    "year_start_local": "2026-01-08T12:00:00",
    "name": "2026 Season 3",
    "start_local": "2026-07-29T12:00:00",
    "queues": {
        "420": "Ranked Solo/Duo",
        "440": "Ranked Flex",
    },
}


def current_ranked_season():
    data = load_json(
        RANKED_SEASON_PATH,
        DEFAULT_RANKED_SEASON,
    )
    if not isinstance(data, dict):
        data = dict(DEFAULT_RANKED_SEASON)

    name = str(
        data.get(
            "name",
            DEFAULT_RANKED_SEASON["name"],
        )
    )
    start_text = str(
        data.get(
            "start_local",
            DEFAULT_RANKED_SEASON["start_local"],
        )
    )
    queues_raw = (
        data.get("queues")
        or DEFAULT_RANKED_SEASON["queues"]
    )

    queues = {}
    for key, value in queues_raw.items():
        try:
            queue_id = int(key)
        except Exception:
            continue
        queues[queue_id] = str(value)

    if not queues:
        queues = {
            420: "Ranked Solo/Duo",
            440: "Ranked Flex",
        }

    try:
        start_dt = datetime.fromisoformat(
            start_text
        )
    except Exception:
        start_dt = datetime(
            2026,
            7,
            29,
            12,
            0,
            0,
        )

    year_name = str(
        data.get(
            "year_name",
            DEFAULT_RANKED_SEASON["year_name"],
        )
    )
    year_start_text = str(
        data.get(
            "year_start_local",
            DEFAULT_RANKED_SEASON["year_start_local"],
        )
    )
    try:
        year_start_dt = datetime.fromisoformat(
            year_start_text
        )
    except Exception:
        year_start_dt = datetime(
            2026,
            1,
            8,
            12,
            0,
            0,
        )

    return {
        "year_name": year_name,
        "year_start_local": year_start_dt,
        "year_start_epoch": int(
            year_start_dt.timestamp()
        ),
        "year_start_ms": int(
            year_start_dt.timestamp()
            * 1000
        ),
        "name": name,
        "start_local": start_dt,
        "start_epoch": int(
            start_dt.timestamp()
        ),
        "start_ms": int(
            start_dt.timestamp()
            * 1000
        ),
        "queues": queues,
    }


RANKED_HISTORY_SCOPES = {
    "2026_YEAR": "2026 Ranked Year (S1–S3)",
    "CURRENT_SEASON": "Current Season 3 only",
}


def ranked_history_scope_info(
    scope,
):
    season = current_ranked_season()
    scope = str(
        scope
        or "2026_YEAR"
    ).strip().upper()

    if (
        scope == "CURRENT_SEASON"
        or scope.startswith(
            "CURRENT SEASON"
        )
    ):
        return {
            "key": "CURRENT_SEASON",
            "label": RANKED_HISTORY_SCOPES[
                "CURRENT_SEASON"
            ],
            "name": season["name"],
            "start_local": season[
                "start_local"
            ],
            "start_epoch": season[
                "start_epoch"
            ],
            "start_ms": season[
                "start_ms"
            ],
        }

    return {
        "key": "2026_YEAR",
        "label": RANKED_HISTORY_SCOPES[
            "2026_YEAR"
        ],
        "name": season[
            "year_name"
        ],
        "start_local": season[
            "year_start_local"
        ],
        "start_epoch": season[
            "year_start_epoch"
        ],
        "start_ms": season[
            "year_start_ms"
        ],
    }


def is_ranked_row_in_scope(
    row,
    scope="2026_YEAR",
    queue_ids=None,
):
    season = current_ranked_season()
    scope_info = ranked_history_scope_info(
        scope
    )

    queue_id = int(
        (row or {}).get(
            "queue_id",
            0,
        )
        or 0
    )
    allowed = set(
        int(queue_id)
        for queue_id in (
            queue_ids
            if queue_ids is not None
            else season["queues"].keys()
        )
    )
    if queue_id not in allowed:
        return False

    creation_ms = int(
        (row or {}).get(
            "game_creation_ms",
            0,
        )
        or 0
    )
    return creation_ms >= scope_info[
        "start_ms"
    ]


def ranked_queue_name(queue_id):
    season = current_ranked_season()
    return season["queues"].get(
        int(queue_id or 0),
        f"Ranked Q{queue_id}",
    )


def is_current_season_ranked_row(
    row,
    queue_ids=None,
):
    return is_ranked_row_in_scope(
        row,
        scope="CURRENT_SEASON",
        queue_ids=queue_ids,
    )


