def normalize_rank_snapshot(
    entries,
):
    result = {
        "solo": None,
        "flex": None,
    }

    for entry in (
        entries
        if isinstance(
            entries,
            list,
        )
        else []
    ):
        queue_type = str(
            entry.get(
                "queueType",
                "",
            )
        ).upper()

        compact = {
            "queue_type": queue_type,
            "tier": str(
                entry.get(
                    "tier",
                    "",
                )
            ).upper(),
            "rank": str(
                entry.get(
                    "rank",
                    "",
                )
            ).upper(),
            "league_points": int(
                entry.get(
                    "leaguePoints",
                    0,
                )
                or 0
            ),
            "wins": int(
                entry.get(
                    "wins",
                    0,
                )
                or 0
            ),
            "losses": int(
                entry.get(
                    "losses",
                    0,
                )
                or 0
            ),
        }

        if queue_type == "RANKED_SOLO_5X5":
            result["solo"] = compact
        elif queue_type in {
            "RANKED_FLEX_SR",
            "RANKED_FLEX_5X5",
        }:
            result["flex"] = compact

    return result


def rank_entry_text(
    entry: dict | None,
) -> str:
    if not entry:
        return "UNRANKED"

    rank = RankEntry.from_mapping(entry)
    tier = rank.tier.title()
    division = rank.division
    lp = rank.league_points

    if tier in {"Master", "Grandmaster", "Challenger"}:
        return f"{tier.upper()} — {lp} LP"

    return f"{tier.upper()} {division} — {lp} LP".strip()




def _rank_int(
    value,
    default=0,
):
    try:
        return int(
            value
        )
    except Exception:
        try:
            return int(
                float(
                    value
                )
            )
        except Exception:
            return int(
                default
            )


def normalize_lcu_rank_snapshot(
    payload,
):
    """
    Normalize the local League Client ranked-stats response.

    LCU field names have changed across client builds, so this accepts the
    common queueMap/list shapes and several field aliases. If the local endpoint
    cannot provide a valid queue entry, callers keep the last Riot API snapshot.
    """
    result = {
        "solo": None,
        "flex": None,
    }
    if not isinstance(
        payload,
        dict,
    ):
        return result

    candidates = []

    queue_map = payload.get(
        "queueMap"
    )
    if isinstance(
        queue_map,
        dict,
    ):
        for queue_name, row in queue_map.items():
            if isinstance(
                row,
                dict,
            ):
                candidates.append(
                    (
                        str(
                            queue_name
                        ),
                        row,
                    )
                )

    for key in (
        "queues",
        "queueEntries",
        "rankedQueues",
    ):
        rows = payload.get(
            key
        )
        if isinstance(
            rows,
            list,
        ):
            for row in rows:
                if not isinstance(
                    row,
                    dict,
                ):
                    continue
                queue_name = (
                    row.get(
                        "queueType"
                    )
                    or row.get(
                        "queue"
                    )
                    or row.get(
                        "queueName"
                    )
                    or ""
                )
                candidates.append(
                    (
                        str(
                            queue_name
                        ),
                        row,
                    )
                )

    # Some client builds may expose direct queue objects.
    for key, target in (
        (
            "solo",
            "RANKED_SOLO_5X5",
        ),
        (
            "soloQueue",
            "RANKED_SOLO_5X5",
        ),
        (
            "flex",
            "RANKED_FLEX_SR",
        ),
        (
            "flexQueue",
            "RANKED_FLEX_SR",
        ),
    ):
        row = payload.get(
            key
        )
        if isinstance(
            row,
            dict,
        ):
            candidates.append(
                (
                    target,
                    row,
                )
            )

    def first_value(
        row,
        names,
        default="",
    ):
        for name in names:
            if name in row and row.get(
                name
            ) not in (
                None,
                "",
            ):
                return row.get(
                    name
                )
        return default

    for queue_name, row in candidates:
        queue_key = str(
            queue_name
            or first_value(
                row,
                (
                    "queueType",
                    "queue",
                    "queueName",
                ),
            )
            or ""
        ).upper().replace(
            "X",
            "X",
        )

        compact = {
            "queue_type": queue_key,
            "tier": str(
                first_value(
                    row,
                    (
                        "tier",
                        "currentSeasonTier",
                        "currentTier",
                        "highestTier",
                    ),
                )
                or ""
            ).upper(),
            "rank": str(
                first_value(
                    row,
                    (
                        "rank",
                        "division",
                        "currentSeasonDivision",
                        "currentDivision",
                    ),
                )
                or ""
            ).upper(),
            "league_points": _rank_int(
                first_value(
                    row,
                    (
                        "leaguePoints",
                        "league_points",
                        "lp",
                    ),
                    0,
                ),
                0,
            ),
            "wins": _rank_int(
                first_value(
                    row,
                    (
                        "wins",
                        "winCount",
                    ),
                    0,
                ),
                0,
            ),
            "losses": _rank_int(
                first_value(
                    row,
                    (
                        "losses",
                        "lossCount",
                    ),
                    0,
                ),
                0,
            ),
        }

        if not compact[
            "tier"
        ]:
            continue

        normalized_queue = re.sub(
            r"[^A-Z0-9]",
            "",
            queue_key,
        )
        if (
            "RANKEDSOLO5X5"
            in normalized_queue
            or normalized_queue
            in {
                "SOLO",
                "SOLOQUEUE",
            }
        ):
            result[
                "solo"
            ] = compact
        elif (
            "RANKEDFLEX"
            in normalized_queue
            or normalized_queue
            in {
                "FLEX",
                "FLEXQUEUE",
            }
        ):
            result[
                "flex"
            ] = compact

    return result


RANK_TIER_ORDER = {
    "IRON": 0,
    "BRONZE": 1,
    "SILVER": 2,
    "GOLD": 3,
    "PLATINUM": 4,
    "EMERALD": 5,
    "DIAMOND": 6,
    "MASTER": 7,
    "GRANDMASTER": 8,
    "CHALLENGER": 9,
}

RANK_DIVISION_OFFSET = {
    "IV": 0,
    "III": 100,
    "II": 200,
    "I": 300,
}


def rank_progress_score(
    entry,
):
    """Comparable display score for plotting saved Riot rank snapshots."""
    if not isinstance(
        entry,
        dict,
    ) or not entry:
        return None

    tier = str(
        entry.get(
            "tier",
            "",
        )
        or ""
    ).upper()
    if tier not in RANK_TIER_ORDER:
        return None

    lp = max(
        0,
        int(
            entry.get(
                "league_points",
                0,
            )
            or 0
        ),
    )
    base = RANK_TIER_ORDER[
        tier
    ] * 400

    if tier in {
        "MASTER",
        "GRANDMASTER",
        "CHALLENGER",
    }:
        return float(
            base
            + lp
        )

    division = str(
        entry.get(
            "rank",
            "IV",
        )
        or "IV"
    ).upper()
    return float(
        base
        + RANK_DIVISION_OFFSET.get(
            division,
            0,
        )
        + lp
    )



def rank_progress_band_label(
    score,
):
    """
    Convert the 100-point ranked-ladder display bands back to Riot tier/division.

    The plotting score uses 400 points per tier and 100 per division.
    """
    try:
        band = int(
            float(
                score
            )
            // 100
        ) * 100
    except Exception:
        return ""

    tier_index = max(
        0,
        band // 400,
    )
    tier_name = next(
        (
            tier
            for tier, index in RANK_TIER_ORDER.items()
            if index == tier_index
        ),
        "",
    )
    if not tier_name:
        return ""

    if tier_name in {
        "MASTER",
        "GRANDMASTER",
        "CHALLENGER",
    }:
        return tier_name

    within = max(
        0,
        band
        - tier_index
        * 400,
    )
    division = {
        0: "IV",
        100: "III",
        200: "II",
        300: "I",
    }.get(
        within,
        "IV",
    )
    return f"{tier_name} {division}"


def rank_progress_net_change_text(
    start_score,
    end_score,
):
    try:
        delta = int(
            round(
                float(
                    end_score
                )
                - float(
                    start_score
                )
            )
        )
    except Exception:
        return "-"

    return f"{delta:+d} LP"


def record_rank_progress_snapshot(
    riot_id,
    rank_snapshot,
):
    """
    Persist actual rank snapshots across RiftSense versions.

    A new point is written only when Solo/Flex rank data changes, so repeated
    manual syncs without a game do not clutter the chart.
    """
    if not isinstance(
        rank_snapshot,
        dict,
    ):
        return False

    solo = rank_snapshot.get(
        "solo"
    )
    flex = rank_snapshot.get(
        "flex"
    )
    if not solo and not flex:
        return False

    payload = load_json(
        RANK_PROGRESS_PATH,
        [],
    )
    if not isinstance(
        payload,
        list,
    ):
        payload = []

    entry = {
        "captured_at": datetime.now().isoformat(
            timespec="seconds"
        ),
        "riot_id": str(
            riot_id
            or ""
        ),
        "solo": dict(
            solo
        ) if isinstance(
            solo,
            dict,
        ) else None,
        "flex": dict(
            flex
        ) if isinstance(
            flex,
            dict,
        ) else None,
    }

    if payload:
        last = payload[
            -1
        ]
        if (
            str(
                last.get(
                    "riot_id",
                    "",
                )
            )
            == entry[
                "riot_id"
            ]
            and last.get(
                "solo"
            )
            == entry[
                "solo"
            ]
            and last.get(
                "flex"
            )
            == entry[
                "flex"
            ]
        ):
            return False

    payload.append(
        entry
    )
    # Rank points are only written when the rank snapshot changes.
    # Keep a long archive so General > Rank Progress can show 1Y / ALL views.
    payload = payload[
        -2000:
    ]
    return write_json_atomic(
        RANK_PROGRESS_PATH,
        payload,
    )


def load_rank_progress(
    riot_id="",
):
    payload = load_json(
        RANK_PROGRESS_PATH,
        [],
    )
    if not isinstance(
        payload,
        list,
    ):
        return []

    riot_id = str(
        riot_id
        or ""
    ).strip()
    if not riot_id:
        return payload

    return [
        row
        for row in payload
        if str(
            row.get(
                "riot_id",
                "",
            )
        ).strip()
        == riot_id
    ]



