ROLE_TIER_LANES = {
    "TOP": "top",
    "JUNGLE": "jungle",
    "MID": "middle",
    "ADC": "bottom",
    "SUPPORT": "support",
}

ROLE_TIER_ORDER = (
    "S+",
    "S",
    "A",
    "B",
    "C",
    "D",
)


def normalize_display_tier(
    tier,
):
    """
    RiftSense deliberately uses six easy-to-scan display buckets:

      S+ / S / A / B / C / D

    Public-source subtiers such as S-, A+, A-, B+ ... are preserved as
    source_tier for the tooltip but collapsed for the visual Tier List.
    """
    value = str(
        tier
        or ""
    ).strip().upper()

    if value == "S+":
        return "S+"
    if value.startswith(
        "S"
    ):
        return "S"
    if value.startswith(
        "A"
    ):
        return "A"
    if value.startswith(
        "B"
    ):
        return "B"
    if value.startswith(
        "C"
    ):
        return "C"
    if value.startswith(
        "D"
    ):
        return "D"
    return "D"


