def role_tier_cache_fresh(
    role,
    max_age_hours=ROLE_TIER_REFRESH_HOURS,
):
    entry = role_tier_cache_entry(
        role
    )
    timestamp = float(
        entry.get(
            "updated_at_epoch",
            0,
        )
        or 0
    )
    if timestamp <= 0:
        return False
    return (
        time.time()
        - timestamp
    ) <= float(
        max_age_hours
    ) * 3600.0


def _role_tier_visible_text(
    raw,
):
    value = html_lib.unescape(
        str(
            raw
            or ""
        )
    )
    value = re.sub(
        r"(?is)<script\b[^>]*>.*?</script>",
        " ",
        value,
    )
    value = re.sub(
        r"(?is)<style\b[^>]*>.*?</style>",
        " ",
        value,
    )
    value = re.sub(
        r"(?s)<[^>]+>",
        " ",
        value,
    )
    value = value.replace(
        "\\u0027",
        "'",
    )
    value = value.replace(
        "\\u0026",
        "&",
    )
    value = re.sub(
        r"\s+",
        " ",
        value,
    )
    return value.strip()


def parse_lolalytics_role_tier(
    raw,
    champion_names,
):
    """
    Parse the visible LoLalytics grid table.

    Expected row shape:
      Champion  Rank  Lane%  Tier  Win%  Pick%  Ban%  Elo...

    Champion names are restricted to the current Riot Data Dragon catalog so
    unrelated page text cannot become a fake champion row.
    """
    visible = _role_tier_visible_text(
        raw
    )

    patch_match = re.search(
        r"\b(?:Patch|PATCH)\s+([0-9]+\.[0-9]+(?:\.[0-9]+)?)",
        visible,
    )
    patch = (
        patch_match.group(
            1
        )
        if patch_match
        else ""
    )

    names = sorted(
        {
            str(
                name
                or ""
            ).strip()
            for name in champion_names
            if str(
                name
                or ""
            ).strip()
        },
        key=len,
        reverse=True,
    )
    if not names:
        return {
            "patch": patch,
            "rows": [],
        }

    name_pattern = "|".join(
        re.escape(
            name
        )
        for name in names
    )

    pattern = re.compile(
        (
            rf"(?P<name>{name_pattern})\s+"
            r"(?P<rank>[0-9]{1,3})\s+"
            r"(?P<lane>[0-9]+(?:\.[0-9]+)?)\s+"
            r"(?P<tier>[SABCD][+-]?)\s*"
            r"(?P<win>[0-9]+(?:\.[0-9]+)?)\s+"
            r"(?P<pick>[0-9]+(?:\.[0-9]+)?)\s+"
            r"(?P<ban>[0-9]+(?:\.[0-9]+)?)"
        ),
        flags=re.IGNORECASE,
    )

    rows = []
    seen = set()
    for match in pattern.finditer(
        visible
    ):
        name = match.group(
            "name"
        )
        key = normalize_name(
            name
        )
        if key in seen:
            continue
        seen.add(
            key
        )
        source_tier = match.group(
            "tier"
        ).upper()
        rows.append({
            "name": name,
            "rank": int(
                match.group(
                    "rank"
                )
            ),
            "lane_pct": float(
                match.group(
                    "lane"
                )
            ),
            "source_tier": source_tier,
            "tier": normalize_display_tier(
                source_tier
            ),
            "win_rate": float(
                match.group(
                    "win"
                )
            ),
            "pick_rate": float(
                match.group(
                    "pick"
                )
            ),
            "ban_rate": float(
                match.group(
                    "ban"
                )
            ),
        })

    rows.sort(
        key=lambda row: int(
            row.get(
                "rank",
                999,
            )
        )
    )

    return {
        "patch": patch,
        "rows": rows,
    }


def fetch_lolalytics_role_tier(
    role,
    champion_names,
    timeout=10.0,
):
    role = str(
        role
        or ""
    ).upper()
    lane = ROLE_TIER_LANES.get(
        role
    )
    if not lane:
        raise ValueError(
            "Unknown tier-list role."
        )

    url = (
        "https://lolalytics.com/lol/tierlist/"
        f"?lane={lane}&view=grid"
    )
    request = Request(
        url,
        headers={
            "User-Agent": (
                "Mozilla/5.0 "
                "(Windows NT 10.0; Win64; x64) "
                f"RiftSense/{APP_VERSION}"
            ),
            "Accept": (
                "text/html,application/xhtml+xml,"
                "application/xml;q=0.9,*/*;q=0.7"
            ),
            "Accept-Language": "en-US,en;q=0.9",
        },
        method="GET",
    )

    with urlopen(
        request,
        timeout=timeout,
    ) as response:
        final_host = (
            urlparse(
                str(
                    response.geturl()
                    or ""
                )
            ).hostname
            or ""
        ).lower()
        if final_host not in {
            "lolalytics.com",
            "www.lolalytics.com",
        }:
            raise RuntimeError(
                "Tier-list source redirected to an unapproved host."
            )

        raw = response.read(
            3_000_000
        ).decode(
            "utf-8",
            errors="ignore",
        )

    parsed = parse_lolalytics_role_tier(
        raw,
        champion_names,
    )
    if len(
        parsed.get(
            "rows",
            []
        )
    ) < 10:
        raise RuntimeError(
            "Tier-list page was reachable, but too few champion rows were parsed."
        )

    return {
        "source": ROLE_TIER_SOURCE_NAME,
        "role": role,
        "patch": parsed.get(
            "patch",
            "",
        ),
        "rank_scope": "Emerald+",
        "queue": "Ranked Solo/Duo",
        "region": "Global",
        "updated_at_epoch": time.time(),
        "updated_at": datetime.now().isoformat(
            timespec="seconds"
        ),
        "rows": parsed.get(
            "rows",
            [],
        ),
    }


def update_role_tier_cache_entry(
    role,
    entry,
):
    payload = load_role_tier_cache()
    payload[
        str(
            role
            or ""
        ).upper()
    ] = entry
    return save_role_tier_cache(
        payload
    )


RIOT_PUBLIC_CLIENT = RiotPublicClient(
    user_agent=f"RiftSense/{APP_VERSION_LABEL}",
)


def riot_api_json(
    url: str,
    api_key: str,
    timeout: float = 12.0,
):
    return RIOT_PUBLIC_CLIENT.get_json(url, api_key, timeout=timeout)


def riot_api_status_hint(status) -> str:
    try:
        status = int(status)
    except (TypeError, ValueError):
        return ""
    if status in {401, 403}:
        return " • Riot API key rejected or expired; generate a fresh Developer key."
    if status == 429:
        return " • Riot API rate limit reached; wait briefly and retry."
    return ""



def riot_account_by_riot_id(
    riot_id,
    route,
    api_key,
):
    riot_id = (riot_id or "").strip()
    if "#" not in riot_id:
        return None, 0, "Use Riot ID format: GameName#TAG"

    game_name, tag_line = riot_id.rsplit(
        "#",
        1,
    )
    game_name = game_name.strip()
    tag_line = tag_line.strip()

    if not game_name or not tag_line:
        return None, 0, "Use Riot ID format: GameName#TAG"

    host = riot_route_host(route)
    url = (
        f"https://{host}.api.riotgames.com"
        f"/riot/account/v1/accounts/by-riot-id/"
        f"{quote(game_name, safe='')}/"
        f"{quote(tag_line, safe='')}"
    )
    data, status, _headers = riot_api_json(
        url,
        api_key,
    )

    if status == 200 and data.get("puuid"):
        return data, status, ""

    message = (
        (data.get("status") or {}).get("message")
        or f"Riot API returned HTTP {status}"
    )
    return None, status or 0, message


def riot_match_ids_page(
    puuid,
    route,
    api_key,
    start=0,
    count=100,
    queue_id=None,
    start_time=None,
):
    host = riot_route_host(route)

    query_data = {
        "start": int(start),
        "count": int(count),
    }

    if queue_id is not None:
        query_data["queue"] = int(
            queue_id
        )

    if start_time is not None:
        query_data["startTime"] = int(
            start_time
        )

    query = urlencode(
        query_data
    )
    url = (
        f"https://{host}.api.riotgames.com"
        f"/lol/match/v5/matches/by-puuid/"
        f"{quote(puuid, safe='')}/ids?{query}"
    )
    return riot_api_json(
        url,
        api_key,
    )


def riot_match_detail(
    match_id,
    route,
    api_key,
):
    host = riot_route_host(route)
    url = (
        f"https://{host}.api.riotgames.com"
        f"/lol/match/v5/matches/"
        f"{quote(str(match_id), safe='')}"
    )
    return riot_api_json(
        url,
        api_key,
    )


def riot_match_summary(
    match,
    puuid,
):
    info = (match or {}).get("info") or {}
    metadata = (match or {}).get("metadata") or {}
    participants = info.get("participants") or []

    participant = next(
        (
            p
            for p in participants
            if p.get("puuid") == puuid
        ),
        None,
    )
    if participant is None:
        return None

    creation_ms = int(
        info.get("gameCreation", 0)
        or info.get("gameStartTimestamp", 0)
        or 0
    )
    if creation_ms:
        date_text = datetime.fromtimestamp(
            creation_ms / 1000.0
        ).isoformat(
            timespec="seconds"
        )
    else:
        date_text = ""

    duration = float(
        info.get("gameDuration", 0)
        or 0
    )
    # Defensive compatibility for old payloads that may expose milliseconds.
    if duration > 100000:
        duration /= 1000.0

    item_ids = []
    for index in range(7):
        item_id = int(
            participant.get(
                f"item{index}",
                0,
            )
            or 0
        )
        if item_id:
            item_ids.append(item_id)

    cs = int(
        participant.get(
            "totalMinionsKilled",
            0,
        )
        or 0
    ) + int(
        participant.get(
            "neutralMinionsKilled",
            0,
        )
        or 0
    )

    return {
        "source": "RIOT",
        "account_puuid": str(
            puuid
            or ""
        ),
        "match_id": metadata.get("matchId") or "",
        "date": date_text,
        "game_creation_ms": creation_ms,
        "champion": participant.get("championName") or "-",
        "win": bool(participant.get("win")),
        "kills": int(participant.get("kills", 0) or 0),
        "deaths": int(participant.get("deaths", 0) or 0),
        "assists": int(participant.get("assists", 0) or 0),
        "cs": cs,
        "duration_seconds": int(duration),
        "queue_id": int(info.get("queueId", 0) or 0),
        "game_mode": info.get("gameMode") or "",
        "role": participant.get("teamPosition") or participant.get("role") or "",
        "item_ids": item_ids,
    }



def match_participant_cs(participant):
    participant = participant or {}
    return int(
        participant.get(
            "totalMinionsKilled",
            0,
        )
        or 0
    ) + int(
        participant.get(
            "neutralMinionsKilled",
            0,
        )
        or 0
    )


def match_participant_role(participant):
    participant = participant or {}
    role = (
        participant.get("teamPosition")
        or participant.get("individualPosition")
        or participant.get("role")
        or ""
    )
    role = str(role).upper()
    labels = {
        "MIDDLE": "MID",
        "BOTTOM": "ADC",
        "UTILITY": "SUPPORT",
        "NONE": "-",
        "INVALID": "-",
    }
    return labels.get(
        role,
        role or "-",
    )


def match_participant_name(participant):
    participant = participant or {}
    game_name = (
        participant.get("riotIdGameName")
        or participant.get("summonerName")
        or "Unknown"
    )
    tag = participant.get("riotIdTagline") or ""
    if tag and "#" not in str(game_name):
        return f"{game_name}#{tag}"
    return str(game_name)


def match_objective_counts(info, team_id):
    for team in (info or {}).get("teams") or []:
        if int(team.get("teamId", 0) or 0) != int(team_id or 0):
            continue

        objectives = team.get("objectives") or {}

        def kills(name):
            return int(
                (objectives.get(name) or {}).get(
                    "kills",
                    0,
                )
                or 0
            )

        return {
            "dragon": kills("dragon"),
            "baron": kills("baron"),
            "herald": kills("riftHerald"),
            "tower": kills("tower"),
        }

    return {
        "dragon": 0,
        "baron": 0,
        "herald": 0,
        "tower": 0,
    }


def match_review_data(match, puuid):
    """
    Build a transparent, stat-based review from Match-V5 data.

    This intentionally does not claim replay-level knowledge. It can identify
    statistical red flags and useful comparisons, but cannot know pathing,
    exact decision context, wave states, vision locations or why a death
    happened without timeline/replay data.
    """
    info = (match or {}).get("info") or {}
    participants = info.get("participants") or []

    player = next(
        (
            participant
            for participant in participants
            if participant.get("puuid") == puuid
        ),
        None,
    )
    if player is None:
        return None

    duration_seconds = float(
        info.get("gameDuration", 0)
        or 0
    )
    if duration_seconds > 100000:
        duration_seconds /= 1000.0
    minutes = max(
        duration_seconds / 60.0,
        1.0,
    )

    team_id = int(
        player.get("teamId", 0)
        or 0
    )
    enemy_team_id = (
        200
        if team_id == 100
        else 100
    )

    allies = [
        participant
        for participant in participants
        if int(
            participant.get(
                "teamId",
                0,
            )
            or 0
        )
        == team_id
    ]

    team_kills = sum(
        int(
            participant.get(
                "kills",
                0,
            )
            or 0
        )
        for participant in allies
    )

    kills = int(
        player.get("kills", 0)
        or 0
    )
    deaths = int(
        player.get("deaths", 0)
        or 0
    )
    assists = int(
        player.get("assists", 0)
        or 0
    )
    cs = match_participant_cs(
        player
    )
    gold = int(
        player.get("goldEarned", 0)
        or 0
    )
    damage = int(
        player.get(
            "totalDamageDealtToChampions",
            0,
        )
        or 0
    )
    vision = float(
        player.get("visionScore", 0)
        or 0
    )
    objective_damage = int(
        player.get(
            "damageDealtToObjectives",
            0,
        )
        or 0
    )

    challenges = player.get("challenges") or {}

    kill_participation = challenges.get(
        "killParticipation"
    )
    if kill_participation is None:
        kill_participation = (
            (kills + assists)
            / max(
                team_kills,
                1,
            )
        )
    kill_participation = float(
        kill_participation
        or 0
    )

    gold_per_min = float(
        challenges.get(
            "goldPerMinute",
            0,
        )
        or 0
    )
    if gold_per_min <= 0:
        gold_per_min = (
            gold / minutes
        )

    vision_per_min = float(
        challenges.get(
            "visionScorePerMinute",
            0,
        )
        or 0
    )
    if vision_per_min <= 0:
        vision_per_min = (
            vision / minutes
        )

    cs_per_min = (
        cs / minutes
    )

    team_damage = sum(
        int(
            participant.get(
                "totalDamageDealtToChampions",
                0,
            )
            or 0
        )
        for participant in allies
    )
    damage_share = (
        damage
        / max(
            team_damage,
            1,
        )
    )

    control_wards = int(
        challenges.get(
            "controlWardsPlaced",
            player.get(
                "visionWardsBoughtInGame",
                0,
            ),
        )
        or 0
    )

    role = match_participant_role(
        player
    )
    raw_role = str(
        player.get("teamPosition")
        or player.get("individualPosition")
        or ""
    ).upper()

    opponent = None
    for participant in participants:
        if int(
            participant.get(
                "teamId",
                0,
            )
            or 0
        ) == team_id:
            continue

        participant_role = str(
            participant.get("teamPosition")
            or participant.get("individualPosition")
            or ""
        ).upper()

        if raw_role and participant_role == raw_role:
            opponent = participant
            break

    if opponent is None:
        enemy_candidates = [
            participant
            for participant in participants
            if int(
                participant.get(
                    "teamId",
                    0,
                )
                or 0
            )
            == enemy_team_id
        ]
        if len(enemy_candidates) == 1:
            opponent = enemy_candidates[0]

    opponent_data = None
    if opponent:
        enemy_allies = [
            participant
            for participant in participants
            if int(
                participant.get(
                    "teamId",
                    0,
                )
                or 0
            )
            == enemy_team_id
        ]
        enemy_team_kills = sum(
            int(
                participant.get(
                    "kills",
                    0,
                )
                or 0
            )
            for participant in enemy_allies
        )

        opponent_cs = match_participant_cs(
            opponent
        )
        opponent_gold = int(
            opponent.get(
                "goldEarned",
                0,
            )
            or 0
        )
        opponent_damage = int(
            opponent.get(
                "totalDamageDealtToChampions",
                0,
            )
            or 0
        )
        opponent_vision = float(
            opponent.get(
                "visionScore",
                0,
            )
            or 0
        )
        opponent_data = {
            "name": match_participant_name(
                opponent
            ),
            "champion": champion_display_name(
                opponent.get(
                    "championName",
                    "-",
                )
            ),
            "raw_champion": opponent.get(
                "championName",
                "-",
            ),
            "kills": int(
                opponent.get(
                    "kills",
                    0,
                )
                or 0
            ),
            "deaths": int(
                opponent.get(
                    "deaths",
                    0,
                )
                or 0
            ),
            "assists": int(
                opponent.get(
                    "assists",
                    0,
                )
                or 0
            ),
            "cs": opponent_cs,
            "cs_per_min": (
                opponent_cs
                / minutes
            ),
            "gold": opponent_gold,
            "gold_diff": (
                gold
                - opponent_gold
            ),
            "damage": opponent_damage,
            "vision": opponent_vision,
            "vision_per_min": (
                opponent_vision
                / minutes
            ),
            "objective_damage": int(
                opponent.get(
                    "damageDealtToObjectives",
                    0,
                )
                or 0
            ),
            "kill_participation": (
                (
                    int(
                        opponent.get(
                            "kills",
                            0,
                        )
                        or 0
                    )
                    + int(
                        opponent.get(
                            "assists",
                            0,
                        )
                        or 0
                    )
                )
                / max(
                    enemy_team_kills,
                    1,
                )
            ),
        }

    team_objectives = match_objective_counts(
        info,
        team_id,
    )
    enemy_objectives = match_objective_counts(
        info,
        enemy_team_id,
    )

    issues = []
    strengths = []

    # Deaths are a strong tempo signal, especially for jungle.
    if deaths >= 8:
        issues.append(
            (
                "High deaths",
                (
                    f"{deaths} deaths is a major tempo loss. "
                    "Review deaths before objectives, forced engages without "
                    "follow-up and fights started while key allies were too far away."
                ),
            )
        )
    elif deaths >= 6:
        issues.append(
            (
                "Death count",
                (
                    f"{deaths} deaths is on the high side. "
                    "Check whether each engage created enough value to justify "
                    "lost farm, map pressure and objective setup."
                ),
            )
        )
    elif deaths <= 3:
        strengths.append(
            (
                "Good survival",
                f"Only {deaths} deaths over {minutes:.0f} minutes.",
            )
        )

    # Participation: particularly actionable for junglers.
    low_kp_threshold = (
        0.50
        if role == "JUNGLE"
        else 0.42
    )
    if (
        team_kills >= 8
        and kill_participation
        < low_kp_threshold
    ):
        issues.append(
            (
                "Low kill participation",
                (
                    f"{kill_participation:.0%} KP. "
                    + (
                        "For jungle this can indicate too much isolated farming, "
                        "late rotations or ganks that do not convert."
                        if role == "JUNGLE"
                        else
                        "You were involved in a relatively small share of your "
                        "team's kills; review rotations and fight timing."
                    )
                ),
            )
        )
    elif (
        team_kills >= 6
        and kill_participation >= 0.68
    ):
        strengths.append(
            (
                "High fight involvement",
                f"{kill_participation:.0%} kill participation.",
            )
        )

    # Same-role economy and farm are more useful than absolute thresholds.
    if opponent_data:
        gold_diff = opponent_data[
            "gold_diff"
        ]
        cspm_diff = (
            cs_per_min
            - opponent_data[
                "cs_per_min"
            ]
        )

        if gold_diff <= -1200:
            issues.append(
                (
                    "Economy deficit",
                    (
                        f"Finished {abs(gold_diff):,}g behind "
                        f"{opponent_data['champion']} in the same role. "
                        "Review deaths, failed ganks, idle time and whether "
                        "objective trades cost too many camps/waves."
                    ),
                )
            )
        elif gold_diff >= 1200:
            strengths.append(
                (
                    "Economy advantage",
                    (
                        f"Finished {gold_diff:,}g ahead of "
                        f"{opponent_data['champion']}."
                    ),
                )
            )

        if cspm_diff <= -0.80:
            issues.append(
                (
                    "Farm / tempo gap",
                    (
                        f"{cs_per_min:.1f} CS/min vs "
                        f"{opponent_data['cs_per_min']:.1f} for "
                        f"{opponent_data['champion']}. "
                        + (
                            "Check camp sequencing, respawn timing and time spent "
                            "waiting around lanes for low-probability ganks."
                            if role == "JUNGLE"
                            else
                            "Check missed waves, recall timing and unnecessary "
                            "roams that did not convert."
                        )
                    ),
                )
            )
        elif cspm_diff >= 0.80:
            strengths.append(
                (
                    "Farm advantage",
                    (
                        f"{cs_per_min:.1f} CS/min vs "
                        f"{opponent_data['cs_per_min']:.1f} in the same role."
                    ),
                )
            )

    # Vision review only becomes a warning when relative evidence supports it.
    if (
        minutes >= 18
        and role in {
            "JUNGLE",
            "SUPPORT",
        }
    ):
        opponent_vpm = (
            opponent_data.get(
                "vision_per_min",
                0,
            )
            if opponent_data
            else 0
        )

        if (
            vision_per_min < 0.50
            and opponent_vpm
            > vision_per_min * 1.25
        ):
            issues.append(
                (
                    "Vision impact",
                    (
                        f"{vision_per_min:.2f} vision/min vs "
                        f"{opponent_vpm:.2f} for the opposing role. "
                        "Review sweeper timing and vision setup 45–90 seconds "
                        "before Dragon/Baron."
                    ),
                )
            )
        elif (
            vision_per_min >= 0.85
            or (
                opponent_vpm > 0
                and vision_per_min
                > opponent_vpm * 1.20
            )
        ):
            strengths.append(
                (
                    "Vision contribution",
                    f"{vision_per_min:.2f} vision score per minute.",
                )
            )

        if (
            control_wards == 0
            and minutes >= 22
        ):
            issues.append(
                (
                    "No control wards recorded",
                    (
                        f"No control wards were recorded in a {minutes:.0f}-minute "
                        "game. For jungle/support, objective setups are usually "
                        "easier when at least some control vision is available."
                    ),
                )
            )

    # Objective comparison for jungle.
    if (
        role == "JUNGLE"
        and opponent_data
    ):
        our_epic = (
            team_objectives["dragon"]
            + team_objectives["baron"]
            + team_objectives["herald"]
        )
        enemy_epic = (
            enemy_objectives["dragon"]
            + enemy_objectives["baron"]
            + enemy_objectives["herald"]
        )
        enemy_obj_damage = opponent_data[
            "objective_damage"
        ]

        if (
            enemy_epic > our_epic
            and enemy_obj_damage
            > max(
                3000,
                objective_damage * 1.5,
            )
        ):
            issues.append(
                (
                    "Objective control",
                    (
                        f"Your team had {our_epic} epic objectives vs "
                        f"{enemy_epic}. Objective damage was {objective_damage:,} "
                        f"vs {enemy_obj_damage:,} for the enemy jungler. "
                        "Review setup before spawn rather than only the final smite."
                    ),
                )
            )

    stolen = int(
        player.get(
            "objectivesStolen",
            0,
        )
        or 0
    )
    if stolen > 0:
        strengths.append(
            (
                "Objective steal",
                f"Recorded {stolen} objective steal(s).",
            )
        )

    if (
        bool(
            player.get(
                "firstBloodKill"
            )
        )
        or bool(
            player.get(
                "firstBloodAssist"
            )
        )
    ):
        strengths.append(
            (
                "Early impact",
                "Participated in first blood.",
            )
        )

    if damage_share >= 0.25:
        strengths.append(
            (
                "Damage contribution",
                f"{damage_share:.0%} of your team's champion damage.",
            )
        )

    # Keep the review concise.
    issues = issues[:5]
    strengths = strengths[:4]

    if not issues:
        issues.append(
            (
                "No obvious statistical red flag",
                (
                    "The Match-V5 stats do not show a clear major mistake. "
                    "The most useful next step would be reviewing key deaths and "
                    "objective setups in a replay/timeline."
                ),
            )
        )

    return {
        "player": player,
        "participants": participants,
        "duration_seconds": int(
            duration_seconds
        ),
        "minutes": minutes,
        "team_id": team_id,
        "role": role,
        "kills": kills,
        "deaths": deaths,
        "assists": assists,
        "cs": cs,
        "cs_per_min": cs_per_min,
        "gold": gold,
        "gold_per_min": gold_per_min,
        "damage": damage,
        "damage_share": damage_share,
        "vision": vision,
        "vision_per_min": vision_per_min,
        "kill_participation": kill_participation,
        "objective_damage": objective_damage,
        "control_wards": control_wards,
        "team_objectives": team_objectives,
        "enemy_objectives": enemy_objectives,
        "opponent": opponent_data,
        "issues": issues,
        "strengths": strengths,
    }


def load_riot_history_index():
    data = load_json(
        RIOT_HISTORY_INDEX_PATH,
        [],
    )
    return data if isinstance(data, list) else []


def save_riot_history_index(rows):
    tmp = RIOT_HISTORY_INDEX_PATH.with_suffix(
        ".json.tmp"
    )
    tmp.write_text(
        json.dumps(
            rows,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    tmp.replace(
        RIOT_HISTORY_INDEX_PATH
    )


class Tooltip:
    def __init__(self, widget, text):
        self.widget = widget
        self.text = text
        self.tip = None
        widget.bind("<Enter>", self.show, add="+")
        widget.bind("<Leave>", self.hide, add="+")

    def _resolved_text(self):
        try:
            if callable(self.text):
                return str(self.text() or "")
            if hasattr(self.text, "get"):
                return str(self.text.get() or "")
        except Exception:
            return ""
        return str(self.text or "")

    def show(self, _event=None):
        text = self._resolved_text()
        if self.tip or not text:
            return
        x = self.widget.winfo_rootx() + 18
        y = self.widget.winfo_rooty() + self.widget.winfo_height() + 6
        self.tip = tk.Toplevel(self.widget)
        self.tip.wm_overrideredirect(True)
        self.tip.wm_geometry(f"+{x}+{y}")
        tk.Label(
            self.tip,
            text=text,
            justify="left",
            relief="solid",
            borderwidth=1,
            padx=8,
            pady=5,
            bg=PANEL_ALT,
            fg=FG,
            highlightthickness=1,
            highlightbackground=BORDER,
            wraplength=420,
        ).pack()

    def hide(self, _event=None):
        if self.tip:
            self.tip.destroy()
            self.tip = None


