        bottom=tk.Frame(self.sidebar,bg=SIDEBAR_BG)
        bottom.pack(side="bottom",fill="x",padx=10,pady=10)
        self.sidebar_connection_var=tk.StringVar(value="● WAITING")
        self.sidebar_connection_label=tk.Label(bottom,textvariable=self.sidebar_connection_var,bg=SIDEBAR_BG,fg=SIDEBAR_MUTED,font=ui_font(7, "bold"))
