    def _make_dashboard_metric_card(
        self,
        parent,
        column,
        title,
        value,
        detail,
        accent,
    ):
        outer = tk.Frame(
            parent,
            bg=PANEL_ALT,
            highlightthickness=1,
            highlightbackground=BORDER,
        )
        outer.grid(
            row=0,
            column=column,
            sticky="nsew",
            padx=(
                0
                if column == 0
                else 4,
                0,
            ),
        )
        tv = tk.StringVar(
            value=title
        )
        vv = tk.StringVar(
            value=value
        )
        dv = tk.StringVar(
            value=detail
        )
        title_label = tk.Label(
            outer,
            textvariable=tv,
            bg=PANEL_ALT,
            fg=MUTED,
            font=ui_font(7, "bold"),
            anchor="w",
        )
        title_label.pack(
            fill="x",
            padx=8,
            pady=(7, 1),
        )
        value_label = tk.Label(
            outer,
            textvariable=vv,
            bg=PANEL_ALT,
            fg=accent,
            font=ui_font(13, "bold"),
            anchor="w",
        )
        value_label.pack(
            fill="x",
            padx=8,
        )
        detail_label = tk.Label(
            outer,
            textvariable=dv,
            bg=PANEL_ALT,
            fg=FG,
            font=ui_font(7),
            anchor="w",
            justify="left",
            wraplength=135,
        )
        detail_label.pack(
            fill="x",
            padx=8,
            pady=(1, 7),
        )
        return {
            "frame": outer,
            "title": tv,
            "value": vv,
            "detail": dv,
            "title_label": title_label,
            "value_label": value_label,
            "detail_label": detail_label,
        }

    def create_sidebar_nav_button(
        self,
        key,
        icon,
        label,
    ):
        """
        Sidebar row with a fixed-width icon cell.

        Unicode glyphs have different visual widths, so embedding them directly
        in the button text made the labels start at different X positions.
        """
        row = tk.Frame(
            self.sidebar,
            bg=SIDEBAR_BG,
            height=40,
            highlightthickness=1,
            highlightbackground=SIDEBAR_BG,
            cursor="hand2",
        )
        row.pack(
            fill="x",
            padx=10,
            pady=3,
        )
        row.pack_propagate(
            False
        )

        icon_label = tk.Label(
            row,
            text=icon,
            bg=SIDEBAR_BG,
            fg=SIDEBAR_MUTED,
            font=ui_font(10),
            width=2,
            anchor="center",
            cursor="hand2",
        )
        icon_label.pack(
            side="left",
            padx=(8, 7),
        )

        text_label = tk.Label(
            row,
            text=label,
            bg=SIDEBAR_BG,
            fg=SIDEBAR_MUTED,
            font=ui_font(9),
            anchor="w",
            cursor="hand2",
        )
        text_label.pack(
            side="left",
            fill="x",
            expand=True,
        )

        nav = {
            "frame": row,
            "icon": icon_label,
            "label": text_label,
            "key": key,
        }

        def activate(
            _event=None,
            mode=key,
        ):
            if mode == "assistant":
                self.open_game_assistant()
            else:
                self.select_dashboard_view(
                    mode
                )

        def hover(
            _event=None,
        ):
            active_key = self._sidebar_active_key(
                getattr(
                    self,
                    "current_dashboard_view",
                    "general",
                )
            )
            if active_key == key:
                return
            self._style_sidebar_nav(
                nav,
                active=False,
                hover=True,
            )

        def leave(
            _event=None,
        ):
            active_key = self._sidebar_active_key(
                getattr(
                    self,
                    "current_dashboard_view",
                    "general",
                )
            )
            self._style_sidebar_nav(
                nav,
                active=(
                    active_key
                    == key
                ),
                hover=False,
            )

        for widget in (
            row,
            icon_label,
            text_label,
        ):
            widget.bind(
                "<Button-1>",
                activate,
            )
            widget.bind(
                "<Enter>",
                hover,
            )
            widget.bind(
                "<Leave>",
                leave,
            )

        self._style_sidebar_nav(
            nav,
            active=False,
        )
        return nav

    def _sidebar_active_key(
        self,
        mode,
    ):
        if mode in {
            "assistant",
            "live",
            "build",
            "draft",
        }:
            return "assistant"
        return mode

    def _style_sidebar_nav(
        self,
        nav,
        active=False,
        hover=False,
    ):
        if active:
            bg = "#18243a"
            border = "#2b3c5b"
            fg = SIDEBAR_FG
            icon_fg = ACCENT
            weight = "bold"
        elif hover:
            bg = "#142033"
            border = "#142033"
            fg = SIDEBAR_FG
            icon_fg = SIDEBAR_FG
            weight = "normal"
        else:
            bg = SIDEBAR_BG
            border = SIDEBAR_BG
            fg = SIDEBAR_MUTED
            icon_fg = SIDEBAR_MUTED
            weight = "normal"

        nav[
            "frame"
        ].configure(
            bg=bg,
            highlightbackground=border,
        )
        nav[
            "icon"
        ].configure(
            bg=bg,
            fg=icon_fg,
        )
        nav[
            "label"
        ].configure(
            bg=bg,
            fg=fg,
            font=ui_font(
                9,
                weight,
            ),
        )

    def open_game_assistant(
        self,
    ):
        """
        One sidebar destination for the full match workflow.

        Champion Select -> Draft panel
        Live game       -> Live Overview + Build Assistant content
        Waiting         -> Live/Build workspace in waiting state
        """
        detected = str(
            getattr(
                self,
                "detected_mode",
                "waiting",
            )
            or "waiting"
        ).lower()

        if detected == "draft":
            self.select_dashboard_view(
                "draft"
            )
        else:
            self.select_dashboard_view(
                "live"
            )

    def _set_nav_active(
        self,
        mode,
    ):
        active_key = self._sidebar_active_key(
            mode
        )
        for key, nav in getattr(
            self,
            "nav_buttons",
            {},
        ).items():
            self._style_sidebar_nav(
                nav,
                active=(
                    key
                    == active_key
                ),
            )

    def select_dashboard_view(self, mode):
        """
        Switch between the integrated RiftSense application pages.

        History and Settings are now part of the main application window rather
        than separate Toplevel windows.
        """
        if mode not in {
            "general",
            "live",
            "build",
            "draft",
            "tierlist",
            "history",
            "settings",
        }:
            mode = "general"

        if (
            mode
            == getattr(
                self,
                "current_dashboard_view",
                None,
            )
            and (
                (
                    mode == "history"
                    and hasattr(
                        self,
                        "history_page",
                    )
                    and self.history_page.winfo_manager()
                )
                or (
                    mode == "general"
                    and hasattr(
                        self,
                        "general_page",
                    )
                    and self.general_page.winfo_manager()
                )
                or (
                    mode == "tierlist"
                    and hasattr(
                        self,
                        "tier_list_page",
                    )
                    and self.tier_list_page.winfo_manager()
                )
                or (
                    mode == "settings"
                    and hasattr(
                        self,
                        "settings_page",
                    )
                    and self.settings_page.winfo_manager()
                )
            )
        ):
            return

        self._pending_dashboard_view = mode

        self._set_nav_active(mode)
        self.dashboard_mode_var.set({
            "general": "GENERAL",
            "live": "GAME ASSISTANT",
            "build": "GAME ASSISTANT",
            "draft": "GAME ASSISTANT",
            "tierlist": "TIER LIST",
            "history": "GAME HISTORY",
            "settings": "SETTINGS",
        }.get(mode, "GENERAL"))

        if self._navigation_job:
            try:
                self.after_cancel(
                    self._navigation_job
                )
            except Exception as exc:
                log_warning("Best-effort select_dashboard_view operation failed: " + str(exc))

        self._navigation_job = self.after(
            10,
            self._apply_dashboard_view,
        )



    def _set_assistant_actions_visible(
        self,
        visible,
    ):
        frame = getattr(
            self,
            "assistant_actions",
            None,
        )
        if frame is None:
            return

        if visible:
            if not frame.winfo_manager():
                kwargs = {
                    "side": "left",
                    "padx": (0, 10),
                    "pady": 6,
                }
                patch_label = getattr(
                    self,
                    "dashboard_patch_label",
                    None,
                )
                if patch_label is not None:
                    kwargs["before"] = patch_label
                frame.pack(**kwargs)
        elif frame.winfo_manager():
            frame.pack_forget()


    def _set_dashboard_topbar_visible(
        self,
        visible,
    ):
        topbar = getattr(
            self,
            "dashboard_topbar",
            None,
        )
        if topbar is None:
            return

        if visible:
            if not topbar.winfo_manager():
                try:
                    topbar.pack(
                        fill="x",
                        before=self.page_host,
                    )
                except Exception:
                    topbar.pack(
                        fill="x",
                    )
        else:
            if topbar.winfo_manager():
                topbar.pack_forget()

    def _maybe_start_history_auto_sync(
        self,
    ):
        self._history_auto_sync_job = None

        if not getattr(
            self,
            "_history_auto_sync_pending",
            False,
        ):
            return

        api_key = str(
            self.history_api_key_var.get()
            or ""
        ).strip()

        if not api_key:
            self._history_auto_sync_pending = False
            self.history_sync_status_var.set(
                "API key is empty • ranked-history sync was not started."
            )
            return

        thread = getattr(
            self,
            "_riot_sync_thread",
            None,
        )
        if (
            thread
            and thread.is_alive()
        ):
            # Keep the newly-entered key armed until the existing worker exits.
            self._history_auto_sync_job = self.after(
                500,
                self._maybe_start_history_auto_sync,
            )
            return

        self.history_sync_status_var.set(
            "Session API key ready • starting ranked-history sync..."
        )
        started = self.start_ranked_sync_from_settings(
            auto=True
        )
        self._history_auto_sync_pending = False

        if not started:
            # start_ranked_sync_from_settings already writes the exact reason.
            self._set_history_sync_controls(
                False
            )


    def _apply_dashboard_view(self):
        self._navigation_job = None
        mode = self._pending_dashboard_view or "live"
        self._pending_dashboard_view = None

        if self._navigation_busy:
            self._pending_dashboard_view = mode
            self._navigation_job = self.after(
                30,
                self._apply_dashboard_view,
            )
            return

        self._navigation_busy = True
        try:
            previous = getattr(
                self,
                "current_dashboard_view",
                None,
            )
            self.current_dashboard_view = mode

            self._set_dashboard_topbar_visible(
                mode != "history"
            )
            self._set_assistant_actions_visible(
                mode in {"live", "build"}
            )

            # Hide all top-level page bodies first. They remain fully constructed,
            # so returning to them is immediate and does not lose state.
            if self.main_split.winfo_manager():
                self.main_split.pack_forget()
            if self.general_page.winfo_manager():
                self.general_page.pack_forget()
            if self.tier_list_page.winfo_manager():
                self.tier_list_page.pack_forget()
            if self.history_page.winfo_manager():
                self.history_page.pack_forget()
            if self.settings_page.winfo_manager():
                self.settings_page.pack_forget()

            if mode == "general":
                self.general_page.pack(
                    fill="both",
                    expand=True,
                    padx=7,
                    pady=7,
                )
                self.refresh_general_page()
                return

            if mode == "tierlist":
                self.tier_list_page.pack(
                    fill="both",
                    expand=True,
                    padx=7,
                    pady=7,
                )
                self.refresh_tier_list_page()
                return

            if mode == "history":
                self.history_page.pack(
                    fill="both",
                    expand=True,
                    padx=7,
                    pady=7,
                )

                if not self._history_nav_layout_ready:
                    self._history_nav_layout_ready = True
                    self.after(
                        40,
                        self._set_history_mockup_split,
                    )

                if (
                    not self._history_has_rendered
                    or self._history_needs_full_refresh
                ):
                    self.refresh_history_tree(
                        full_refresh=True,
                    )
                    self._history_has_rendered = True
                    self._history_needs_full_refresh = False

                if getattr(
                    self,
                    "_history_auto_sync_pending",
                    False,
                ):
                    if self._history_auto_sync_job is not None:
                        try:
                            self.after_cancel(
                                self._history_auto_sync_job
                            )
                        except Exception as exc:
                            log_warning("Best-effort _apply_dashboard_view operation failed: " + str(exc))
                    self._history_auto_sync_job = self.after(
                        120,
                        self._maybe_start_history_auto_sync,
                    )
                return

            if mode == "settings":
                self.settings_page.pack(
                    fill="both",
                    expand=True,
                    padx=7,
                    pady=7,
                )
                self.reload_settings_page()
                return

            # Live / Build / Draft share the original split dashboard.
            self.main_split.pack(
                fill="both",
                expand=True,
                padx=7,
                pady=7,
            )

            saved_ratio = max(
                0.35,
                min(
                    0.75,
                    float(
                        SETTINGS.get(
                            "split_ratio",
                            0.57,
                        )
                        or 0.57
                    ),
                ),
            )

            if mode == "draft":
                want_draft, want_live, ratio = True, False, saved_ratio
            elif mode == "build":
                want_draft, want_live, ratio = False, True, saved_ratio
            else:
                want_draft, want_live, ratio = False, True, saved_ratio

            visibility_changed = (
                bool(self.show_draft_var.get()) != want_draft
                or bool(self.show_live_var.get()) != want_live
            )

            self.show_draft_var.set(
                want_draft
            )
            self.show_live_var.set(
                want_live
            )

            if (
                visibility_changed
                or previous != mode
            ):
                self.apply_panel_visibility()
                self.apply_compact_live_visibility()

            try:
                pane_width = max(
                    1,
                    int(
                        self.main_split.winfo_width()
                    ),
                )
                target = int(
                    pane_width * ratio
                )
                current = int(
                    self.main_split.sashpos(0)
                )
                if abs(current - target) >= 6:
                    self._nav_ratio_lock_until = (
                        time.monotonic()
                        + 0.35
                    )
                    self.main_split.sashpos(
                        0,
                        target,
                    )
            except Exception as exc:
                log_warning("Best-effort _apply_dashboard_view operation failed: " + str(exc))
        finally:
            self.after(
                25,
                lambda: setattr(
                    self,
                    "_navigation_busy",
                    False,
                ),
            )



    def set_live_state_banner(
        self,
        state,
        title,
        detail,
        visible=True,
    ):
        if not hasattr(
            self,
            "live_state_banner",
        ):
            return

        palette = {
            "ok": (
                GOOD,
                POS_BG,
            ),
            "warn": (
                ACCENT,
                ORANGE_BG,
            ),
            "off": (
                DANGER,
                NEG_BG,
            ),
            "idle": (
                ACCENT,
                TIE_BG,
            ),
        }
        fg, bg = palette.get(
            state,
            palette["idle"],
        )

        self.live_state_title_var.set(
            title
        )
        self.live_state_detail_var.set(
            detail
        )
        self.live_state_banner.configure(
            bg=bg,
            highlightbackground=fg,
        )
        self.live_state_banner_accent.configure(
            bg=fg,
        )
        self.live_state_title_label.configure(
            bg=bg,
            fg=fg,
        )
        self.live_state_detail_label.configure(
            bg=bg,
        )
        for child in self.live_state_banner.winfo_children():
            try:
                if child is not self.live_state_banner_accent:
                    child.configure(
                        bg=bg
                    )
                    for sub in child.winfo_children():
                        sub.configure(
                            bg=bg
                        )
            except Exception as exc:
                log_warning("Best-effort set_live_state_banner operation failed: " + str(exc))

        if visible:
            if not self.live_state_banner.winfo_manager():
                self.live_state_banner.pack(
                    fill="x",
                    padx=6,
                    pady=(3, 2),
                    before=self.right_live_summary,
                )
        else:
            self.live_state_banner.pack_forget()

