    def flash_label(self, widget, flash_color, restore_color=None, duration=650):
        """
        Subtle foreground flash. No widget recreation and no image reload.
        """
        if widget is None:
            return
        key = str(widget)
        if restore_color is None:
            try:
                restore_color = widget.cget("fg")
            except Exception:
                restore_color = FG

        job = self.flash_jobs.get(key)
        if job:
            try:
                self.after_cancel(job)
            except Exception as exc:
                log_warning("Best-effort flash_label operation failed: " + str(exc))

        try:
            widget.configure(fg=flash_color)
        except Exception:
            return

        def restore():
            try:
                widget.configure(fg=restore_color)
            except Exception as exc:
                log_warning("Best-effort restore operation failed: " + str(exc))
            self.flash_jobs.pop(key, None)

        self.flash_jobs[key] = self.after(duration, restore)

    def flash_numeric_change(self, key, value, widget, restore_color):
        previous = self.last_numeric_metrics.get(key)
        self.last_numeric_metrics[key] = value
        if previous is None or previous == value:
            return
        flash = GOOD if value > previous else DANGER
        self.flash_label(
            widget,
            flash,
            restore_color=restore_color,
            duration=600,
        )

    def push_what_changed(self, text):
        if not hasattr(self, "what_changed_var"):
            return
        self.what_changed_var.set("CHANGED • " + text)
        if not self.what_changed_label.winfo_manager():
            self.what_changed_label.pack(
                fill="x",
                pady=(2, 0),
            )
        self.flash_label(
            self.what_changed_label,
            FG,
            restore_color=ACCENT,
            duration=700,
        )

        if self.what_changed_clear_job:
            try:
                self.after_cancel(self.what_changed_clear_job)
            except Exception as exc:
                log_warning("Best-effort push_what_changed operation failed: " + str(exc))

        def clear_changed():
            self.what_changed_var.set("")
            try:
                self.what_changed_label.pack_forget()
            except Exception as exc:
                log_warning("Best-effort clear_changed operation failed: " + str(exc))

        self.what_changed_clear_job = self.after(
            12000,
            clear_changed,
        )

    def track_strategy_changes(self, values_with_reasons):
        """
        Collect up to two meaningful changes from one refresh to avoid noisy spam.
        """
        changes = []
        for key, label, value, reason in values_with_reasons:
            old = self.last_strategy_values.get(key)
            self.last_strategy_values[key] = value
            if old is None or old == value:
                continue
            changes.append(
                f"{label} {old} → {value} • {reason}"
            )

        if changes:
            self.push_what_changed("  |  ".join(changes[:2]))

    def draw_game_state_history(self):
        canvas = getattr(self, "game_state_history_canvas", None)
        if canvas is None:
            return
        canvas.delete("all")

        samples = list(self.team_gold_history)
        if len(samples) < 2:
            return

        canvas.update_idletasks()
        width = max(120, canvas.winfo_width())
        height = max(20, canvas.winfo_height())

        values = [float(value) for _time, value in samples]
        max_abs = max(1200.0, max(abs(value) for value in values))

        zero_y = height / 2.0
        canvas.create_line(
            0, zero_y, width, zero_y,
            fill=BORDER,
            dash=(2, 2),
        )

        points = []
        count = len(samples)
        for index, (_time, value) in enumerate(samples):
            x = index * width / max(1, count - 1)
            y = zero_y - (float(value) / max_abs) * (height * 0.42)
            points.extend((x, y))

        current_color = (
            GOOD if values[-1] > 300
            else DANGER if values[-1] < -300
            else ACCENT
        )
        canvas.create_line(
            *points,
            fill=current_color,
            width=2,
            smooth=True,
        )

