    def on_auto_switch_toggle(self):
        if self.auto_switch_var.get():
            self.last_auto_applied_mode = None
            self.apply_auto_mode(self.detected_mode)

    def apply_auto_mode(self, mode):
        """
        Apply automatic visibility only when detected game state changes.
        Manual sidebar navigation is not interrupted mid-click.
        """
        self.detected_mode = mode

        # History and Settings are deliberate user pages. Keep them open while
        # background Live/LCU detection continues updating silently.
        if getattr(
            self,
            "current_dashboard_view",
            "live",
        ) in {"general", "tierlist", "history", "settings"}:
            return

        if not self.auto_switch_var.get():
            return
        if mode == self.last_auto_applied_mode:
            return

        self.last_auto_applied_mode = mode

        if getattr(self, "_navigation_busy", False) or self._navigation_job:
            # Let the user's click finish first. Next poll can apply Auto Switch
            # if the game state genuinely changed again.
            return

        if mode == "draft":
            # Game Assistant stays highlighted; only its internal context changes.
            self._set_assistant_actions_visible(False)
            self._set_nav_active("draft")
            self.dashboard_mode_var.set("GAME ASSISTANT")
            self.current_dashboard_view = "draft"
            self.show_draft_var.set(True)
            self.show_live_var.set(False)
        elif mode == "live":
            # Preserve Build Assistant if user intentionally chose it in-game.
            self._set_assistant_actions_visible(True)
            if self.current_dashboard_view not in {"live", "build"}:
                self.current_dashboard_view = "live"
            self._set_nav_active(self.current_dashboard_view)
            self.dashboard_mode_var.set(
                "GAME ASSISTANT"
            )
            self.show_draft_var.set(False)
            self.show_live_var.set(True)
        else:
            # Waiting state keeps the current sidebar view rather than forcing
            # both large panels to repack every time local APIs are unavailable.
            if self.current_dashboard_view == "draft":
                self.show_draft_var.set(True)
                self.show_live_var.set(False)
            else:
                self.show_draft_var.set(False)
                self.show_live_var.set(True)

        self.apply_panel_visibility()
        self.apply_compact_live_visibility()


