    def apply_panel_visibility(self):
        """
        Show/hide the large Draft and Live sections without affecting their data refresh.
        This lets the user hide Draft after Champion Select finishes and keep the build
        assistant visible.
        """
        if hasattr(self, "draft_panel"):
            if self.show_draft_var.get():
                draft_only = not bool(
                    self.show_live_var.get()
                )

                if not self.draft_panel.winfo_manager():
                    if self.live_panel.winfo_manager():
                        self.draft_panel.pack(
                            fill=(
                                "both"
                                if draft_only
                                else "x"
                            ),
                            expand=draft_only,
                            pady=7,
                            before=self.live_panel,
                        )
                    else:
                        self.draft_panel.pack(
                            fill=(
                                "both"
                                if draft_only
                                else "x"
                            ),
                            expand=draft_only,
                            pady=7,
                        )
                else:
                    # Champion Select uses the Draft panel by itself. Reconfigure
                    # the existing pack geometry too; otherwise a panel that was
                    # initially packed as fill='x' leaves a large dead strip below
                    # it after Live is hidden.
                    self.draft_panel.pack_configure(
                        fill=(
                            "both"
                            if draft_only
                            else "x"
                        ),
                        expand=draft_only,
                        pady=7,
                    )
            else:
                self.draft_panel.pack_forget()

        if hasattr(self, "live_panel"):
            if self.show_live_var.get():
                if not self.live_panel.winfo_manager():
                    self.live_panel.pack(
                        fill="both",
                        expand=True,
                        pady=7,
                    )
                else:
                    self.live_panel.pack_configure(
                        fill="both",
                        expand=True,
                        pady=7,
                    )
            else:
                self.live_panel.pack_forget()


    def clear_frame(self, frame):
        for child in frame.winfo_children():
            child.destroy()

    def load_photo(self, path, small=False, target_px=None):
        if not path:
            return None

        if target_px is None:
            target_px = 32 if small else 64

        key = f"{path}|{target_px}"
        if key in self.photo_cache:
            return self.photo_cache[key]

        try:
            img = tk.PhotoImage(file=str(path))

            width = max(1, img.width())
            height = max(1, img.height())
            longest = max(width, height)

            # Tkinter's built-in subsample is integer-only. Pick the closest safe
            # integer downscale without introducing extra dependencies.
            factor = max(1, int(round(longest / max(1, target_px))))
            if factor > 1:
                img = img.subsample(factor, factor)

            self.photo_cache[key] = img
            return img
        except Exception:
            return None

    def load_circle_photo(
        self,
        path,
        target_px=36,
        ring=None,
        ring_width=1,
    ):
        """
        Return a cached circular champion portrait using only Tk PhotoImage.

        This keeps RiftSense stdlib-only at runtime while giving History the
        circular portrait treatment used in the target design.
        """
        if not path:
            return None

        ring = str(
            ring
            or ACCENT
        )
        key = (
            f"circle|{path}|{int(target_px)}|"
            f"{ring}|{int(ring_width)}"
        )
        if key in self.photo_cache:
            return self.photo_cache[
                key
            ]

        base = self.load_photo(
            path,
            target_px=target_px,
        )
        if base is None:
            return None

        try:
            img = base.copy()
            width = max(
                1,
                img.width(),
            )
            height = max(
                1,
                img.height(),
            )
            cx = (
                width
                - 1
            ) / 2.0
            cy = (
                height
                - 1
            ) / 2.0
            radius = max(
                1.0,
                min(
                    width,
                    height,
                )
                / 2.0
                - 0.8,
            )
            inner = max(
                0.0,
                radius
                - max(
                    1,
                    int(
                        ring_width
                    ),
                ),
            )
            radius_sq = radius * radius
            inner_sq = inner * inner

            for y in range(
                height
            ):
                dy = (
                    y
                    - cy
                )
                for x in range(
                    width
                ):
                    dx = (
                        x
                        - cx
                    )
                    distance_sq = (
                        dx
                        * dx
                        + dy
                        * dy
                    )
                    if distance_sq > radius_sq:
                        img.transparency_set(
                            x,
                            y,
                            True,
                        )
                    elif (
                        ring_width
                        and distance_sq
                        >= inner_sq
                    ):
                        try:
                            img.put(
                                ring,
                                (
                                    x,
                                    y,
                                ),
                            )
                        except Exception as exc:
                            log_warning("Best-effort load_circle_photo operation failed: " + str(exc))

            self.photo_cache[
                key
            ] = img
            return img
        except Exception:
            return base

    def current_item_icon_path(self, item_id):
        """
        Prefer the icon bundled with the currently running League Client.
        This avoids stale Data Dragon item art. Data Dragon remains the fallback.
        """
        if not item_id:
            return None

        item_id = str(item_id)
        patch_key = self.dd.version or "current"
        cache_path = CLIENT_ITEM_CACHE_DIR / patch_key / f"{item_id}.png"

        if cache_path.exists() and cache_path.stat().st_size > 100:
            return cache_path

        # League Client game-data assets reflect the installed client build.
        raw, status = self.lcu.get_bytes(
            f"/lol-game-data/assets/v1/items/{item_id}.png"
        )

        if raw and status == 200 and len(raw) > 100:
            # PNG begins with 89 50 4E 47. Some Riot endpoints may return another
            # Tk-compatible image format, so only reject obvious HTML/JSON.
            head = raw[:32].lstrip().lower()
            if not head.startswith(b"<") and not head.startswith(b"{"):
                cache_path.parent.mkdir(parents=True, exist_ok=True)
                tmp = cache_path.with_suffix(".png.tmp")
                tmp.write_bytes(raw)
                tmp.replace(cache_path)
                return cache_path

        return self.dd.item_icon_path(item_id)

    def add_champion_icon(self, parent, champion_name, subtitle=""):
        holder = ttk.Frame(parent, style="Panel.TFrame")
        holder.pack(side="left", padx=2)

        path = self.dd.champion_icon_path(champion_name)
        photo = self.load_photo(path, target_px=int(SETTINGS.get("champion_icon_px", 28)))
        if photo:
            label = ttk.Label(holder, image=photo, style="Panel.TLabel")
        else:
            label = ttk.Label(holder, text="?", style="Panel.TLabel", width=4)
        label.pack()

        if subtitle:
            ttk.Label(
                holder,
                text=subtitle,
                style="Muted.Panel.TLabel",
                font=ui_font(8),
            ).pack()

        Tooltip(label, champion_name)

    def add_item_icon(self, parent, item_id, item_name, position=None):
        holder = ttk.Frame(parent, style="Panel.TFrame")
        holder.pack(side="left", padx=5)

        path = self.current_item_icon_path(item_id)
        photo = self.load_photo(path, target_px=28)
        if photo:
            label = ttk.Label(holder, image=photo, style="Panel.TLabel")
        else:
            label = ttk.Label(holder, text="?", style="Panel.TLabel", width=4)
        label.pack()

        if position is not None:
            ttk.Label(
                holder,
                text=str(position),
                style="Muted.Panel.TLabel",
            ).pack()

        Tooltip(label, item_name)

    def refresh_item_images(self):
        """
        Clear cached item art so icons are fetched again from the current League Client.
        Champion art and other metadata are left untouched.
        """
        try:
            if CLIENT_ITEM_CACHE_DIR.exists():
                shutil.rmtree(CLIENT_ITEM_CACHE_DIR)
            CLIENT_ITEM_CACHE_DIR.mkdir(parents=True, exist_ok=True)

            if ITEM_CACHE_DIR.exists():
                shutil.rmtree(ITEM_CACHE_DIR)
            ITEM_CACHE_DIR.mkdir(parents=True, exist_ok=True)

            # Keep champion photos, remove cached item PhotoImages.
            self.photo_cache = {}

            self.current_item_signature = None
            self.build_signature = None
            self.adaptive_signature = None
            self.purchase_signature = None
            self.companion_signature = None
            self.full_build_signature = None

            self.rs_info(
                "Item images",
                "Item image cache cleared. Icons will be loaded again from the "
                "currently running League Client, with Riot Data Dragon as fallback."
            )
            self.refresh_all()
        except Exception as exc:
            self.rs_error(
                "Item images",
                f"Could not refresh item images:\n{exc}",
            )

    def select_league_folder(self):
        chosen = filedialog.askdirectory(
            title="Select your League of Legends installation folder"
        )
        if not chosen:
            return

        path = Path(chosen)
        if not (path / "lockfile").exists():
            self.rs_warning(
                "League folder",
                "No 'lockfile' is present in that folder right now.\n\n"
                "This can be normal if League Client is closed. The folder will still "
                "be saved and checked when the client starts.",
            )

        SETTINGS["league_dir"] = str(path)
        save_settings()
        self.lcu.port = None
        self.lcu.password = None
        self.refresh_all()

    def set_health(self, key, status, detail=""):
        label = getattr(self, "health_labels", {}).get(key)
        if not label:
            return
        colors = {"ok": GOOD, "warn": ACCENT, "off": DANGER, "idle": MUTED}
        symbol = {"ok": "●", "warn": "●", "off": "●", "idle": "○"}.get(status, "○")
        suffix = f" {detail}" if detail else ""
        label.configure(text=f"{key}: {symbol}{suffix}", fg=colors.get(status, MUTED))

    def update_health_bar(self):
        self.set_health("LIVE", "ok" if self.live_api_ok else "idle", "connected" if self.live_api_ok else "waiting")
        lcu_ok = bool(self.lcu.port and self.lcu.password)
        self.set_health("LCU", "ok" if lcu_ok else "idle", "connected" if lcu_ok else "waiting")
        dd_ok = bool(self.dd.item_data and self.dd.champion_data)
        self.set_health("ITEM DATA", "ok" if dd_ok else "warn", self.dd.version or "unavailable")
        patch_state = "ok"
        if self.patch_status_text.startswith("MISMATCH"):
            patch_state = "warn"
        elif self.patch_status_text in {"-", "waiting"}:
            patch_state = "idle"
        self.set_health("PATCH", patch_state, self.patch_status_text)
        self.refresh_dashboard_header()

    def apply_saved_split_ratio(self):
        try:
            ratio = float(SETTINGS.get("split_ratio", 0.57))
            ratio = max(0.35, min(0.75, ratio))
            width = max(1, self.main_split.winfo_width())
            self.main_split.sashpos(0, int(width * ratio))
        except Exception as exc:
            log_warning("Best-effort apply_saved_split_ratio operation failed: " + str(exc))

