    def maybe_refresh_patch_data(
        self,
        game_version,
    ):
        prefix = patch_prefix_from_game_version(
            game_version
        )
        if not prefix:
            self.patch_status_text = "waiting"
            return

        version_matches = bool(
            self.dd.version
            and self.dd.version.startswith(
                prefix
            )
        )
        items_ready = bool(
            getattr(
                self.dd,
                "item_data",
                None,
            )
            and getattr(
                self.dd,
                "items_version",
                None,
            )
            == self.dd.version
        )
        champions_ready = bool(
            getattr(
                self.dd,
                "champion_data",
                None,
            )
            and getattr(
                self.dd,
                "champions_version",
                None,
            )
            == self.dd.version
        )

        # The old code returned as soon as the version string matched. If
        # load_items() had failed once, RiftSense could then keep a matching
        # version with an empty item catalogue for a long time. Boots were the
        # most visible symptom because slot 1 depended on item-id validation.
        if (
            version_matches
            and items_ready
            and champions_ready
        ):
            self.patch_status_text = self.dd.version
            return

        now = time.monotonic()

        # Healthy patch checks stay cheap. Missing static data retries quickly.
        retry_after = (
            5.0
            if version_matches
            and not items_ready
            else 10.0
            if version_matches
            else 30.0
        )

        if (
            SETTINGS.get(
                "auto_patch_refresh",
                True,
            )
            and now
            - self.last_patch_check
            >= retry_after
        ):
            self.last_patch_check = now

            version = (
                self.dd.version
                if version_matches
                else self.dd.resolve_version(
                    game_version
                )
            )

            if version:
                self.dd.load_static_data(
                    version
                )

                # Item data arriving changes validation, ids and icon lookups.
                # Force the build cards to recompute immediately instead of
                # waiting for an unrelated meta/adaptive signature change.
                if (
                    getattr(
                        self.dd,
                        "item_data",
                        None,
                    )
                    and getattr(
                        self.dd,
                        "items_version",
                        None,
                    )
                    == version
                ):
                    self.full_build_signature = None
                    self.adaptive_signature = None
                    self.build_signature = None

        version_matches = bool(
            self.dd.version
            and self.dd.version.startswith(
                prefix
            )
        )
        items_ready = bool(
            getattr(
                self.dd,
                "item_data",
                None,
            )
            and getattr(
                self.dd,
                "items_version",
                None,
            )
            == self.dd.version
        )

        if (
            version_matches
            and items_ready
        ):
            self.patch_status_text = self.dd.version
        elif version_matches:
            self.patch_status_text = (
                f"{self.dd.version} • loading items"
            )
        else:
            client_patch = prefix.rstrip(
                "."
            )
            self.patch_status_text = (
                f"MISMATCH client {client_patch} / "
                f"data {self.dd.version or '-'}"
            )


    def stabilize_adaptive_options(self, champion, options):
        options = list(options or [])
        if not options:
            return []
        margin = float(SETTINGS.get("build_reactivity", 1.2) or 1.2)
        previous = self.stable_adaptive_by_champion.get(champion) or []
        current = {item["name"]: item for item in options}
        stable = []
        remaining = list(options)
        for prev in previous:
            name = prev.get("name")
            if name not in current or not remaining:
                continue
            best = remaining[0]
            prev_now = current[name]
            if best["name"] != name and best["score"] < prev_now["score"] + margin:
                stable.append(prev_now)
                remaining = [x for x in remaining if x["name"] != name]
            elif best not in stable:
                stable.append(best)
                remaining = remaining[1:]
        for item in remaining:
            if item["name"] not in {x["name"] for x in stable}:
                stable.append(item)
        stable = stable[:3]
        self.stable_adaptive_by_champion[champion] = stable
        return stable

    def clear_build_change_notice(self):
        self.build_change_var.set("")
        self.full_build_new_names = set()
        for var, source in self.full_build_new_label_vars:
            try:
                var.set(source)
            except Exception as exc:
                log_warning("Best-effort clear_build_change_notice operation failed: " + str(exc))
        for holder, source in self.full_build_new_holders:
            try:
                holder.configure(
                    highlightbackground=(
                        GOOD
                        if source
                        in {
                            "OWNED",
                            "OFFENSE",
                            "ASSASSIN CORE",
                            "META",
                        }
                        else ACCENT
                        if source
                        in {
                            "ADAPTIVE",
                            "ADAPTIVE BOOTS",
                        }
                        else BORDER
                    )
                )
            except Exception as exc:
                log_warning("Best-effort clear_build_change_notice operation failed: " + str(exc))
        self.full_build_new_label_vars = []
        self.full_build_new_holders = []
        self.build_change_clear_job = None

    def record_build_change(self, old_names, new_names, adaptive_options):
        if not old_names or old_names == new_names:
            return
        changes = []
        adaptive_map = {x.get("name"): x for x in (adaptive_options or [])}
        for index, new_name in enumerate(new_names):
            old_name = old_names[index] if index < len(old_names) else None
            if new_name != old_name:
                if old_name:
                    changes.append(f"slot {index+1}: {old_name} → {new_name}")
                else:
                    changes.append(f"slot {index+1}: +{new_name}")
                self.full_build_new_names.add(new_name)
        if not changes:
            return
        reasons = []
        for name in self.full_build_new_names:
            option = adaptive_map.get(name)
            if option:
                reasons.extend(option.get("reasons") or [])
        reason_text = reasons[0] if reasons else "the current threat/composition fit changed"
        text = "BUILD UPDATED — " + "; ".join(changes[:2]) + f". Reason: {reason_text}."
        self.build_change_var.set(text)
        event = {"time": getattr(self, "current_game_time_seconds", 0), "changes": changes, "reason": reason_text}
        self.build_change_history.append(event)
        if hasattr(self, "what_changed_var"):
            self.push_what_changed(
                f"Build • {changes[0]} • {reason_text}"
            )
        if self.live_session_active:
            self.session_build_changes.append(event)
        if self.build_change_clear_job:
            try:
                self.after_cancel(self.build_change_clear_job)
            except Exception as exc:
                log_warning("Best-effort record_build_change operation failed: " + str(exc))
        self.build_change_clear_job = self.after(9000, self.clear_build_change_notice)

    def render_events(self, events):
        """
        V29 does not render a persistent event log.

        Events are still read from the Live Client API and retained in the
        post-game session snapshot. The live dashboard keeps only the compact
        Dragon / Baron readiness bar.
        """
        return


    def begin_live_session(self):
        if self.live_session_active:
            return
        self.live_session_active = True
        self.session_started_at = datetime.now().isoformat(timespec="seconds")
        self.session_build_changes = []
        self.last_session_snapshot = None

    def update_session_snapshot(self, data, champion, riot_id, player, full_build, events):
        game_data = data.get("gameData") or {}
        scores = player.get("scores") or {}
        item_names = []
        for item in player.get("items") or []:
            item_id = item.get("itemID")
            if item_id:
                name = item.get("displayName") or self.dd.item_name(item_id)
                if normalize_name(name) not in {"warding totem (trinket)", "oracle lens", "farsight alteration"}:
                    item_names.append(name)
        self.last_session_snapshot = {
            "started_at": self.session_started_at,
            "last_seen_at": datetime.now().isoformat(timespec="seconds"),
            "player": riot_id,
            "champion": champion,
            "duration_seconds": float(game_data.get("gameTime", 0) or 0),
            "level": player.get("level", 0),
            "kills": scores.get("kills", 0),
            "deaths": scores.get("deaths", 0),
            "assists": scores.get("assists", 0),
            "cs": scores.get("creepScore", 0),
            "final_items": item_names,
            "adaptive_full_build": [item.get("name") for item in (full_build or [])],
            "events": [format_event_text(e) for e in important_game_events(events)],
            "lane_history": {lane: list(values) for lane, values in self.lane_progress_history.items()},
            "build_changes": list(self.session_build_changes),
            "game_phase": game_phase(float(game_data.get("gameTime", 0) or 0)),
            "strategy_mode": getattr(self, "current_strategy_mode", "STABLE"),
            "state_confidence": {
                "score": (getattr(self, "current_state_confidence", (0, "LOW", ""))[0]),
                "label": (getattr(self, "current_state_confidence", (0, "LOW", ""))[1]),
                "reason": (getattr(self, "current_state_confidence", (0, "LOW", ""))[2]),
            },
            "team_gold_history": list(getattr(self, "team_gold_history", [])),
            "enemy_threat_ranking": [
                {
                    "champion": item.get("champion"),
                    "item_gold": item.get("item_gold"),
                    "power": item.get("power"),
                    "threat_type": item.get("threat_type"),
                }
                for item in getattr(self, "current_enemy_threat_ranking", [])[:3]
            ],
            "ally_carry_ranking": [
                {
                    "champion": item.get("champion"),
                    "item_gold": item.get("item_gold"),
                    "power": item.get("power"),
                }
                for item in getattr(self, "current_ally_carry_ranking", [])[:3]
            ],
            "objective_readiness": dict(getattr(self, "current_objective_readiness", {})),
            "data_version": self.dd.version,
        }

    def save_post_game_report(self):
        snapshot = self.last_session_snapshot
        if not snapshot:
            return
        key = f"{snapshot.get('started_at')}|{snapshot.get('champion')}"
        if key == self.last_saved_session_key:
            return
        self.last_saved_session_key = key
        safe_champ = re.sub(r"[^A-Za-z0-9_-]+", "_", snapshot.get("champion") or "game")
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        path = HISTORY_DIR / f"{stamp}_{safe_champ}.json"
        path.write_text(json.dumps(snapshot, ensure_ascii=False, indent=2), encoding="utf-8")
        csv_path = HISTORY_DIR / "games.csv"
        new_file = not csv_path.exists()
        with csv_path.open("a", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            if new_file:
                writer.writerow(["date", "champion", "k", "d", "a", "cs", "duration", "final_items", "adaptive_build"])
            writer.writerow([
                snapshot.get("last_seen_at"), snapshot.get("champion"), snapshot.get("kills"), snapshot.get("deaths"),
                snapshot.get("assists"), snapshot.get("cs"), int(snapshot.get("duration_seconds", 0)),
                " > ".join(snapshot.get("final_items") or []), " > ".join(snapshot.get("adaptive_full_build") or []),
            ])

    def finish_live_session(self):
        if self.live_session_active:
            try:
                self.save_post_game_report()
            except Exception as exc:
                log_warning("Best-effort finish_live_session operation failed: " + str(exc))
        self.live_session_active = False
        self.live_miss_count = 0
        self.session_started_at = None
        self.session_build_changes = []

    def _riot_sync_post(self, payload):
        try:
            event_type = str(
                (
                    payload
                    or {}
                ).get(
                    "type",
                    "event",
                )
            )
            message = str(
                (
                    payload
                    or {}
                ).get(
                    "message",
                    "",
                )
                or ""
            )
            if message:
                log_info(
                    f"Ranked sync • {event_type} • {message}"
                )
            else:
                log_info(
                    f"Ranked sync • {event_type}"
                )
        except Exception as exc:
            log_warning("Best-effort _riot_sync_post operation failed: " + str(exc))

        try:
            self._riot_sync_queue.put_nowait(
                payload
            )
        except Exception as exc:
            log_warning("Best-effort _riot_sync_post operation failed: " + str(exc))

    def _normalized_riot_id_key(
        self,
        riot_id,
    ):
        return str(
            riot_id
            or ""
        ).strip().casefold()

    def _history_local_identity(
        self,
        riot_id,
    ):
        """
        Resolve the PUUID without ACCOUNT-V1 whenever possible.

        Order:
          1. Saved PUUID for the same Riot ID.
          2. Current logged-in League Client summoner (LCU).

        This is useful for the personal desktop workflow because a 403 returned
        by ACCOUNT-V1 is not enough to distinguish an auth problem from an
        endpoint/authorization problem.
        """
        requested_key = self._normalized_riot_id_key(
            riot_id
        )

        saved = load_json(
            RIOT_ACCOUNT_PATH,
            {},
        )
        if not isinstance(
            saved,
            dict,
        ):
            saved = {}

        saved_id = str(
            saved.get(
                "riot_id",
                "",
            )
            or ""
        ).strip()
        saved_puuid = str(
            saved.get(
                "puuid",
                "",
            )
            or ""
        ).strip()

        if (
            saved_puuid
            and saved_id
            and self._normalized_riot_id_key(
                saved_id
            )
            == requested_key
        ):
            return {
                "puuid": saved_puuid,
                "riot_id": saved_id,
                "source": "saved account",
                "payload": saved,
            }

        # Local League Client identity. Read-only localhost request only.
        try:
            payload, status = self.lcu.get(
                "/lol-summoner/v1/current-summoner",
                timeout=1.5,
            )
        except Exception:
            payload = None
            status = None

        if (
            status == 200
            and isinstance(
                payload,
                dict,
            )
        ):
            puuid = str(
                payload.get(
                    "puuid",
                    "",
                )
                or ""
            ).strip()

            game_name = str(
                payload.get(
                    "gameName",
                    "",
                )
                or ""
            ).strip()
            tag_line = str(
                payload.get(
                    "tagLine",
                    "",
                )
                or ""
            ).strip()

            # Some client builds expose only displayName. PUUID is still enough
            # for League-V4 and Match-V5.
            resolved_id = (
                f"{game_name}#{tag_line}"
                if game_name
                and tag_line
                else str(
                    payload.get(
                        "displayName",
                        "",
                    )
                    or riot_id
                ).strip()
            )

            if puuid:
                # If the client supplies a full Riot ID, refuse to silently use
                # a different logged-in account.
                if (
                    game_name
                    and tag_line
                    and self._normalized_riot_id_key(
                        resolved_id
                    )
                    != requested_key
                ):
                    return {
                        "error": (
                            "League Client is logged in as "
                            f"{resolved_id}, but Settings contains {riot_id}."
                        ),
                        "source": "League Client",
                    }

                return {
                    "puuid": puuid,
                    "riot_id": (
                        resolved_id
                        if "#" in resolved_id
                        else riot_id
                    ),
                    "source": "League Client",
                    "payload": payload,
                }

        return None

    def _riot_history_sync_worker(
        self,
        riot_id,
        route,
        platform,
        api_key,
        queue_ids,
        history_scope,
    ):
        """
        Sync Summoner's Rift ranked matches for the selected history scope.

        Normal Draft, Quickplay, ARAM, Arena and custom games are always excluded.
        The default V38 scope is the full 2026 ranked year (S1-S3).
        """
        try:
            season = current_ranked_season()
            scope_info = ranked_history_scope_info(
                history_scope
            )
            history_scope = scope_info[
                "key"
            ]
            queue_ids = [
                int(queue_id)
                for queue_id in queue_ids
                if int(queue_id)
                in season["queues"]
            ]

            if not queue_ids:
                self._riot_sync_post({
                    "type": "error",
                    "message": (
                        "Select at least one ranked queue: "
                        "Solo/Duo and/or Flex."
                    ),
                })
                return

            previous_account_state = load_json(
                RIOT_ACCOUNT_PATH,
                {},
            )
            if not isinstance(
                previous_account_state,
                dict,
            ):
                previous_account_state = {}

            identity = self._history_local_identity(
                riot_id
            )

            if (
                isinstance(
                    identity,
                    dict,
                )
                and identity.get(
                    "error"
                )
            ):
                self._riot_sync_post({
                    "type": "error",
                    "message": identity[
                        "error"
                    ],
                })
                return

            if (
                isinstance(
                    identity,
                    dict,
                )
                and identity.get(
                    "puuid"
                )
            ):
                puuid = str(
                    identity[
                        "puuid"
                    ]
                )
                resolved_id = str(
                    identity.get(
                        "riot_id",
                        riot_id,
                    )
                    or riot_id
                )
                identity_source = str(
                    identity.get(
                        "source",
                        "local identity",
                    )
                )
                self._riot_sync_post({
                    "type": "status",
                    "message": (
                        f"PUUID resolved from {identity_source}. "
                        "Testing Riot ranked API access..."
                    ),
                })
            else:
                account, status, error = riot_account_by_riot_id(
                    riot_id,
                    route,
                    api_key,
                )

                if not account:
                    error_text = str(
                        error
                        or "Forbidden"
                    )
                    if status in {
                        401,
                        403,
                    }:
                        error_text = (
                            f"ACCOUNT-V1 HTTP {status}: {error_text}. "
                            "RiftSense could not obtain a PUUID locally. "
                            "Keep League Client open and logged in, then retry. "
                            "A Riot 403 does not uniquely identify the cause."
                        )
                    self._riot_sync_post({
                        "type": "error",
                        "message": (
                            f"Could not resolve Riot ID / PUUID: {error_text}"
                        ),
                    })
                    return

                puuid = str(
                    account[
                        "puuid"
                    ]
                )
                resolved_id = (
                    f"{account.get('gameName', '')}"
                    f"#{account.get('tagLine', '')}"
                )

            account_state = {
                "riot_id": resolved_id,
                "route": route,
                "platform": platform,
                "puuid": puuid,
                "last_sync_at": previous_account_state.get(
                    "last_sync_at",
                    "",
                ),
                "history_scope": scope_info[
                    "name"
                ],
                "history_scope_key": history_scope,
                "queue_ids": queue_ids,
                "rank_snapshot": previous_account_state.get(
                    "rank_snapshot",
                    {},
                ),
            }

            # Current rank is platform-routed and can be refreshed with the same
            # temporary API key used for Match-V5 sync.
            rank_data, rank_status, _rank_headers = riot_league_entries_by_puuid(
                puuid,
                platform,
                api_key,
            )
            if rank_status == 200:
                rank_snapshot = normalize_rank_snapshot(
                    rank_data
                )
                account_state[
                    "rank_snapshot"
                ] = rank_snapshot
                account_state[
                    "rank_updated_at"
                ] = datetime.now().isoformat(
                    timespec="seconds"
                )
                account_state[
                    "rank_source"
                ] = "Riot API"
                record_rank_progress_snapshot(
                    resolved_id,
                    rank_snapshot,
                )
                self._riot_sync_post({
                    "type": "rank",
                    "rank_snapshot": rank_snapshot,
                    "message": (
                        "Rank refreshed • "
                        f"Solo: {rank_entry_text(rank_snapshot.get('solo'))} • "
                        f"Flex: {rank_entry_text(rank_snapshot.get('flex'))}"
                    ),
                })
            else:
                rank_message = (
                    (rank_data.get("status") or {}).get(
                        "message"
                    )
                    if isinstance(
                        rank_data,
                        dict,
                    )
                    else ""
                )
                self._riot_sync_post({
                    "type": "rank_warning",
                    "message": (
                        f"League-V4 on {platform} returned "
                        f"HTTP {rank_status}: {rank_message or 'no message'}"
                    ),
                })

                if rank_status in {
                    401,
                    403,
                }:
                    self._riot_sync_post({
                        "type": "error",
                        "message": (
                            f"Riot ranked API authorization failed at League-V4 "
                            f"(HTTP {rank_status}). The PUUID was resolved, so "
                            "this failure is after identity resolution."
                        ),
                    })
                    return

            RIOT_ACCOUNT_PATH.write_text(
                json.dumps(
                    account_state,
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )

            queue_text = ", ".join(
                season["queues"].get(
                    queue_id,
                    str(queue_id),
                )
                for queue_id in queue_ids
            )

            self._riot_sync_post({
                "type": "status",
                "message": (
                    f"Account found: {resolved_id}. "
                    f"Scanning {scope_info['name']} ranked only: {queue_text}."
                ),
            })

            # Query each ranked queue separately so normal games never enter
            # the ID list in the first place.
            match_ids = []
            seen_ids = set()

            for queue_id in queue_ids:
                start = 0
                queue_name = season["queues"].get(
                    queue_id,
                    f"Q{queue_id}",
                )

                while not self._riot_sync_cancel.is_set():
                    data, page_status, headers = riot_match_ids_page(
                        puuid,
                        route,
                        api_key,
                        start=start,
                        count=100,
                        queue_id=queue_id,
                        start_time=scope_info["start_epoch"],
                    )

                    if page_status == 429:
                        retry = float(
                            headers.get(
                                "Retry-After",
                                "2",
                            )
                            or 2
                        )
                        self._riot_sync_post({
                            "type": "status",
                            "message": (
                                f"Riot rate limit reached. "
                                f"Waiting {retry:.0f}s..."
                            ),
                        })
                        time.sleep(
                            min(
                                max(
                                    retry,
                                    1.0,
                                ),
                                120.0,
                            )
                        )
                        continue

                    if page_status != 200:
                        message = (
                            (data.get("status") or {}).get(
                                "message"
                            )
                            if isinstance(
                                data,
                                dict,
                            )
                            else ""
                        )
                        self._riot_sync_post({
                            "type": "error",
                            "message": (
                                f"{queue_name} match-list request failed "
                                f"(HTTP {page_status}): {message}"
                            ),
                        })
                        return

                    page = (
                        data
                        if isinstance(
                            data,
                            list,
                        )
                        else []
                    )
                    if not page:
                        break

                    for match_id in page:
                        match_id = str(
                            match_id
                        )
                        if match_id not in seen_ids:
                            seen_ids.add(
                                match_id
                            )
                            match_ids.append(
                                match_id
                            )

                    start += len(page)

                    self._riot_sync_post({
                        "type": "status",
                        "message": (
                            f"{queue_name}: "
                            f"{len(match_ids):,} ranked matches found in selected scope..."
                        ),
                    })

                    if len(page) < 100:
                        break

                    time.sleep(1.25)

            if self._riot_sync_cancel.is_set():
                self._riot_sync_post({
                    "type": "cancelled",
                    "message": (
                        "Ranked history sync cancelled."
                    ),
                })
                return

            # Keep existing history on disk; selected-scope
            # ranked rows count as already downloaded for this sync.
            existing_rows = load_riot_history_index()
            existing_by_id = {
                str(row.get("match_id")): row
                for row in existing_rows
                if row.get("match_id")
            }

            missing = [
                match_id
                for match_id in match_ids
                if match_id not in existing_by_id
            ]

            self._riot_sync_post({
                "type": "status",
                "message": (
                    f"{len(match_ids):,} ranked matches found in selected scope. "
                    f"{len(missing):,} new match details to download."
                ),
            })

            downloaded = 0
            total_missing = len(
                missing
            )

            for match_id in missing:
                if self._riot_sync_cancel.is_set():
                    break

                while not self._riot_sync_cancel.is_set():
                    data, match_status, headers = riot_match_detail(
                        match_id,
                        route,
                        api_key,
                    )

                    if match_status == 429:
                        retry = float(
                            headers.get(
                                "Retry-After",
                                "2",
                            )
                            or 2
                        )
                        self._riot_sync_post({
                            "type": "status",
                            "message": (
                                f"Rate limit: waiting {retry:.0f}s • "
                                f"{downloaded:,}/{total_missing:,} new ranked matches"
                            ),
                        })
                        time.sleep(
                            min(
                                max(
                                    retry,
                                    1.0,
                                ),
                                120.0,
                            )
                        )
                        continue
                    break

                if self._riot_sync_cancel.is_set():
                    break

                if match_status == 200:
                    summary = riot_match_summary(
                        data,
                        puuid,
                    )

                    # Defensive check even though Match-V5 IDs were already
                    # queue/startTime filtered.
                    if (
                        summary
                        and is_ranked_row_in_scope(
                            summary,
                            scope=history_scope,
                            queue_ids=queue_ids,
                        )
                    ):
                        raw_path = (
                            RIOT_HISTORY_DIR
                            / f"{match_id}.json"
                        )
                        raw_path.write_text(
                            json.dumps(
                                data,
                                ensure_ascii=False,
                            ),
                            encoding="utf-8",
                        )
                        existing_by_id[
                            match_id
                        ] = summary

                    downloaded += 1

                    if (
                        downloaded % 10 == 0
                        or downloaded
                        == total_missing
                    ):
                        # Preserve any old rows already on disk, but the History
                        # page will display only the requested
                        # ranked scope.
                        all_rows = sorted(
                            existing_by_id.values(),
                            key=lambda row: int(
                                row.get(
                                    "game_creation_ms",
                                    0,
                                )
                                or 0
                            ),
                            reverse=True,
                        )
                        save_riot_history_index(
                            all_rows
                        )
                        stored_current = sum(
                            is_ranked_row_in_scope(
                                row,
                                scope=history_scope,
                                queue_ids=queue_ids,
                            )
                            for row in all_rows
                        )
                        self._riot_sync_post({
                            "type": "progress",
                            "downloaded": downloaded,
                            "total": total_missing,
                            "available": len(
                                match_ids
                            ),
                            "message": (
                                f"Downloaded {downloaded:,}/"
                                f"{total_missing:,} new ranked matches • "
                                f"{stored_current:,} ranked matches stored in scope"
                            ),
                        })

                elif match_status in {
                    401,
                    403,
                }:
                    self._riot_sync_post({
                        "type": "error",
                        "message": (
                            "Riot API key was rejected or expired "
                            f"(HTTP {match_status})."
                        ),
                    })
                    return
                else:
                    self._riot_sync_post({
                        "type": "status",
                        "message": (
                            f"Skipped {match_id} "
                            f"(HTTP {match_status})."
                        ),
                    })

                time.sleep(1.25)

            all_rows = sorted(
                existing_by_id.values(),
                key=lambda row: int(
                    row.get(
                        "game_creation_ms",
                        0,
                    )
                    or 0
                ),
                reverse=True,
            )
            save_riot_history_index(
                all_rows
            )

            scoped_rows = [
                row
                for row in all_rows
                if is_ranked_row_in_scope(
                    row,
                    scope=history_scope,
                    queue_ids=queue_ids,
                )
            ]

            account_state["last_sync_at"] = (
                datetime.now().isoformat(
                    timespec="seconds"
                )
            )
            RIOT_ACCOUNT_PATH.write_text(
                json.dumps(
                    account_state,
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )

            if self._riot_sync_cancel.is_set():
                self._riot_sync_post({
                    "type": "cancelled",
                    "message": (
                        f"Sync cancelled. "
                        f"{len(scoped_rows):,} ranked matches in the selected "
                        "scope are already stored."
                    ),
                })
                return

            self._riot_sync_post({
                "type": "done",
                "message": (
                    f"Sync complete: {len(scoped_rows):,} "
                    f"{scope_info['name']} ranked matches stored "
                    f"({queue_text})."
                ),
                "count": len(
                    scoped_rows
                ),
            })

        except Exception as exc:
            self._riot_sync_post({
                "type": "error",
                "message": (
                    f"Ranked history sync error: {exc}"
                ),
            })


    def _watch_riot_sync_queue(
        self,
        status_var,
        progress_var,
    ):
        while True:
            try:
                event = self._riot_sync_queue.get_nowait()
            except queue.Empty:
                break

            event_type = event.get("type")
            message = event.get(
                "message",
                "",
            )
            if message:
                status_var.set(
                    message
                )

            if event_type == "rank":
                callback = getattr(
                    self,
                    "_riot_history_refresh_callback",
                    None,
                )
                if callback:
                    try:
                        callback()
                    except Exception as exc:
                        status_var.set(
                            f"Rank UI refresh failed: {exc}"
                        )

            if event_type == "progress":
                downloaded = int(
                    event.get(
                        "downloaded",
                        0,
                    )
                )
                total = int(
                    event.get(
                        "total",
                        0,
                    )
                )
                if total > 0:
                    progress_var.set(
                        min(
                            100.0,
                            downloaded
                            / total
                            * 100.0,
                        )
                    )
            elif event_type in {
                "done",
                "cancelled",
                "error",
            }:
                if event_type == "done":
                    progress_var.set(
                        100.0
                    )
                    PERSONAL_META_SIGNAL_CACHE.clear()
                    self._history_all_rows_cache = None
                    self._history_needs_full_refresh = True
                    self.refresh_general_page(
                        allow_rank_refresh=False
                    )

                callback = getattr(
                    self,
                    "_riot_history_refresh_callback",
                    None,
                )
                if callback:
                    try:
                        callback(
                            full_refresh=True
                        )
                        self._history_has_rendered = True
                        self._history_needs_full_refresh = False
                    except TypeError:
                        try:
                            callback()
                        except Exception as exc:
                            status_var.set(
                                f"History refresh failed: {exc}"
                            )
                    except Exception as exc:
                        status_var.set(
                            f"History refresh failed: {exc}"
                        )

                self._set_history_sync_controls(
                    False
                )

        thread = getattr(
            self,
            "_riot_sync_thread",
            None,
        )
        if thread and thread.is_alive():
            self._riot_sync_watch_job = self.after(
                100,
                lambda: self._watch_riot_sync_queue(
                    status_var,
                    progress_var,
                ),
            )
        else:
            # Drain one last time shortly after the worker exits.
            if not self._riot_sync_queue.empty():
                self._riot_sync_watch_job = self.after(
                    80,
                    lambda: self._watch_riot_sync_queue(
                        status_var,
                        progress_var,
                    ),
                )
            else:
                self._set_history_sync_controls(
                    False
                )
                self.update_history_sync_state_visual()

    def cancel_riot_history_sync(
        self,
    ):
        thread = getattr(
            self,
            "_riot_sync_thread",
            None,
        )
        if (
            thread
            and thread.is_alive()
        ):
            self._riot_sync_cancel.set()
            self.history_sync_status_var.set(
                "Cancelling ranked-history sync..."
            )
        else:
            self.history_sync_status_var.set(
                "No ranked-history sync is currently running."
            )

    def _set_history_sync_controls(
        self,
        running,
    ):
        if hasattr(
            self,
            "history_sync_button",
        ):
            try:
                self.history_sync_button.configure(
                    text=(
                        "⟳  Syncing..."
                        if running
                        else "⟳  Sync Ranked"
                    ),
                    state=(
                        "disabled"
                        if running
                        else "normal"
                    ),
                )
            except Exception as exc:
                log_warning("Best-effort _set_history_sync_controls operation failed: " + str(exc))

        if hasattr(
            self,
            "history_cancel_sync_button",
        ):
            try:
                self.history_cancel_sync_button.configure(
                    state=(
                        "normal"
                        if running
                        else "disabled"
                    ),
                )
            except Exception as exc:
                log_warning("Best-effort _set_history_sync_controls operation failed: " + str(exc))

    def start_riot_history_sync(
        self,
        riot_id,
        route,
        platform,
        api_key,
        status_var,
        progress_var,
        queue_ids,
        history_scope,
    ):
        if (
            self._riot_sync_thread
            and self._riot_sync_thread.is_alive()
        ):
            status_var.set(
                "A Riot ranked-history sync is already running."
            )
            self._set_history_sync_controls(
                True
            )
            return False

        riot_id = (
            riot_id
            or ""
        ).strip()
        api_key = (
            api_key
            or ""
        ).strip()
        route = (
            route
            or "EUROPE"
        ).upper()
        platform = (
            platform
            or SETTINGS.get(
                "riot_platform",
                "EUN1",
            )
            or "EUN1"
        ).upper()
        history_scope = ranked_history_scope_info(
            history_scope
        )["key"]

        queue_ids = [
            int(queue_id)
            for queue_id in queue_ids
        ]

        if not queue_ids:
            status_var.set(
                "Select Ranked Solo/Duo and/or Ranked Flex before syncing."
            )
            self._set_history_sync_controls(
                False
            )
            return False

        if "#" not in riot_id:
            status_var.set(
                "Riot ID is invalid • use GameName#TAG."
            )
            self._set_history_sync_controls(
                False
            )
            return False

        if not api_key:
            status_var.set(
                "Riot API key is missing • enter a session key in Settings → Riot & Sync."
            )
            self._set_history_sync_controls(
                False
            )
            return False

        saved_account = load_json(
            RIOT_ACCOUNT_PATH,
            {},
        )
        saved_account.update({
            "riot_id": riot_id,
            "route": route,
            "platform": platform,
            "queue_ids": queue_ids,
            "history_scope_key": history_scope,
        })

        # Riot ID and platform are normal persistent app preferences. API key is not.
        SETTINGS["riot_id"] = riot_id
        SETTINGS["riot_platform"] = platform
        SETTINGS["ranked_history_scope"] = history_scope
        save_settings()
        strip_persisted_secrets(
            saved_account
        )
        RIOT_ACCOUNT_PATH.write_text(
            json.dumps(
                saved_account,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

        self._riot_sync_cancel.clear()

        while True:
            try:
                self._riot_sync_queue.get_nowait()
            except queue.Empty:
                break
            except Exception:
                break

        progress_var.set(
            0.0
        )
        self._set_history_sync_controls(
            True
        )

        scope_info = ranked_history_scope_info(
            history_scope
        )
        status_var.set(
            f"Connecting to Riot API • {scope_info['name']} ranked only..."
        )

        self._riot_sync_thread = threading.Thread(
            target=self._riot_history_sync_worker,
            args=(
                riot_id,
                route,
                platform,
                api_key,
                queue_ids,
                history_scope,
            ),
            name="RiotRankedHistorySync",
            daemon=True,
        )
        self._riot_sync_thread.start()

        self._watch_riot_sync_queue(
            status_var,
            progress_var,
        )
        return True


    def show_previous_games(self):
        # Backward-compatible alias for older callers.
        self.select_dashboard_view(
            "history"
        )

    def show_settings(self):
        # Backward-compatible alias for older callers.
        self.select_dashboard_view(
            "settings"
        )

    def _history_synced_ago_text(
        self,
        account_state,
    ):
        raw = str(
            (
                account_state
                or {}
            ).get(
                "last_sync_at",
                "",
            )
            or (
                account_state
                or {}
            ).get(
                "rank_updated_at",
                "",
            )
            or ""
        ).strip()
        if not raw:
            return "● Ready"

        try:
            dt = datetime.fromisoformat(
                raw.replace(
                    "Z",
                    "+00:00",
                )
            )
            now = datetime.now(
                dt.tzinfo
            ) if dt.tzinfo else datetime.now()
            seconds = max(
                0,
                int(
                    (
                        now
                        - dt
                    ).total_seconds()
                ),
            )
        except Exception:
            return "● Synced"

        if seconds < 60:
            return "● Synced just now"
        if seconds < 3600:
            return f"● Synced {seconds // 60} min ago"
        if seconds < 86400:
            return f"● Synced {seconds // 3600}h ago"
        return f"● Synced {seconds // 86400}d ago"

    def draw_history_rank_emblem(
        self,
        tier="",
        division="",
    ):
        label = getattr(
            self,
            "history_rank_emblem_label",
            None,
        )
        if label is None:
            return

        tier = str(
            tier
            or ""
        ).strip().lower()
        division = str(
            division
            or ""
        ).strip().upper()

        path = (
            HISTORY_RANK_ASSETS_DIR
            / f"{tier}.png"
        )
        photo = (
            self.load_photo(
                path,
                target_px=76,
            )
            if path.exists()
            else None
        )

        if photo:
            label.configure(
                image=photo,
                text="",
                width=0,
                height=0,
            )
            label._history_rank_photo = photo
        else:
            fallback = (
                (
                    tier[
                        :1
                    ].upper()
                    + division
                )
                if tier
                else "R"
            )
            label.configure(
                image="",
                text=fallback,
                width=6,
                height=3,
                font=ui_font(
                    13,
                    "bold",
                ),
            )
            label._history_rank_photo = None


    def open_ranked_sync_settings(
        self,
    ):
        self.select_dashboard_view(
            "settings"
        )
        try:
            self.settings_notebook.select(
                self.settings_riot_tab
            )
        except Exception as exc:
            log_warning("Best-effort open_ranked_sync_settings operation failed: " + str(exc))
        try:
            self.setting_riot_api_key_entry.focus_set()
        except Exception as exc:
            log_warning("Best-effort open_ranked_sync_settings operation failed: " + str(exc))

    def start_ranked_sync_from_settings(
        self,
        auto=False,
    ):
        riot_id = str(
            self.history_riot_id_var.get()
            or ""
        ).strip()
        route = str(
            self.history_route_var.get()
            or "EUROPE"
        ).strip().upper()
        platform = str(
            self.history_platform_var.get()
            or "EUN1"
        ).strip().upper()
        api_key = str(
            self.history_api_key_var.get()
            or ""
        ).strip()

        if not riot_id:
            self.history_sync_status_var.set(
                "Riot ID is missing • configure it in Settings → Riot & Sync"
            )
            if not auto:
                self.open_ranked_sync_settings()
            return False

        if not api_key:
            self.history_sync_status_var.set(
                "Riot API key is missing • enter a session key in Settings → Riot & Sync"
            )
            if not auto:
                self.open_ranked_sync_settings()
            return False

        queue_ids = [
            queue_id
            for queue_id, enabled in (
                (
                    420,
                    self.history_solo_var.get(),
                ),
                (
                    440,
                    self.history_flex_var.get(),
                ),
            )
            if enabled
        ]
        if not queue_ids:
            self.history_sync_status_var.set(
                "Select Ranked Solo/Duo and/or Ranked Flex before syncing."
            )
            if not auto:
                self.rs_warning(
                    "Riot Ranked History",
                    "Select Ranked Solo/Duo and/or Ranked Flex.",
                )
            return False

        thread = getattr(
            self,
            "_riot_sync_thread",
            None,
        )
        if (
            thread
            and thread.is_alive()
        ):
            self.history_sync_status_var.set(
                "A ranked-history sync is already running."
            )
            return False

        # Persist only non-secret account fields before the sync starts.
        SETTINGS[
            "riot_id"
        ] = riot_id
        SETTINGS[
            "riot_platform"
        ] = platform
        SETTINGS[
            "riot_route"
        ] = route
        save_settings()

        return bool(
            self.start_riot_history_sync(
                riot_id,
                route,
                platform,
                api_key,
                self.history_sync_status_var,
                self.history_progress_var,
                queue_ids,
                self.history_scope_var.get(),
            )
        )


    def _build_custom_history_tab_bar(
        self,
        parent,
        notebook,
        specs,
        detail=False,
    ):
        """
        Build the flat target-style History tab bar.

        The underlying ttk.Notebook tabs are hidden; these controls provide the
        visible icon/text/underline treatment from the target design.
        """
        bar_bg = (
            PANEL
            if detail
            else BG
        )
        bar = tk.Frame(
            parent,
            bg=bar_bg,
            height=38,
            highlightthickness=1,
            highlightbackground=BORDER,
        )
        bar.pack(
            fill="x",
            before=notebook,
            pady=(
                0,
                0,
            ),
        )
        bar.pack_propagate(
            False
        )

        entries = []
        photos = []

        for index, (
            label_text,
            icon_name,
        ) in enumerate(
            specs
        ):
            cell = tk.Frame(
                bar,
                bg=bar_bg,
                cursor="hand2",
            )
            cell.pack(
                side="left",
                fill="y",
                padx=(
                    0
                    if index == 0
                    else 2,
                    0,
                ),
            )

            content = tk.Frame(
                cell,
                bg=bar_bg,
                cursor="hand2",
            )
            content.pack(
                fill="both",
                expand=True,
                padx=(
                    13
                    if not detail
                    else 10
                ),
                pady=(5, 2),
            )

            icon_label = None
            if icon_name:
                icon_path = (
                    HISTORY_TAB_ASSETS_DIR
                    / f"{icon_name}.png"
                )
                photo = self.load_photo(
                    icon_path,
                    target_px=16,
                )
                if photo:
                    photos.append(
                        photo
                    )
                    icon_label = tk.Label(
                        content,
                        image=photo,
                        bg=bar_bg,
                        bd=0,
                        cursor="hand2",
                    )
                    icon_label._history_tab_photo = photo
                    icon_label.pack(
                        side="left",
                        padx=(0, 7),
                    )

            label = tk.Label(
                content,
                text=label_text,
                bg=bar_bg,
                fg=MUTED,
                font=ui_font(
                    7,
                    "bold",
                ),
                cursor="hand2",
            )
            label.pack(
                side="left",
            )

            underline = tk.Frame(
                cell,
                bg=bar_bg,
                height=2,
            )
            underline.pack(
                side="bottom",
                fill="x",
            )

            entry = {
                "cell": cell,
                "content": content,
                "icon": icon_label,
                "label": label,
                "underline": underline,
            }
            entries.append(
                entry
            )

            def select_tab(
                _event=None,
                tab_index=index,
            ):
                try:
                    notebook.select(
                        tab_index
                    )
                except Exception:
                    return
                self._sync_custom_history_tab_bar(
                    notebook,
                    entries,
                    detail=detail,
                )

            for widget in (
                cell,
                content,
                label,
                icon_label,
            ):
                if widget is not None:
                    widget.bind(
                        "<Button-1>",
                        select_tab,
                    )

        notebook.bind(
            "<<NotebookTabChanged>>",
            lambda _event: self._sync_custom_history_tab_bar(
                notebook,
                entries,
                detail=detail,
            ),
            add="+",
        )

        self.after_idle(
            lambda: self._sync_custom_history_tab_bar(
                notebook,
                entries,
                detail=detail,
            )
        )
        return (
            bar,
            entries,
            photos,
        )

    def _sync_custom_history_tab_bar(
        self,
        notebook,
        entries,
        detail=False,
    ):
        try:
            selected = notebook.index(
                notebook.select()
            )
        except Exception:
            selected = 0

        base_bg = (
            PANEL
            if detail
            else BG
        )
        selected_bg = (
            DEEP_BG
            if detail
            else PANEL
        )

        for index, entry in enumerate(
            entries
        ):
            active = (
                index
                == selected
            )
            bg = (
                selected_bg
                if active
                else base_bg
            )
            fg = (
                ACCENT
                if active
                else MUTED
            )
            underline_bg = (
                ACCENT
                if active
                else bg
            )

            for key in (
                "cell",
                "content",
                "icon",
            ):
                widget = entry.get(
                    key
                )
                if widget is not None:
                    try:
                        widget.configure(
                            bg=bg
                        )
                    except Exception as exc:
                        log_warning("Best-effort _sync_custom_history_tab_bar operation failed: " + str(exc))

            entry[
                "label"
            ].configure(
                bg=bg,
                fg=fg,
            )
            entry[
                "underline"
            ].configure(
                bg=underline_bg
            )

