        def schedule_history_search(
            *_args,
        ):
            if self.history_search_job is not None:
                try:
                    self.after_cancel(
                        self.history_search_job
                    )
                except Exception as exc:
                    log_warning("Best-effort schedule_history_search operation failed: " + str(exc))
            self.history_search_job = self.after(
                160,
                lambda: self.refresh_history_tree(
                    reset_limit=True,
                    full_refresh=False,
                ),
            )

