    def on_settings_control_changed(
        self,
    ):
        """
        Checkbox/combobox changes are applied and persisted immediately.

        Apply & Save remains available for Riot ID edits and as an explicit
        confirmation action.
        """
        self.save_integrated_settings(
            silent=True
        )

    def apply_runtime_settings(
        self,
    ):
        """
        Push persisted Settings into the already-running application.

        Older versions mostly changed the SETTINGS dict but did not refresh the UI that had
        already been constructed, which made several controls appear broken.
        """
        if hasattr(
            self,
            "compact_live_var",
        ):
            self.compact_live_var.set(
                bool(
                    SETTINGS.get(
                        "smart_compact_live",
                        True,
                    )
                )
            )

        if hasattr(
            self,
            "auto_import_runes_var",
        ):
            self.auto_import_runes_var.set(
                bool(
                    SETTINGS.get(
                        "auto_import_runes",
                        True,
                    )
                )
            )

        # Appearance is live; no restart is required.
        self.apply_theme_live(
            SETTINGS.get(
                "appearance",
                "DARK",
            )
        )

        # Text-size fonts are named/live in V43, so this updates existing widgets.
        self.apply_ui_text_size_live()

        # Show/hide live sections immediately.
        self.apply_compact_live_visibility()

        if hasattr(
            self,
            "general_page",
        ):
            self.refresh_general_page()

        # Re-render things whose size/ranking depends on settings.
        self.draft_signature = None
        self.adaptive_signature = None
        self.current_item_signature = None
        self.enemy_inventory_signature = None

        # Meta source/refresh settings are live too. A changed source set makes
        # the existing cache stale and schedules a background rebuild.
        current_meta_champion = (
            getattr(
                self,
                "current_player_champion",
                "",
            )
            or getattr(
                self,
                "current_rune_champion",
                "",
            )
        )
        if current_meta_champion:
            self.meta_last_attempt.pop(
                normalize_name(
                    current_meta_champion
                ),
                None,
            )
            current_meta_role = (
                getattr(
                    self,
                    "current_rune_role",
                    "",
                )
                or getattr(
                    self,
                    "current_player_role",
                    "",
                )
            )
            self.ensure_meta_for_champion(
                current_meta_champion,
                role=current_meta_role,
            )
        else:
            self.update_meta_status_ui(
                ""
            )

        # Champion pool and build reactivity are read from SETTINGS by the normal
        # draft/build render path. Trigger a non-blocking refresh now.
        try:
            if not self._poll_in_flight:
                self.after(
                    15,
                    self.refresh_all,
                )
        except Exception as exc:
            log_warning("Best-effort apply_runtime_settings operation failed: " + str(exc))

        # Apply saved pane ratio without waiting for an app restart.
        try:
            self.after_idle(
                self.apply_saved_split_ratio
            )
        except Exception as exc:
            log_warning("Best-effort apply_runtime_settings operation failed: " + str(exc))

        try:
            self.update_idletasks()
        except Exception as exc:
            log_warning("Best-effort apply_runtime_settings operation failed: " + str(exc))

