    def _settings_all_champions(self):
        names = all_champion_names(
            self.dd
        )
        return (
            names
            if names
            else sorted(
                DRAFT_PROFILES.keys()
            )
        )

    def settings_change_pool_role(
        self,
    ):
        role = str(
            self.settings_pool_role_var.get()
            or "JUNGLE"
        ).upper()
        if role not in DRAFT_ROLE_KEYS:
            role = "JUNGLE"
            self.settings_pool_role_var.set(
                role
            )

        if not hasattr(
            self,
            "settings_role_pool_names",
        ):
            self.settings_role_pool_names = migrated_role_pool_map(
                SETTINGS
            )

        self.settings_pool_names = self.settings_role_pool_names.setdefault(
            role,
            [],
        )
        self.settings_pool_target_label_var.set(
            f"MY {role} POOL"
        )
        self.settings_pool_role_summary_var.set(
            f"{draft_role_display(role)} pool • {len(self.settings_pool_names)} champions"
        )
        self.refresh_settings_pool_lists()

    def _settings_filtered_available(self):
        pool_set = set(
            self.settings_pool_names
        )
        query = (
            self.settings_pool_search_var.get()
            .strip()
            .lower()
        )

        values = [
            champion
            for champion in self._settings_all_champions()
            if champion not in pool_set
        ]

        if query:
            values = [
                champion
                for champion in values
                if query in champion.lower()
            ]
        return values

    def refresh_settings_pool_lists(self):
        if not hasattr(
            self,
            "settings_available_box",
        ):
            return

        self.settings_available_box.delete(
            0,
            "end",
        )
        self.settings_pool_box.delete(
            0,
            "end",
        )

        for champion in self._settings_filtered_available():
            self.settings_available_box.insert(
                "end",
                champion,
            )

        for champion in sorted(
            self.settings_pool_names
        ):
            self.settings_pool_box.insert(
                "end",
                champion,
            )

        role = str(
            self.settings_pool_role_var.get()
            or "JUNGLE"
        ).upper()
        curated_count = sum(
            champion in DRAFT_PROFILES
            for champion in self.settings_pool_names
        )
        generic_count = (
            len(
                self.settings_pool_names
            )
            - curated_count
        )
        total_unique = len({
            champion
            for champions in getattr(
                self,
                "settings_role_pool_names",
                {},
            ).values()
            for champion in champions
        })
        self.settings_pool_count_var.set(
            f"{role}: {len(self.settings_pool_names)} champions • "
            f"{curated_count} curated • {generic_count} generic • "
            f"{total_unique} unique across all roles"
        )
        self.settings_pool_role_summary_var.set(
            f"{draft_role_display(role)} pool • {len(self.settings_pool_names)} champions"
        )

    def settings_add_selected(self):
        additions = [
            self.settings_available_box.get(
                index
            )
            for index in self.settings_available_box.curselection()
        ]
        for champion in additions:
            if champion not in self.settings_pool_names:
                self.settings_pool_names.append(
                    champion
                )
        self.refresh_settings_pool_lists()
        self.save_integrated_settings(
            silent=True
        )

    def settings_remove_selected(self):
        removals = {
            self.settings_pool_box.get(
                index
            )
            for index in self.settings_pool_box.curselection()
        }
        if not removals:
            return

        self.settings_pool_names[:] = [
            champion
            for champion in self.settings_pool_names
            if champion not in removals
        ]
        self.refresh_settings_pool_lists()
        self.save_integrated_settings(
            silent=True
        )

    def settings_add_visible(self):
        for champion in self._settings_filtered_available():
            if champion not in self.settings_pool_names:
                self.settings_pool_names.append(
                    champion
                )
        self.refresh_settings_pool_lists()
        self.save_integrated_settings(
            silent=True
        )

    def settings_reset_curated(self):
        role = str(
            self.settings_pool_role_var.get()
            or "JUNGLE"
        ).upper()

        defaults = []
        for champion, profile in DRAFT_PROFILES.items():
            roles = draft_profile_role_keys(
                profile
            )
            if (
                "ANY" in roles
                or role in roles
            ):
                defaults.append(
                    champion
                )

        # Curated JSON may not cover every role yet. Use the role fallback as
        # the editor default rather than leaving Reset with an empty result.
        if not defaults:
            defaults = list(
                DRAFT_ROLE_FALLBACK_POOL.get(
                    role,
                    [],
                )
            )

        self.settings_pool_names[:] = sorted(
            _clean_champion_list(
                defaults
            )
        )
        self.settings_pool_search_var.set(
            ""
        )
        self.refresh_settings_pool_lists()
        self.save_integrated_settings(
            silent=True
        )

    def _watch_riot_api_test_queue(
        self,
    ):
        queue_obj = getattr(
            self,
            "_riot_api_test_queue",
            None,
        )
        if queue_obj is None:
            return

        message = None
        try:
            while True:
                message = queue_obj.get_nowait()
        except queue.Empty:
            pass
        except Exception as exc:
            log_warning("Best-effort _watch_riot_api_test_queue operation failed: " + str(exc))

        if message is not None:
            self.last_riot_api_diagnostic = str(
                message
            )
            self.history_sync_status_var.set(
                str(
                    message
                )
            )
            try:
                self.setting_test_api_button.configure(
                    text="Test API",
                    state="normal",
                )
            except Exception as exc:
                log_warning("Best-effort _watch_riot_api_test_queue operation failed: " + str(exc))
            self._riot_api_test_job = None
            return

        thread = getattr(
            self,
            "_riot_api_test_thread",
            None,
        )
        if (
            thread
            and thread.is_alive()
        ):
            self._riot_api_test_job = self.after(
                80,
                self._watch_riot_api_test_queue,
            )
        else:
            try:
                message = queue_obj.get_nowait()
            except Exception:
                message = None

            if message is not None:
                self.history_sync_status_var.set(
                    str(
                        message
                    )
                )
            else:
                self.history_sync_status_var.set(
                    "API TEST ERROR • Worker returned no result. Open Settings → Diagnostics → Open Latest Log."
                )

            try:
                self.setting_test_api_button.configure(
                    text="Test API",
                    state="normal",
                )
            except Exception as exc:
                log_warning("Best-effort _watch_riot_api_test_queue operation failed: " + str(exc))
            self._riot_api_test_job = None

    def test_riot_api_access(
        self,
    ):
        """
        Validate the current session key without writing history.

        PUUID is resolved locally/saved when possible, then League-V4 and
        Match-V5 are tested independently.
        """
        api_key = str(
            self.setting_riot_api_key_var.get()
            or ""
        ).strip()
        riot_id = str(
            self.setting_riot_id_var.get()
            or ""
        ).strip()
        platform = str(
            self.setting_riot_platform_var.get()
            or "EUN1"
        ).strip().upper()
        route = str(
            self.setting_riot_route_var.get()
            or "EUROPE"
        ).strip().upper()

        if not api_key:
            self.history_sync_status_var.set(
                "API TEST • Enter a session Riot API key first."
            )
            return

        if "#" not in riot_id:
            self.history_sync_status_var.set(
                "API TEST • Riot ID must be GameName#TAG."
            )
            return

        old_job = getattr(
            self,
            "_riot_api_test_job",
            None,
        )
        if old_job is not None:
            try:
                self.after_cancel(
                    old_job
                )
            except Exception as exc:
                log_warning("Best-effort test_riot_api_access operation failed: " + str(exc))

        self._riot_api_test_queue = queue.Queue()

        try:
            self.setting_test_api_button.configure(
                text="Testing...",
                state="disabled",
            )
        except Exception as exc:
            log_warning("Best-effort test_riot_api_access operation failed: " + str(exc))

        self.history_sync_status_var.set(
            "API TEST • Resolving PUUID..."
        )

        def finish(
            message,
        ):
            try:
                self._riot_api_test_queue.put_nowait(
                    str(
                        message
                    )
                )
            except Exception as exc:
                log_warning("Best-effort finish operation failed: " + str(exc))

        def worker():
            try:
                identity = self._history_local_identity(
                    riot_id
                )

                if (
                    isinstance(
                        identity,
                        dict,
                    )
                    and identity.get(
                        "error"
                    )
                ):
                    finish(
                        "API TEST • "
                        + str(
                            identity[
                                "error"
                            ]
                        )
                    )
                    return

                if (
                    isinstance(
                        identity,
                        dict,
                    )
                    and identity.get(
                        "puuid"
                    )
                ):
                    puuid = str(
                        identity[
                            "puuid"
                        ]
                    )
                    source = str(
                        identity.get(
                            "source",
                            "local identity",
                        )
                    )
                else:
                    account, account_status, account_error = (
                        riot_account_by_riot_id(
                            riot_id,
                            route,
                            api_key,
                        )
                    )
                    if not account:
                        finish(
                            (
                                "API TEST • ACCOUNT-V1 "
                                f"HTTP {account_status or '-'} • "
                                f"{account_error or 'no message'}"
                                f"{riot_api_status_hint(account_status)} • "
                                "Keep League Client open so RiftSense can bypass "
                                "ACCOUNT-V1 and test ranked APIs directly."
                            )
                        )
                        return

                    puuid = str(
                        account.get(
                            "puuid",
                            "",
                        )
                        or ""
                    )
                    source = "ACCOUNT-V1"

                league_data, league_status, _league_headers = (
                    riot_league_entries_by_puuid(
                        puuid,
                        platform,
                        api_key,
                    )
                )
                league_message = (
                    (
                        league_data.get(
                            "status",
                            {},
                        )
                        or {}
                    ).get(
                        "message",
                        "",
                    )
                    if isinstance(
                        league_data,
                        dict,
                    )
                    else ""
                )

                if league_status != 200:
                    finish(
                        (
                            f"API TEST • PUUID via {source} • "
                            f"League-V4 HTTP {league_status or '-'} • "
                            f"{league_message or 'request not authorized'}"
                            f"{riot_api_status_hint(league_status)}"
                        )
                    )
                    return

                match_data, match_status, _match_headers = riot_match_ids_page(
                    puuid,
                    route,
                    api_key,
                    start=0,
                    count=1,
                    queue_id=420,
                    start_time=None,
                )
                match_message = (
                    (
                        match_data.get(
                            "status",
                            {},
                        )
                        or {}
                    ).get(
                        "message",
                        "",
                    )
                    if isinstance(
                        match_data,
                        dict,
                    )
                    else ""
                )

                if match_status == 200:
                    finish(
                        (
                            f"API TEST OK • PUUID via {source} • "
                            "League-V4 HTTP 200 • Match-V5 HTTP 200"
                        )
                    )
                else:
                    finish(
                        (
                            f"API TEST PARTIAL • PUUID via {source} • "
                            "League-V4 HTTP 200 • "
                            f"Match-V5 HTTP {match_status or '-'} • "
                            f"{match_message or 'request not authorized'}"
                            f"{riot_api_status_hint(match_status)}"
                        )
                    )
            except Exception as exc:
                log_exception(
                    "Riot API test worker failed",
                    exc,
                )
                finish(
                    "API TEST ERROR • "
                    + str(exc)
                )

        self._riot_api_test_thread = threading.Thread(
            target=worker,
            name="RiftApiDiagnostic",
            daemon=True,
        )
        self._riot_api_test_thread.start()
        self._riot_api_test_job = self.after(
            80,
            self._watch_riot_api_test_queue,
        )


    def _watch_verify_sync_queue(
        self,
    ):
        queue_obj = getattr(
            self,
            "_verify_sync_queue",
            None,
        )
        if queue_obj is None:
            return

        result = None
        try:
            result = queue_obj.get_nowait()
        except queue.Empty:
            result = None
        except Exception:
            result = None

        if result is None:
            thread = getattr(
                self,
                "_verify_sync_thread",
                None,
            )
            if (
                thread
                and thread.is_alive()
            ):
                self._verify_sync_job = self.after(
                    80,
                    self._watch_verify_sync_queue,
                )
                return

            self.history_sync_status_var.set(
                "VERIFY SYNC • Verification worker ended without a result."
            )
            try:
                self.setting_verify_sync_button.configure(
                    text="Verify & Sync",
                    state="normal",
                )
            except Exception as exc:
                log_warning("Best-effort _watch_verify_sync_queue operation failed: " + str(exc))
            self._verify_sync_job = None
            return

        ok = bool(
            result.get(
                "ok",
                False,
            )
        )
        message = str(
            result.get(
                "message",
                "",
            )
            or ""
        )
        self.last_verify_sync_result = (
            message
            or (
                "VERIFY SYNC OK"
                if ok
                else "VERIFY SYNC FAILED"
            )
        )

        if not ok:
            self.history_sync_status_var.set(
                message
                or "VERIFY SYNC FAILED"
            )
            try:
                self.setting_verify_sync_button.configure(
                    text="Verify & Sync",
                    state="normal",
                )
            except Exception as exc:
                log_warning("Best-effort _watch_verify_sync_queue operation failed: " + str(exc))
            self._verify_sync_job = None
            return

        self.history_sync_status_var.set(
            message
            or "VERIFY SYNC OK • starting real ranked sync..."
        )

        started = self.start_ranked_sync_from_settings(
            auto=True
        )
        try:
            self.setting_verify_sync_button.configure(
                text="Verify & Sync",
                state="normal",
            )
        except Exception as exc:
            log_warning("Best-effort _watch_verify_sync_queue operation failed: " + str(exc))

        if not started:
            if not self.history_sync_status_var.get():
                self.history_sync_status_var.set(
                    "VERIFY SYNC OK • real sync could not be started."
                )

        self._verify_sync_job = None

    def verify_and_sync_ranked(
        self,
    ):
        """
        Pre-push / real-installation check.

        This validates the exact live pipeline on the user's machine:
          PUUID -> League-V4 -> Match-V5 list -> Match-V5 detail
        and only then launches RiftSense's normal full ranked-history sync.

        No key is persisted by this test.
        """
        api_key = str(
            self.setting_riot_api_key_var.get()
            or ""
        ).strip()
        riot_id = str(
            self.setting_riot_id_var.get()
            or ""
        ).strip()
        platform = str(
            self.setting_riot_platform_var.get()
            or "EUN1"
        ).strip().upper()
        route = str(
            self.setting_riot_route_var.get()
            or "EUROPE"
        ).strip().upper()

        if not api_key:
            self.history_sync_status_var.set(
                "VERIFY SYNC • Enter a session Riot API key first."
            )
            return

        if "#" not in riot_id:
            self.history_sync_status_var.set(
                "VERIFY SYNC • Riot ID must be GameName#TAG."
            )
            return

        running = getattr(
            self,
            "_riot_sync_thread",
            None,
        )
        if (
            running
            and running.is_alive()
        ):
            self.history_sync_status_var.set(
                "VERIFY SYNC • A ranked-history sync is already running."
            )
            return

        queue_ids = self._selected_history_queue_ids()
        if not queue_ids:
            self.history_sync_status_var.set(
                "VERIFY SYNC • Select Solo/Duo and/or Flex first."
            )
            return

        try:
            self.setting_verify_sync_button.configure(
                text="Verifying...",
                state="disabled",
            )
        except Exception as exc:
            log_warning("Best-effort verify_and_sync_ranked operation failed: " + str(exc))

        self.history_sync_status_var.set(
            "VERIFY SYNC • Resolving PUUID..."
        )

        self._verify_sync_queue = queue.Queue()

        def finish(
            ok,
            message,
        ):
            try:
                self._verify_sync_queue.put_nowait({
                    "ok": bool(
                        ok
                    ),
                    "message": str(
                        message
                    ),
                })
            except Exception as exc:
                log_warning("Best-effort finish operation failed: " + str(exc))

        def worker():
            identity = self._history_local_identity(
                riot_id
            )

            if (
                isinstance(
                    identity,
                    dict,
                )
                and identity.get(
                    "error"
                )
            ):
                finish(
                    False,
                    (
                        "VERIFY SYNC FAILED • "
                        + str(
                            identity[
                                "error"
                            ]
                        )
                    ),
                )
                return

            if (
                isinstance(
                    identity,
                    dict,
                )
                and identity.get(
                    "puuid"
                )
            ):
                puuid = str(
                    identity[
                        "puuid"
                    ]
                )
                source = str(
                    identity.get(
                        "source",
                        "local identity",
                    )
                )
            else:
                account, status, error = riot_account_by_riot_id(
                    riot_id,
                    route,
                    api_key,
                )
                if not account:
                    finish(
                        False,
                        (
                            "VERIFY SYNC FAILED • ACCOUNT-V1 "
                            f"HTTP {status or '-'} • "
                            f"{error or 'no message'} • "
                            "Keep League Client open so RiftSense can resolve "
                            "your PUUID locally."
                        ),
                    )
                    return

                puuid = str(
                    account.get(
                        "puuid",
                        "",
                    )
                    or ""
                )
                source = "ACCOUNT-V1"

            league_data, league_status, _league_headers = (
                riot_league_entries_by_puuid(
                    puuid,
                    platform,
                    api_key,
                )
            )
            if league_status != 200:
                league_message = (
                    (
                        league_data.get(
                            "status",
                            {},
                        )
                        or {}
                    ).get(
                        "message",
                        "",
                    )
                    if isinstance(
                        league_data,
                        dict,
                    )
                    else ""
                )
                finish(
                    False,
                    (
                        f"VERIFY SYNC FAILED • PUUID via {source} • "
                        f"League-V4 HTTP {league_status or '-'} • "
                        f"{league_message or 'request not authorized'}"
                    ),
                )
                return

            tested_queue = int(
                queue_ids[
                    0
                ]
            )
            match_ids, match_status, _match_headers = riot_match_ids_page(
                puuid,
                route,
                api_key,
                start=0,
                count=1,
                queue_id=tested_queue,
                start_time=None,
            )

            if match_status != 200:
                match_message = (
                    (
                        match_ids.get(
                            "status",
                            {},
                        )
                        or {}
                    ).get(
                        "message",
                        "",
                    )
                    if isinstance(
                        match_ids,
                        dict,
                    )
                    else ""
                )
                finish(
                    False,
                    (
                        f"VERIFY SYNC FAILED • League-V4 HTTP 200 • "
                        f"Match-V5 list HTTP {match_status or '-'} • "
                        f"{match_message or 'request not authorized'}"
                    ),
                )
                return

            first_match_id = (
                str(
                    match_ids[
                        0
                    ]
                )
                if isinstance(
                    match_ids,
                    list,
                )
                and match_ids
                else ""
            )

            if first_match_id:
                detail, detail_status, _detail_headers = riot_match_detail(
                    first_match_id,
                    route,
                    api_key,
                )

                if (
                    detail_status != 200
                    or not isinstance(
                        detail,
                        dict,
                    )
                    or not isinstance(
                        detail.get(
                            "info"
                        ),
                        dict,
                    )
                    or not isinstance(
                        detail.get(
                            "metadata"
                        ),
                        dict,
                    )
                ):
                    finish(
                        False,
                        (
                            "VERIFY SYNC FAILED • Match-V5 list HTTP 200 • "
                            f"Match detail HTTP {detail_status or '-'} • "
                            "detail payload was not usable"
                        ),
                    )
                    return

                detail_text = (
                    f"detail {first_match_id} HTTP 200"
                )
            else:
                detail_text = (
                    "no recent match in selected queue; Match-V5 list access OK"
                )

            finish(
                True,
                (
                    f"VERIFY SYNC OK • PUUID via {source} • "
                    "League-V4 HTTP 200 • Match-V5 list HTTP 200 • "
                    f"{detail_text} • starting real ranked sync..."
                ),
            )

        self._verify_sync_thread = threading.Thread(
            target=worker,
            name="RiftVerifySync",
            daemon=True,
        )
        self._verify_sync_thread.start()

        if getattr(
            self,
            "_verify_sync_job",
            None,
        ) is not None:
            try:
                self.after_cancel(
                    self._verify_sync_job
                )
            except Exception as exc:
                log_warning("Best-effort verify_and_sync_ranked operation failed: " + str(exc))

        self._verify_sync_job = self.after(
            80,
            self._watch_verify_sync_queue,
        )

    def save_integrated_settings(self, silent=False):
        riot_id = (
            self.setting_riot_id_var.get()
            or ""
        ).strip()

        riot_platform = (
            self.setting_riot_platform_var.get()
            or "EUN1"
        ).strip().upper()

        riot_route = (
            self.setting_riot_route_var.get()
            or "EUROPE"
        ).strip().upper()

        session_api_key = str(
            self.setting_riot_api_key_var.get()
            or ""
        ).strip()

        if (
            riot_id
            and (
                "#" not in riot_id
                or riot_id.startswith("#")
                or riot_id.endswith("#")
            )
        ):
            self.rs_warning(
                "Riot ID",
                "Enter Riot ID as GameName#TAG, for example Player#EUNE.",
            )
            return

        if riot_platform not in RIOT_PLATFORM_ROUTES:
            self.rs_warning(
                "Riot platform",
                "Choose a valid Riot platform, for example EUN1 for EUNE.",
            )
            return

        if riot_route not in {
            "EUROPE",
            "AMERICAS",
            "ASIA",
            "SEA",
        }:
            self.rs_warning(
                "Riot route",
                "Choose EUROPE, AMERICAS, ASIA or SEA.",
            )
            return

        role_pool_map = {
            role: sorted(
                _clean_champion_list(
                    getattr(
                        self,
                        "settings_role_pool_names",
                        {},
                    ).get(
                        role,
                        [],
                    )
                )
            )
            for role in DRAFT_ROLE_KEYS
        }
        champion_pool_union = sorted({
            champion
            for champions in role_pool_map.values()
            for champion in champions
        })

        SETTINGS.update({
            "riot_id": riot_id,
            "riot_platform": riot_platform,
            "riot_route": riot_route,
            "smart_compact_live": bool(
                self.setting_compact_var.get()
            ),
            "auto_patch_refresh": bool(
                self.setting_patch_var.get()
            ),
            "show_current_items": bool(
                self.setting_current_var.get()
            ),
            "show_enemy_threats": bool(
                self.setting_threats_var.get()
            ),
            "show_baseline_build": bool(
                self.setting_baseline_var.get()
            ),
            "show_strategy_summary": bool(
                self.setting_strategy_var.get()
            ),
            "show_objective_readiness": bool(
                self.setting_readiness_var.get()
            ),
            "auto_import_runes": bool(
                self.setting_auto_runes_var.get()
            ),
            "build_reactivity": float(
                self.setting_react_var.get()
            ),
            "champion_icon_px": int(
                self.setting_icon_var.get()
            ),
            "draft_icon_px": int(
                self.setting_draft_icon_var.get()
            ),
            "split_ratio": (
                int(
                    self.setting_split_var.get()
                )
                / 100.0
            ),
            "ui_text_size": (
                self.setting_text_size_var.get()
                or "LARGE"
            ).upper(),
            "appearance": (
                self.setting_appearance_var.get()
                or "DARK"
            ).upper(),
            "meta_consensus_enabled": bool(
                self.setting_meta_enabled_var.get()
            ),
            "meta_refresh_hours": int(
                self.setting_meta_refresh_var.get()
                or 24
            ),
            "meta_source_lolalytics": bool(
                self.setting_meta_lolalytics_var.get()
            ),
            "meta_source_ugg": bool(
                self.setting_meta_ugg_var.get()
            ),
            "meta_source_opgg": bool(
                self.setting_meta_opgg_var.get()
            ),
            "meta_source_mobalytics": bool(
                self.setting_meta_mobalytics_var.get()
            ),
            "meta_source_leagueofgraphs": bool(
                self.setting_meta_leagueofgraphs_var.get()
            ),
            # champion_pool remains as a compatibility union for older code/
            # settings files. Draft Assistant itself uses champion_pool_by_role.
            "champion_pool": champion_pool_union,
            "champion_pool_by_role": role_pool_map,
        })

        if not save_settings():
            self.settings_saved_var.set(
                "SAVE FAILED"
            )
            if not silent:
                self.rs_error(
                    "Settings save failed",
                    (
                        f"{APP_NAME} could not write settings.json.\n\n"
                        f"{SETTINGS_SAVE_ERROR or 'Unknown filesystem error'}\n\n"
                        f"Path: {SETTINGS_PATH}"
                    ),
                )
            return False

        # Keep the integrated History page in sync with Settings immediately.
        if hasattr(
            self,
            "history_riot_id_var",
        ):
            self.history_riot_id_var.set(
                riot_id
            )

        if hasattr(
            self,
            "history_platform_var",
        ):
            self.history_platform_var.set(
                riot_platform
            )

        if hasattr(
            self,
            "history_route_var",
        ):
            self.history_route_var.set(
                riot_route
            )

        account_state = load_json(
            RIOT_ACCOUNT_PATH,
            {},
        )
        if not isinstance(
            account_state,
            dict,
        ):
            account_state = {}
        account_state["riot_id"] = riot_id
        account_state["platform"] = riot_platform
        account_state["route"] = riot_route
        strip_persisted_secrets(
            account_state
        )
        try:
            RIOT_ACCOUNT_PATH.write_text(
                json.dumps(
                    account_state,
                    ensure_ascii=False,
                    indent=2,
                ),
                encoding="utf-8",
            )
        except Exception as exc:
            log_warning("Best-effort save_integrated_settings operation failed: " + str(exc))

        self.apply_runtime_settings()

        self._history_auto_sync_pending = bool(
            session_api_key
        )

        if session_api_key:
            self.history_sync_status_var.set(
                "Session API key ready • starting ranked-history sync..."
            )
            saved_message = (
                "Saved • API key ready • ranked sync starting"
            )
            if self._history_auto_sync_job is not None:
                try:
                    self.after_cancel(
                        self._history_auto_sync_job
                    )
                except Exception as exc:
                    log_warning("Best-effort save_integrated_settings operation failed: " + str(exc))
            self._history_auto_sync_job = self.after(
                120,
                self._maybe_start_history_auto_sync,
            )
        else:
            saved_message = (
                f"Saved & applied • {riot_id}"
                if riot_id
                else "Saved & applied"
            )

        self.settings_saved_var.set(
            saved_message
        )

        self.after(
            1800,
            lambda: self.settings_saved_var.set(
                ""
            ),
        )
        return True



    def _write_user_backup_zip(
        self,
        destination,
    ):
        destination = Path(
            destination
        )
        destination.parent.mkdir(
            parents=True,
            exist_ok=True,
        )

        manifest = {
            "app": "RiftSense",
            "format": 3,
            "created_at": datetime.now().isoformat(
                timespec="seconds"
            ),
            "includes": [
                "settings.json",
                "history/",
                "player_memory.json",
                "performance_history.json",
                "rank_progress.json",
                "ai_reviews/",
            ],
        }

        with zipfile.ZipFile(
            destination,
            "w",
            zipfile.ZIP_DEFLATED,
        ) as archive:
            archive.writestr(
                "backup_manifest.json",
                json.dumps(
                    manifest,
                    ensure_ascii=False,
                    indent=2,
                ),
            )

            if SETTINGS_PATH.exists():
                backup_settings = load_json(
                    SETTINGS_PATH,
                    {},
                )
                if isinstance(backup_settings, dict):
                    strip_persisted_secrets(backup_settings)
                    archive.writestr(
                        "settings.json",
                        json.dumps(
                            backup_settings,
                            ensure_ascii=False,
                            indent=2,
                        ),
                    )
                else:
                    archive.write(
                        SETTINGS_PATH,
                        "settings.json",
                    )

            if HISTORY_DIR.exists():
                for path in HISTORY_DIR.rglob(
                    "*"
                ):
                    if not path.is_file():
                        continue

                    archive_name = (
                        "history/"
                        + str(
                            path.relative_to(
                                HISTORY_DIR
                            )
                        ).replace(
                            "\\",
                            "/",
                        )
                    )

                    # Defense in depth for backups created from older local
                    # data. Legacy builds may have persisted a Riot API key
                    # in riot_account.json; never copy those fields into a
                    # newly created RiftSense backup archive.
                    if path == RIOT_ACCOUNT_PATH:
                        backup_account = load_json(
                            path,
                            {},
                        )
                        if isinstance(backup_account, dict):
                            strip_persisted_secrets(backup_account)
                            archive.writestr(
                                archive_name,
                                json.dumps(
                                    backup_account,
                                    ensure_ascii=False,
                                    indent=2,
                                ),
                            )
                            continue

                    archive.write(
                        path,
                        archive_name,
                    )

            for memory_path, archive_name in (
                (
                    PLAYER_MEMORY_PATH,
                    "player_memory.json",
                ),
                (
                    PERFORMANCE_HISTORY_PATH,
                    "performance_history.json",
                ),
                (
                    RANK_PROGRESS_PATH,
                    "rank_progress.json",
                ),
            ):
                if memory_path.exists():
                    archive.write(
                        memory_path,
                        archive_name,
                    )

            if AI_REVIEWS_DIR.exists():
                for path in AI_REVIEWS_DIR.rglob(
                    "*"
                ):
                    if path.is_file():
                        archive.write(
                            path,
                            (
                                "ai_reviews/"
                                + str(
                                    path.relative_to(
                                        AI_REVIEWS_DIR
                                    )
                                ).replace(
                                    "\\",
                                    "/",
                                )
                            ),
                        )

        return destination

    def backup_user_data(self):
        suggested = (
            "RiftSense_Backup_"
            + datetime.now().strftime(
                "%Y-%m-%d_%H-%M"
            )
            + ".zip"
        )
        destination = filedialog.asksaveasfilename(
            title="Backup RiftSense data",
            defaultextension=".zip",
            filetypes=[
                (
                    "ZIP backup",
                    "*.zip",
                ),
            ],
            initialfile=suggested,
        )
        if not destination:
            return

        try:
            self._write_user_backup_zip(
                destination
            )
            self.rs_info(
                "Backup complete",
                (
                    "Settings, ranked history, rank progression and persistent player memory were backed up successfully.\n\n"
                    f"{destination}"
                ),
            )
        except Exception as exc:
            self.rs_error(
                "Backup failed",
                str(exc),
            )

    def restore_user_data(self):
        source = filedialog.askopenfilename(
            title="Restore RiftSense backup",
            filetypes=[
                (
                    "ZIP backup",
                    "*.zip",
                ),
            ],
        )
        if not source:
            return

        if not self.rs_confirm(
            "Restore backup",
            (
                "This will replace the current Settings, History, Rank Progress and Player Memory "
                "with the selected backup.\n\n"
                "A safety backup of the current data will be created first.\n\n"
                "Continue?"
            ),
            confirm_text="Restore Backup",
            danger=True,
        ):
            return

        source = Path(
            source
        )

        try:
            with zipfile.ZipFile(
                source,
                "r",
            ) as archive:
                names = archive.namelist()

                for name in names:
                    normalized = name.replace(
                        "\\",
                        "/",
                    )
                    parts = Path(
                        normalized
                    ).parts

                    if (
                        normalized.startswith("/")
                        or ".." in parts
                    ):
                        raise ValueError(
                            "Backup contains an unsafe path."
                        )

                    if normalized in {
                        "backup_manifest.json",
                        "settings.json",
                        "player_memory.json",
                        "performance_history.json",
                        "rank_progress.json",
                    }:
                        continue

                    if (
                        normalized.startswith(
                            "history/"
                        )
                        or normalized.startswith(
                            "ai_reviews/"
                        )
                    ):
                        continue

                    raise ValueError(
                        f"Unexpected file in backup: {normalized}"
                    )

                if (
                    "settings.json"
                    not in names
                    and "player_memory.json"
                    not in names
                    and not any(
                        name.startswith(
                            "history/"
                        )
                        for name in names
                    )
                ):
                    raise ValueError(
                        "This ZIP does not look like a RiftSense or legacy Rift Build Assistant backup."
                    )

                backup_dir = (
                    DATA_DIR
                    / "backups"
                )
                backup_dir.mkdir(
                    parents=True,
                    exist_ok=True,
                )
                safety_path = (
                    backup_dir
                    / (
                        "before_restore_"
                        + datetime.now().strftime(
                            "%Y-%m-%d_%H-%M-%S"
                        )
                        + ".zip"
                    )
                )
                self._write_user_backup_zip(
                    safety_path
                )

                with tempfile.TemporaryDirectory() as temp_dir:
                    temp_root = Path(
                        temp_dir
                    )
                    archive.extractall(
                        temp_root
                    )

                    restored_settings = (
                        temp_root
                        / "settings.json"
                    )
                    restored_history = (
                        temp_root
                        / "history"
                    )
                    restored_memory = (
                        temp_root
                        / "player_memory.json"
                    )
                    restored_performance = (
                        temp_root
                        / "performance_history.json"
                    )
                    restored_rank_progress = (
                        temp_root
                        / "rank_progress.json"
                    )
                    restored_ai_reviews = (
                        temp_root
                        / "ai_reviews"
                    )

                    if restored_settings.exists():
                        SETTINGS_PATH.parent.mkdir(
                            parents=True,
                            exist_ok=True,
                        )
                        shutil.copy2(
                            restored_settings,
                            SETTINGS_PATH,
                        )

                    if restored_history.exists():
                        if HISTORY_DIR.exists():
                            shutil.rmtree(
                                HISTORY_DIR
                            )
                        shutil.copytree(
                            restored_history,
                            HISTORY_DIR,
                        )

                    if restored_memory.exists():
                        shutil.copy2(
                            restored_memory,
                            PLAYER_MEMORY_PATH,
                        )

                    if restored_performance.exists():
                        shutil.copy2(
                            restored_performance,
                            PERFORMANCE_HISTORY_PATH,
                        )

                    if restored_rank_progress.exists():
                        shutil.copy2(
                            restored_rank_progress,
                            RANK_PROGRESS_PATH,
                        )

                    if restored_ai_reviews.exists():
                        if AI_REVIEWS_DIR.exists():
                            shutil.rmtree(
                                AI_REVIEWS_DIR
                            )
                        shutil.copytree(
                            restored_ai_reviews,
                            AI_REVIEWS_DIR,
                        )

            HISTORY_DIR.mkdir(
                parents=True,
                exist_ok=True,
            )
            RIOT_HISTORY_DIR.mkdir(
                parents=True,
                exist_ok=True,
            )
            AI_REVIEWS_DIR.mkdir(
                parents=True,
                exist_ok=True,
            )

            restored = load_json(
                SETTINGS_PATH,
                {},
            )
            if isinstance(restored, dict):
                if strip_persisted_secrets(restored):
                    write_json_atomic(
                        SETTINGS_PATH,
                        restored,
                    )

            restored_account = load_json(
                RIOT_ACCOUNT_PATH,
                {},
            )
            if (
                isinstance(restored_account, dict)
                and strip_persisted_secrets(restored_account)
            ):
                write_json_atomic(
                    RIOT_ACCOUNT_PATH,
                    restored_account,
                )

            SETTINGS.clear()
            SETTINGS.update(
                DEFAULT_SETTINGS
            )
            if isinstance(
                restored,
                dict,
            ):
                SETTINGS.update(
                    restored
                )

            self.history_metric_cache = {}
            self.reload_settings_page()

            if hasattr(
                self,
                "history_riot_id_var",
            ):
                self.history_riot_id_var.set(
                    str(
                        SETTINGS.get(
                            "riot_id",
                            "",
                        )
                    )
                )
            if hasattr(
                self,
                "history_platform_var",
            ):
                self.history_platform_var.set(
                    str(
                        SETTINGS.get(
                            "riot_platform",
                            "EUN1",
                        )
                    )
                )

            self.refresh_history_tree()
            self.refresh_player_memory(
                force=False,
                render=True,
            )
            self.refresh_personal_coach()
            self.refresh_general_page()

            self.rs_info(
                "Restore complete",
                (
                    "Backup restored successfully.\n\n"
                    "A copy of the previous data was saved to:\n"
                    f"{safety_path}"
                ),
            )

        except Exception as exc:
            self.rs_error(
                "Restore failed",
                str(exc),
            )

    def export_ranked_history_csv(self):
        rows = self._combined_history_rows()
        if not rows:
            self.rs_info(
                "Export Ranked CSV",
                "There are no ranked matches in the selected scope to export.",
            )
            return

        destination = filedialog.asksaveasfilename(
            title="Export ranked history for selected scope",
            defaultextension=".csv",
            filetypes=[
                (
                    "CSV file",
                    "*.csv",
                ),
            ],
            initialfile="RiftSense_Ranked_History.csv",
        )
        if not destination:
            return

        try:
            with open(
                destination,
                "w",
                newline="",
                encoding="utf-8-sig",
            ) as handle:
                writer = csv.writer(
                    handle
                )
                writer.writerow([
                    "Date",
                    "Result",
                    "Champion",
                    "Role",
                    "Kills",
                    "Deaths",
                    "Assists",
                    "CS",
                    "Duration",
                    "Queue",
                    "Final Items",
                    "Match ID",
                ])

                for row in rows:
                    item_names = self._history_item_names_from_ids(
                        row.get(
                            "item_ids",
                            [],
                        )
                    )
                    writer.writerow([
                        row.get(
                            "date",
                            "",
                        ),
                        (
                            "WIN"
                            if row.get(
                                "win"
                            )
                            is True
                            else "LOSS"
                            if row.get(
                                "win"
                            )
                            is False
                            else ""
                        ),
                        row.get(
                            "champion",
                            "",
                        ),
                        row.get(
                            "role",
                            "",
                        ),
                        row.get(
                            "kills",
                            0,
                        ),
                        row.get(
                            "deaths",
                            0,
                        ),
                        row.get(
                            "assists",
                            0,
                        ),
                        row.get(
                            "cs",
                            0,
                        ),
                        format_time(
                            row.get(
                                "duration_seconds",
                                0,
                            )
                        ),
                        ranked_queue_name(
                            row.get(
                                "queue_id",
                                0,
                            )
                        ),
                        " > ".join(
                            item_names
                        ),
                        row.get(
                            "match_id",
                            "",
                        ),
                    ])

            self.rs_info(
                "Export complete",
                (
                    f"Exported {len(rows)} ranked matches.\n\n"
                    f"{destination}"
                ),
            )
        except Exception as exc:
            self.rs_error(
                "Export failed",
                str(exc),
            )


    def _set_diagnostics_text(
        self,
        text,
    ):
        safe_text = redact_sensitive(
            text
        )
        self._diagnostics_last_text = safe_text

        widget = getattr(
            self,
            "diagnostics_text",
            None,
        )
        if widget is None:
            return

        try:
            widget.configure(
                state="normal"
            )
            widget.delete(
                "1.0",
                "end",
            )
            widget.insert(
                "1.0",
                safe_text,
            )
            widget.configure(
                state="disabled"
            )
        except Exception as exc:
            log_warning("Best-effort _set_diagnostics_text operation failed: " + str(exc))

    def collect_diagnostics_text(
        self,
    ):
        account_state = load_json(
            RIOT_ACCOUNT_PATH,
            {},
        )
        if not isinstance(
            account_state,
            dict,
        ):
            account_state = {}

        history_rows = load_riot_history_index()
        if not isinstance(
            history_rows,
            list,
        ):
            history_rows = []

        rank_rows = load_rank_progress()
        if not isinstance(
            rank_rows,
            list,
        ):
            rank_rows = []

        item_data = getattr(
            self.dd,
            "item_data",
            {},
        ) or {}
        champion_data = getattr(
            self.dd,
            "champion_data",
            {},
        ) or {}

        lcu_connected = bool(
            getattr(
                self.lcu,
                "port",
                None,
            )
            and getattr(
                self.lcu,
                "password",
                None,
            )
        )
        live_connected = bool(
            getattr(
                self,
                "live_api_ok",
                False,
            )
        )

        api_key_present = bool(
            str(
                self.history_api_key_var.get()
                if hasattr(
                    self,
                    "history_api_key_var",
                )
                else ""
            ).strip()
        )

        audit = getattr(
            self,
            "item_audit_report",
            None,
        )
        if isinstance(
            audit,
            dict,
        ):
            invalid_count = len(
                audit.get(
                    "invalid",
                    [],
                )
                or []
            )
            item_audit_text = (
                f"PASS • {audit.get('total', 0)} candidates"
                if audit.get(
                    "passed"
                )
                else (
                    f"FAIL • {invalid_count} invalid / "
                    f"{audit.get('total', 0)} candidates"
                )
            )
        else:
            item_audit_text = "Not run"

        sync_timestamp = (
            account_state.get(
                "last_sync_at"
            )
            or account_state.get(
                "rank_updated_at"
            )
            or "Never"
        )

        rank_source = str(
            account_state.get(
                "rank_source",
                "-",
            )
            or "-"
        )

        log_ready = bool(
            LOG_DIR.exists()
        )

        lines = [
            f"{APP_NAME} diagnostics",
            "=" * 54,
            f"Product version: {APP_VERSION_LABEL}",
            f"Internal build: {APP_VERSION}",
            f"OS: {platform.system()} {platform.release()} ({platform.machine() or '-'})",
            f"Python: {platform.python_version()}",
            f"Appearance: {SETTINGS.get('appearance', 'DARK')}",
            "",
            "LOCAL SERVICES",
            f"League Client / LCU: {'CONNECTED' if lcu_connected else 'WAITING'}",
            f"Live Client API: {'CONNECTED' if live_connected else 'WAITING'}",
            f"Local patch state: {getattr(self, 'patch_status_text', '-')}",
            "",
            "RIOT STATIC DATA",
            f"Data Dragon patch: {getattr(self.dd, 'version', None) or '-'}",
            f"Item data: {'OK' if item_data else 'MISSING'} • {len(item_data)} records",
            f"Champion data: {'OK' if champion_data else 'MISSING'} • {len(champion_data)} records",
            f"Rune data: {'OK' if getattr(self.dd, 'rune_name_to_id', None) else 'MISSING'}",
            "",
            "RIOT WEB API / RANKED SYNC",
            f"Session API key: {'PRESENT (not shown or logged)' if api_key_present else 'NOT ENTERED'}",
            f"Last Test API: {getattr(self, 'last_riot_api_diagnostic', 'Not tested')}",
            f"Last Verify & Sync: {getattr(self, 'last_verify_sync_result', 'Not run')}",
            f"Current sync status: {self.history_sync_status_var.get() if hasattr(self, 'history_sync_status_var') else '-'}",
            f"Last saved rank source: {rank_source}",
            f"Last successful rank/history timestamp: {sync_timestamp}",
            "",
            "LOCAL DATA",
            f"Ranked matches indexed: {len(history_rows)}",
            f"Rank progress snapshots: {len(rank_rows)}",
            f"Player Memory: {'PRESENT' if PLAYER_MEMORY_PATH.exists() else 'NOT BUILT'}",
            f"Logs: {'ENABLED' if log_ready else 'UNAVAILABLE'} • rotating riftsense.log",
            "",
            "DRAFT ASSISTANT",
            "Role pools: " + " • ".join(
                f"{draft_role_display(role)} {len(migrated_role_pool_map(SETTINGS).get(role, []))}"
                for role in DRAFT_ROLE_KEYS
            ),
            f"Champion Select refresh: {DRAFT_REFRESH_MS} ms while draft is active",
            "",
            "BUILD SAFETY",
            f"Recommendation item audit: {item_audit_text}",
            f"Current SR item catalogue ready: {'YES' if bool(item_data) else 'NO'}",
            "",
            "PRIVACY",
            "API keys are session-only and excluded from diagnostics/log output.",
            "Diagnostics intentionally omit Riot ID, PUUID and local Windows username.",
        ]

        return redact_sensitive(
            "\n".join(
                lines
            )
        )

    def refresh_diagnostics_panel(
        self,
    ):
        text = self.collect_diagnostics_text()
        self._set_diagnostics_text(
            text
        )
        if hasattr(
            self,
            "diagnostics_status_var",
        ):
            self.diagnostics_status_var.set(
                "Diagnostics refreshed • safe to copy/share • no API key included"
            )
        log_info(
            "Diagnostics refreshed"
        )
        return text

    def copy_diagnostics(
        self,
    ):
        text = (
            self._diagnostics_last_text
            or self.refresh_diagnostics_panel()
        )
        try:
            self.clipboard_clear()
            self.clipboard_append(
                redact_sensitive(
                    text
                )
            )
            self.update_idletasks()
            if hasattr(
                self,
                "diagnostics_status_var",
            ):
                self.diagnostics_status_var.set(
                    "Diagnostics copied to clipboard"
                )
        except Exception as exc:
            log_exception(
                "Copy diagnostics failed",
                exc,
            )
            self.rs_error(
                "Diagnostics",
                f"Could not copy diagnostics:\n{exc}",
            )

