    def run_pre_release_check(
        self,
    ):
        """
        Local pre-release gate.

        The one thing this cannot manufacture is a successful real Riot request
        from another PC. Verify & Sync remains the explicit live-machine gate.
        """
        failures = []
        warnings = []
        passes = []

        required_files = (
            PROFILES_PATH,
            TRAITS_PATH,
            DRAFT_PROFILES_PATH,
            DRAFT_LOADOUTS_PATH,
            RUNE_PROFILES_PATH,
            LOGO_PATH,
            ICON_PATH,
            APP_DIR / "tools" / "pre_push_audit.py",
            APP_DIR / "tools" / "pre_push_public_audit.py",
            APP_DIR / "tools" / "run_release_checks.py",
            APP_DIR / "README.md",
            APP_DIR / "LICENSE",
            APP_DIR / "SECURITY.md",
            APP_DIR / "CHANGELOG.md",
            APP_DIR / "PRE_RELEASE_CHECKLIST.md",
            APP_DIR / ".gitignore",
        )
        missing = [
            path.name
            for path in required_files
            if not path.exists()
        ]
        if missing:
            failures.append(
                "Missing release files: "
                + ", ".join(
                    missing
                )
            )
        else:
            passes.append(
                "Required source/assets present"
            )

        forbidden_runtime_entries = (
            APP_DIR / "settings.json",
            APP_DIR / "history",
            APP_DIR / "cache",
            APP_DIR / "logs",
            APP_DIR / "player_memory.json",
            APP_DIR / "performance_history.json",
            APP_DIR / "rank_progress.json",
        )
        leaked = [
            path.name
            for path in forbidden_runtime_entries
            if path.exists()
        ]
        if leaked:
            failures.append(
                "User/runtime data inside source tree: "
                + ", ".join(
                    leaked
                )
            )
        else:
            passes.append(
                "Source tree contains no local runtime data"
            )

        try:
            source_text = APP_DIR.joinpath(
                "RiftSense.py"
            ).read_text(
                encoding="utf-8"
            )
        except Exception:
            source_text = ""

        if re.search(
            r"RGAPI-[A-Za-z0-9_-]{20,}",
            source_text,
        ):
            failures.append(
                "Source contains a Riot API-key-shaped token"
            )
        else:
            passes.append(
                "No Riot API key detected in source"
            )

        if re.search(
            r"sk-[A-Za-z0-9_-]{20,}",
            source_text,
        ):
            failures.append(
                "Source contains an OpenAI-key-shaped token"
            )
        else:
            passes.append(
                "No OpenAI API key detected in source"
            )

        try:
            audit = self.run_recommendation_item_audit(
                silent=True
            )
        except Exception as exc:
            audit = {
                "passed": False,
                "error": str(
                    exc
                ),
            }

        if isinstance(
            audit,
            dict,
        ) and audit.get(
            "passed"
        ):
            passes.append(
                f"Recommendation item audit passed ({audit.get('total', 0)} candidates)"
            )
        else:
            invalid = len(
                (
                    audit
                    or {}
                ).get(
                    "invalid",
                    [],
                )
                or []
            )
            failures.append(
                (
                    f"Recommendation item audit failed ({invalid} invalid)"
                    if invalid
                    else "Recommendation item audit could not pass"
                )
            )

        verify_result = str(
            getattr(
                self,
                "last_verify_sync_result",
                "",
            )
            or ""
        )
        if verify_result.startswith(
            "VERIFY SYNC OK"
        ):
            passes.append(
                "Real-machine Verify & Sync passed this session"
            )
        else:
            warnings.append(
                "Real Riot Verify & Sync still needs to pass on the release machine"
            )

        if LOG_DIR.exists():
            passes.append(
                "Rotating runtime log directory is available"
            )
        else:
            failures.append(
                "Runtime log directory unavailable"
            )

        if failures:
            headline = "PRE-RELEASE CHECK • BLOCKED"
        elif warnings:
            headline = "PRE-RELEASE CHECK • LOCAL PASS / LIVE RIOT CHECK PENDING"
        else:
            headline = "PRE-RELEASE CHECK • PASS"

        lines = [
            headline,
            "",
            "PASS",
        ]
        lines.extend(
            f"✓ {item}"
            for item in passes
        )
        if warnings:
            lines.extend(
                [
                    "",
                    "PENDING",
                    *(
                        f"○ {item}"
                        for item in warnings
                    ),
                ]
            )
        if failures:
            lines.extend(
                [
                    "",
                    "BLOCKERS",
                    *(
                        f"✕ {item}"
                        for item in failures
                    ),
                ]
            )

        self.last_release_check = headline
        text = "\n".join(
            lines
        )
        self._set_diagnostics_text(
            text
            + "\n\n"
            + self.collect_diagnostics_text()
        )
        if hasattr(
            self,
            "diagnostics_status_var",
        ):
            self.diagnostics_status_var.set(
                headline
            )
        log_info(
            headline
        )
        return {
            "passed": not failures,
            "pending_live_riot": bool(
                warnings
            ),
            "failures": failures,
            "warnings": warnings,
            "passes": passes,
        }

    def _report_callback_exception(
        self,
        exc_type,
        exc_value,
        exc_traceback,
    ):
        trace_text = "".join(
            traceback.format_exception(
                exc_type,
                exc_value,
                exc_traceback,
            )
        )
        safe_trace = redact_sensitive(
            trace_text
        )

        try:
            LOGGER.error(
                "Tk callback crash\n%s",
                safe_trace,
            )
        except Exception as exc:
            log_warning("Best-effort _report_callback_exception operation failed: " + str(exc))

        try:
            self.show_crash_dialog(
                exc_value,
                safe_trace,
            )
        except Exception:
            try:
                messagebox.showerror(
                    APP_NAME,
                    (
                        "RiftSense encountered an unexpected error.\n\n"
                        f"{redact_sensitive(exc_value)}\n\n"
                        "Details were written to riftsense.log."
                    ),
                )
            except Exception as exc:
                log_warning("Best-effort _report_callback_exception operation failed: " + str(exc))

    def show_crash_dialog(
        self,
        exc_value,
        trace_text,
    ):
        window = tk.Toplevel(
            self
        )
        window.title(
            f"{APP_NAME} Error"
        )
        window.configure(
            bg=BG
        )
        window.transient(
            self
        )
        window.resizable(
            False,
            False,
        )

        shell = tk.Frame(
            window,
            bg=PANEL,
            highlightthickness=1,
            highlightbackground=BORDER,
        )
        shell.pack(
            fill="both",
            expand=True,
            padx=12,
            pady=12,
        )

        tk.Label(
            shell,
            text="RiftSense encountered an unexpected error",
            bg=PANEL,
            fg=DANGER,
            font=ui_font(11, "bold"),
            anchor="w",
        ).pack(
            fill="x",
            padx=16,
            pady=(16, 4),
        )
        tk.Label(
            shell,
            text=(
                f"{redact_sensitive(exc_value)}\n\n"
                "The full traceback was written to the rotating local log."
            ),
            bg=PANEL,
            fg=FG,
            font=ui_font(8),
            justify="left",
            anchor="w",
            wraplength=575,
        ).pack(
            fill="x",
            padx=16,
            pady=(0, 10),
        )

        actions = tk.Frame(
            shell,
            bg=PANEL,
        )
        actions.pack(
            fill="x",
            padx=16,
            pady=(0, 16),
        )

        def copy_error():
            try:
                self.clipboard_clear()
                self.clipboard_append(
                    redact_sensitive(
                        trace_text
                    )
                )
                self.update_idletasks()
            except Exception as exc:
                log_warning("Best-effort copy_error operation failed: " + str(exc))

        ttk.Button(
            actions,
            text="Copy Error",
            style="Ghost.TButton",
            command=copy_error,
        ).pack(
            side="left",
        )
        ttk.Button(
            actions,
            text="Open Logs",
            style="Ghost.TButton",
            command=self.open_log_folder,
        ).pack(
            side="left",
            padx=(7, 0),
        )
        ttk.Button(
            actions,
            text="Close",
            style="Primary.TButton",
            command=window.destroy,
        ).pack(
            side="right",
        )

        self._center_toplevel(
            window,
            640,
            260,
        )
        window.grab_set()
        window.focus_force()

