    def set_enemy_duel_visual(
        self,
        widgets,
        duel,
    ):
        """
        Color the whole enemy cell from YOUR active-player perspective.

        Green  = you look stronger on visible data.
        Red    = enemy looks stronger.
        Neutral= close / insufficient edge.
        """
        bg = duel.get(
            "bg",
            PANEL_ALT,
        )
        fg = duel.get(
            "color",
            MUTED,
        )
        label = duel.get(
            "label",
            "WAITING",
        )

        enemy = widgets.get(
            "enemy"
        )
        enemy_text = widgets.get(
            "enemy_text"
        )
        enemy_topline = widgets.get(
            "enemy_topline"
        )
        enemy_bottomline = widgets.get(
            "enemy_bottomline"
        )
        enemy_icon = widgets.get(
            "enemy_icon"
        )

        if enemy is not None:
            enemy.configure(
                bg=bg,
                highlightbackground=fg,
            )
        if enemy_text is not None:
            enemy_text.configure(
                bg=bg
            )
        if enemy_topline is not None:
            enemy_topline.configure(
                bg=bg
            )
        if enemy_bottomline is not None:
            enemy_bottomline.configure(
                bg=bg
            )
        if enemy_icon is not None:
            enemy_icon.configure(
                bg=bg
            )

        for key in (
            "enemy_name_label",
            "enemy_gold_label",
            "enemy_meta_label",
            "duel_label",
        ):
            label_widget = widgets.get(
                key
            )
            if label_widget is not None:
                label_widget.configure(
                    bg=bg
                )

        # Keep normal data hierarchy while making the duel state unmistakable.
        if widgets.get(
            "enemy_name_label"
        ) is not None:
            widgets[
                "enemy_name_label"
            ].configure(
                fg=FG
            )
        if widgets.get(
            "enemy_gold_label"
        ) is not None:
            widgets[
                "enemy_gold_label"
            ].configure(
                fg=fg
            )
        if widgets.get(
            "enemy_meta_label"
        ) is not None:
            widgets[
                "enemy_meta_label"
            ].configure(
                fg=(
                    FG
                    if label
                    != "WAITING"
                    else MUTED
                )
            )
        if widgets.get(
            "duel_label"
        ) is not None:
            widgets[
                "duel_label"
            ].configure(
                fg=fg
            )

        widgets[
            "duel_var"
        ].set(
            (
                f"1V1: {label}"
                if label
                else "1V1: -"
            )
        )

        reason = str(
            duel.get(
                "reason",
                "",
            )
            or ""
        )
        score = duel.get(
            "score",
            0.0,
        )
        widgets[
            "enemy_tooltip_var"
        ].set(
            (
                f"{reason}\n"
                f"Duel score: {score:+.2f}\n\n"
                "GREEN = you look stronger on visible data.\n"
                "RED = enemy looks stronger.\n"
                "CLOSE = no clear edge.\n\n"
                "This is not a guaranteed 1v1 result: cooldowns, current HP, "
                "summoner spells, nearby players, terrain and champion-specific "
                "outplay mechanics can change the fight."
            )
        )

    def reset_enemy_duel_visual(
        self,
        widgets,
    ):
        self.set_enemy_duel_visual(
            widgets,
            {
                "label": "WAITING",
                "color": MUTED,
                "bg": PANEL_ALT,
                "score": 0.0,
                "reason": (
                    "Waiting for live player data."
                ),
            },
        )

    def set_live_overview_waiting_layout(
        self,
        waiting,
    ):
        """
        Waiting/offline mode should look intentional, not like an empty live
        scoreboard. Dense live-only sections are restored in one deterministic
        pack order when valid player data returns.
        """
        self.live_overview_waiting = bool(
            waiting
        )

        frames = (
            getattr(
                self,
                "right_live_summary",
                None,
            ),
            getattr(
                self,
                "team_summary_frame",
                None,
            ),
            getattr(
                self,
                "gank_priority_panel",
                None,
            ),
            getattr(
                self,
                "events_panel",
                None,
            ),
            getattr(
                self,
                "lane_compare_frame",
                None,
            ),
        )

        for frame in frames:
            if frame is not None:
                try:
                    frame.pack_forget()
                except Exception as exc:
                    log_warning("Best-effort set_live_overview_waiting_layout operation failed: " + str(exc))

        if waiting:
            return

        if (
            hasattr(
                self,
                "right_live_summary",
            )
            and SETTINGS.get(
                "show_strategy_summary",
                True,
            )
            and not getattr(
                self,
                "high_dpi_dense",
                False,
            )
        ):
            self.right_live_summary.pack(
                fill="x",
                padx=6,
                pady=(4, 2),
            )

        if hasattr(
            self,
            "team_summary_frame",
        ):
            self.team_summary_frame.pack(
                fill="x",
                padx=6,
                pady=(2, 2),
            )

        if hasattr(
            self,
            "gank_priority_panel",
        ):
            self.gank_priority_panel.pack(
                fill="x",
                padx=6,
                pady=(2, 2),
            )

        if (
            hasattr(
                self,
                "events_panel",
            )
            and SETTINGS.get(
                "show_objective_readiness",
                True,
            )
        ):
            self.events_panel.pack(
                fill="x",
                padx=6,
                pady=(2, 3),
            )

        if hasattr(
            self,
            "lane_compare_frame",
        ):
            self.lane_compare_frame.pack(
                fill="both",
                expand=True,
                padx=6,
                pady=(2, 2),
            )


