    def _comparison_color(self,diff):
        if diff>0: return GOOD,POS_BG
        if diff<0: return DANGER,NEG_BG
        return MUTED,TIE_BG

    def update_player_side(self, widgets, player, ours=True):
        champion=player.get("championName","?") if player else "?"
        gold=visible_inventory_gold(player or {},self.dd)
        kills,deaths,assists,cs=score_line(player or {})
        level=(player or {}).get("level","?")
        prefix="our" if ours else "enemy"
        widgets[f"{prefix}_name"].set(champion)
        widgets[f"{prefix}_gold"].set(f"{gold:,}g items")
        widgets[f"{prefix}_meta"].set(
            f"Lv {level} • {kills}/{deaths}/{assists} • {cs} CS"
        )
        icon=widgets[f"{prefix}_icon"]
        path=self.dd.champion_icon_path(champion) if player else None
        lane_icon_px = max(
            30,
            min(
                38,
                int(
                    SETTINGS.get(
                        "champion_icon_px",
                        28,
                    )
                    or 28
                )
                + 4,
            ),
        )
        photo = (
            self.load_photo(
                path,
                target_px=lane_icon_px,
            )
            if path
            else None
        )
        if photo:
            icon.configure(
                image=photo,
                text="",
                width=0,
                height=0,
            )
            icon._champion_photo = photo
        else:
            icon.configure(
                image="",
                text="?",
                width=4,
                height=2,
            )
            icon._champion_photo = None

    def draw_lane_sparkline(self, canvas, history):
        canvas.delete("all")
        values=[diff for _t,diff in history[-120:]]
        if len(values)<2:
            return
        canvas.update_idletasks()
        width=max(60,canvas.winfo_width()); height=max(14,canvas.winfo_height())
        lo=min(values); hi=max(values)
        if hi==lo: hi=lo+1
        zero_y=height-(0-lo)/(hi-lo)*height if lo<=0<=hi else None
        if zero_y is not None:
            canvas.create_line(0,zero_y,width,zero_y,fill=BORDER)
        pts=[]
        for i,value in enumerate(values):
            x=i*width/max(1,len(values)-1); y=height-(value-lo)/(hi-lo)*height
            pts.extend((x,y))
        color=GOOD if values[-1]>=0 else DANGER
        canvas.create_line(*pts,fill=color,width=2,smooth=True)

    def render_gank_priority(self, our_map, enemy_map, game_time_seconds):
        ranked = rank_gank_lanes(
            our_map,
            enemy_map,
            self.dd,
            self.lane_progress_history,
            float(game_time_seconds),
            carry_lane=getattr(self, "current_ally_carry_lane", None),
            jungler_champion=getattr(self, "current_player_champion", ""),
            strategy=getattr(self, "current_strategy_mode", "STABLE"),
        )
        self.current_gank_ranking = ranked
        if not ranked:
            return

        best = ranked[0]
        best_label = gank_opportunity_label(best)
        phase = game_phase(game_time_seconds)
        profile = JUNGLE_GANK_PROFILES.get(
            getattr(self, "current_player_champion", ""),
            {},
        )
        profile_note = profile.get(
            "identity",
            "general lane-state model",
        )

        self.gank_priority_status_var.set(
            f"{getattr(self, 'current_player_champion', 'Jungler')} • "
            f"{profile_note}"
        )

        rank_by_lane = {
            item["lane"]: (rank, item)
            for rank, item in enumerate(ranked, start=1)
        }

        for lane, widgets in self.gank_card_widgets.items():
            rank, item = rank_by_lane[lane]
            snapshot = item["snapshot"]
            label = gank_opportunity_label(item)

            if rank == 1:
                fg, bg = GOOD, POS_BG
            elif rank == 2:
                fg, bg = ACCENT, ORANGE_BG
            else:
                fg, bg = DANGER, NEG_BG

            card = widgets["card"]
            card.configure(
                bg=bg,
                highlightbackground=fg,
            )
            for child in card.winfo_children():
                try:
                    child.configure(bg=bg)
                except Exception as exc:
                    log_warning("Best-effort render_gank_priority operation failed: " + str(exc))

            widgets["title"].configure(fg=fg, bg=bg)
            widgets["score"].configure(bg=bg)
            widgets["metrics"].configure(bg=bg)
            widgets["reason"].configure(bg=bg)
            widgets["warning"].configure(bg=bg)
            widgets["canvas"].configure(bg=bg)

            widgets["vars"]["title"].set(
                f"#{rank} {lane} — {label}"
            )
            widgets["vars"]["score"].set(
                f"{item['score']:.1f}/10 • Risk {item['risk']}"
            )
            widgets["vars"]["metrics"].set(
                f"Δ {signed_gold(snapshot['gold_diff'])} | "
                f"{item['momentum_label']} {signed_gold(item['trend'])} | "
                f"Lv {snapshot['level_diff']:+.1f} | CS {snapshot['cs_diff']:+d}"
            )
            widgets["vars"]["reason"].set(
                " • ".join(
                    reason.capitalize()
                    for reason in item["reasons"][:2]
                )
            )
            widgets["vars"]["warning"].set(
                ("Risk: " + item["warnings"][0].capitalize())
                if item["warnings"]
                else ""
            )
            widgets["vars"]["tooltip"].set(
                f"{lane} Gank Priority\\n"
                f"Score: {item['score']:.1f}/10 • Risk: {item['risk']}\\n"
                f"Momentum: {item['momentum_label']} ({signed_gold(item['trend'])} over recent history)\\n"
                f"Strategy mode: {self.current_strategy_mode}\\n"
                f"Jungler: {getattr(self, 'current_player_champion', '-') }\\n"
                f"Reasons: {'; '.join(item['reasons'])}\\n"
                f"Warnings: {'; '.join(item['warnings']) if item['warnings'] else 'none'}\\n\\n"
                "The app cannot see exact wave position, wards, hidden enemy-jungle location or full HP/mana state."
            )

            previous_rank = self.last_gank_ranks.get(lane)
            self.last_gank_ranks[lane] = rank
            if previous_rank is not None and previous_rank != rank:
                self.flash_label(
                    widgets["title"],
                    FG,
                    restore_color=fg,
                    duration=650,
                )

            self.draw_lane_sparkline(
                widgets["canvas"],
                self.lane_progress_history.get(lane, []),
            )


    def render_team_comparison(
        self,
        active_player,
        all_players,
        game_time_seconds=0.0,
    ):
        self.ensure_right_widgets()
        self.set_live_overview_waiting_layout(
            False
        )
        self.set_live_state_banner(
            "ok",
            "LIVE INTELLIGENCE ACTIVE",
            "Live Client data is flowing.",
            visible=False,
        )

        my_team = active_player.get("team")
        our_players = [
            player for player in all_players
            if player.get("team") == my_team
        ]
        enemy_players = [
            player for player in all_players
            if player.get("team") != my_team
        ]

        our_map = lane_player_map(our_players)
        enemy_map = lane_player_map(enemy_players)

        # New match / Practice Tool reset.
        if game_time_seconds + 3 < self.last_game_time_seen:
            self.lane_progress_history = {
                "TOP": [],
                "MID": [],
                "BOT": [],
            }
            self.team_gold_history = []
            self.last_strategy_values = {}
            self.last_gank_ranks = {}
            self.last_lane_diffs = {}
            self.last_objective_scores = {}

        self.last_game_time_seen = game_time_seconds

        # Keep 5 minutes of lane momentum history.
        for lane in ("TOP", "MID", "BOT"):
            snap = gank_lane_snapshot(
                lane,
                our_map,
                enemy_map,
                self.dd,
            )
            hist = self.lane_progress_history.setdefault(
                lane,
                [],
            )
            if (
                not hist
                or game_time_seconds - hist[-1][0] >= 2.0
            ):
                hist.append(
                    (
                        float(game_time_seconds),
                        int(snap["gold_diff"]),
                    )
                )
            cutoff = float(game_time_seconds) - 300.0
            hist[:] = [
                sample for sample in hist
                if sample[0] >= cutoff
            ][-150:]

        our_total = sum(
            visible_inventory_gold(player, self.dd)
            for player in our_players
        )
        enemy_total = sum(
            visible_inventory_gold(player, self.dd)
            for player in enemy_players
        )
        total_diff = our_total - enemy_total

        # Whole-game team trend history.
        if (
            not self.team_gold_history
            or game_time_seconds - self.team_gold_history[-1][0] >= 2.0
        ):
            self.team_gold_history.append(
                (
                    float(game_time_seconds),
                    int(total_diff),
                )
            )
        # Entire match, with a practical memory cap.
        self.team_gold_history = self.team_gold_history[-1800:]
        team_momentum = history_delta(
            self.team_gold_history,
            game_time_seconds,
            lookback=120.0,
        )
        team_momentum_label = momentum_descriptor(
            team_momentum
        )

        self.current_strategy_mode = strategy_mode(
            total_diff,
            team_momentum,
        )

        # Confidence is data completeness/stability, NOT win chance.
        confidence_score, confidence_label, confidence_reason = (
            game_state_confidence(
                our_map,
                enemy_map,
                all_players,
                self.lane_progress_history,
            )
        )
        self.current_state_confidence = (
            confidence_score,
            confidence_label,
            confidence_reason,
        )

        # Key-player rankings.
        ally_rank = (
            getattr(self, "current_ally_carry_ranking", [])
            or rank_live_players(our_players, self.dd)
        )
        enemy_rank = (
            getattr(self, "current_enemy_threat_ranking", [])
            or rank_live_players(enemy_players, self.dd)
        )

        self.ally_carry_var.set(
            "ALLY CARRIES: "
            + (
                "  •  ".join(
                    f"#{index + 1} {entry['champion']} {entry['item_gold']:,}g"
                    for index, entry in enumerate(ally_rank[:3])
                )
                if ally_rank
                else "-"
            )
        )

        self.enemy_rank_var.set(
            "ENEMY THREATS: "
            + (
                "  •  ".join(
                    f"#{index + 1} {entry['champion']} "
                    f"[{entry.get('threat_type', 'GENERAL')}] "
                    f"{entry['item_gold']:,}g"
                    for index, entry in enumerate(enemy_rank[:3])
                )
                if enemy_rank
                else "-"
            )
        )

        # Objective score 0–100 + component breakdown.
        self.current_objective_readiness = (
            objective_fight_readiness(
                our_map,
                enemy_map,
                self.dd,
                game_time_seconds,
            )
        )
        ready = self.current_objective_readiness

        self.dragon_ready_var.set(
            f"DRAGON {ready['dragon_score']}/100 • {ready['dragon']}"
        )
        self.baron_ready_var.set(
            f"BARON {ready['baron_score']}/100 • {ready['baron']}"
        )
        self.dragon_ready_label.configure(
            fg=ready["dragon_color"]
        )
        self.baron_ready_label.configure(
            fg=ready["baron_color"]
        )
        self.dragon_tooltip_var.set(
            self.objective_tooltip_text(
                "Dragon",
                ready["dragon_score"],
                ready["dragon"],
                ready["dragon_breakdown"],
            )
        )
        self.baron_tooltip_var.set(
            self.objective_tooltip_text(
                "Baron",
                ready["baron_score"],
                ready["baron"],
                ready["baron_breakdown"],
            )
        )

        self.flash_numeric_change(
            "dragon_score",
            ready["dragon_score"],
            self.dragon_ready_label,
            ready["dragon_color"],
        )
        self.flash_numeric_change(
            "baron_score",
            ready["baron_score"],
            self.baron_ready_label,
            ready["baron_color"],
        )

        # Team summary visual.
        fg, bg = self._comparison_color(total_diff)
        self.team_summary_box.configure(
            bg=bg,
            highlightbackground=fg,
        )
        for child in self.team_summary_box.winfo_children():
            try:
                child.configure(bg=bg)
                for sub in child.winfo_children():
                    sub.configure(bg=bg)
            except Exception as exc:
                log_warning("Best-effort render_team_comparison operation failed: " + str(exc))

        self.team_delta_label.configure(
            fg=fg,
            bg=bg,
        )
        self.our_total_var.set(
            f"{our_total:,}g visible items"
        )
        self.enemy_total_var.set(
            f"{enemy_total:,}g visible items"
        )
        self.team_delta_var.set(
            signed_gold(total_diff)
        )
        self.flash_numeric_change(
            "team_delta",
            total_diff,
            self.team_delta_label,
            fg,
        )

        self.team_compare_status_var.set(
            f"Momentum {team_momentum_label} "
            f"{signed_gold(team_momentum)} / ~2 min"
        )

        # Gank logic now receives strategy mode + current jungler profile.
        self.render_gank_priority(
            our_map,
            enemy_map,
            game_time_seconds,
        )

        phase = game_phase(game_time_seconds)
        state_text, state_color = game_state_label(
            total_diff
        )

        gank_rank = getattr(
            self,
            "current_gank_ranking",
            [],
        )
        best_gank = (
            gank_rank[0]["lane"]
            if gank_rank
            else "-"
        )

        lane_diffs = {
            "TOP": (
                visible_inventory_gold(
                    our_map.get("TOP") or {},
                    self.dd,
                )
                - visible_inventory_gold(
                    enemy_map.get("TOP") or {},
                    self.dd,
                )
            ),
            "MID": (
                visible_inventory_gold(
                    our_map.get("MIDDLE") or {},
                    self.dd,
                )
                - visible_inventory_gold(
                    enemy_map.get("MIDDLE") or {},
                    self.dd,
                )
            ),
            "BOT": (
                visible_inventory_gold(
                    our_map.get("BOTTOM") or {},
                    self.dd,
                )
                + visible_inventory_gold(
                    our_map.get("UTILITY") or {},
                    self.dd,
                )
                - visible_inventory_gold(
                    enemy_map.get("BOTTOM") or {},
                    self.dd,
                )
                - visible_inventory_gold(
                    enemy_map.get("UTILITY") or {},
                    self.dd,
                )
            ),
        }

        strong_side = max(
            lane_diffs,
            key=lane_diffs.get,
        )
        enemy_threat = (
            enemy_rank[0]["champion"]
            if enemy_rank
            else "-"
        )
        enemy_threat_type = (
            enemy_rank[0].get(
                "threat_type",
                "GENERAL",
            )
            if enemy_rank
            else "-"
        )

        self.game_state_var.set(
            f"GAME STATE: {state_text} • {self.current_strategy_mode} MODE • "
            f"CONFIDENCE {confidence_label} {confidence_score}%"
        )
        self.game_state_label.configure(
            fg=state_color
        )

        self.game_state_detail_var.set(
            f"Phase: {phase} | Team momentum: {team_momentum_label} "
            f"{signed_gold(team_momentum)} | Strong side: {strong_side} "
            f"({signed_gold(lane_diffs[strong_side])}) | "
            f"Enemy threat: {enemy_threat} [{enemy_threat_type}] | "
            f"Best lane: {best_gank}"
        )

        self.game_state_tooltip_var.set(
            f"Game State confidence: {confidence_label} {confidence_score}%\\n"
            f"{confidence_reason}\\n\\n"
            f"Strategy mode: {self.current_strategy_mode}\\n"
            f"Team item delta: {signed_gold(total_diff)}\\n"
            f"~2 minute momentum: {signed_gold(team_momentum)} ({team_momentum_label})\\n\\n"
            "Confidence measures live-data completeness/stability. "
            "It is not a win-probability estimate."
        )

        if hasattr(self, "card_game_state"):
            self.card_game_state["value"].set(
                state_text
            )
            self.card_game_state["detail"].set(
                f"{self.current_strategy_mode} • "
                f"Confidence {confidence_label} {confidence_score}%"
            )
            self.card_game_state["value_label"].configure(
                fg=state_color
            )

            self.card_phase["value"].set(
                phase
            )
            self.card_phase["detail"].set(
                (
                    "Lane pressure"
                    if phase == "EARLY"
                    else "Objective setup"
                    if phase == "MID"
                    else "Grouped fights"
                )
            )

            if enemy_rank:
                top_enemy = enemy_rank[0]
                self.card_enemy_threat["value"].set(
                    top_enemy["champion"]
                )
                self.card_enemy_threat["detail"].set(
                    f"{top_enemy.get('threat_type', 'GENERAL')}"
                )
                self.enemy_threat_tooltip_var.set(
                    f"#{1} {top_enemy['champion']} — {top_enemy.get('threat_type', 'GENERAL')}\\n"
                    f"Visible item value: {top_enemy['item_gold']:,}g\\n"
                    f"Power heuristic: {top_enemy['power']:.2f}\\n\\n"
                    "Threat ranking uses visible items, K/D/A, level and CS."
                )

            if ally_rank:
                top_ally = ally_rank[0]
                self.card_ally_carry["value"].set(
                    top_ally["champion"]
                )
                self.card_ally_carry["detail"].set(
                    f"{position_to_gank_lane(top_ally.get('position')) or top_ally.get('position') or '-'} "
                    "• strongest ally"
                )
                self.ally_carry_tooltip_var.set(
                    f"#{1} ally carry: {top_ally['champion']}\\n"
                    f"Visible item value: {top_ally['item_gold']:,}g\\n"
                    f"Power heuristic: {top_ally['power']:.2f}\\n\\n"
                    "The strongest ally's side gets a small Gank Priority bonus."
                )

        self.phase_tooltip_var.set(
            f"{phase} game.\\n"
            f"Team momentum: {team_momentum_label} ({signed_gold(team_momentum)} over ~2 min).\\n"
            "EARLY <14:00 • MID 14:00–27:59 • LATE 28:00+."
        )

        # What Changed — compact event-driven summary.
        self.track_strategy_changes([
            (
                "state",
                "State",
                state_text,
                f"team visible-item delta is {signed_gold(total_diff)}",
            ),
            (
                "mode",
                "Mode",
                self.current_strategy_mode,
                f"team momentum is {team_momentum_label}",
            ),
            (
                "threat",
                "Threat",
                enemy_threat,
                f"ranking now identifies {enemy_threat_type}",
            ),
            (
                "gank",
                "Best gank",
                best_gank,
                "lane score / momentum / risk changed",
            ),
            (
                "strong_side",
                "Strong side",
                strong_side,
                "relative lane power changed",
            ),
        ])

        # Five-role strong/neutral/weak state.
        for position, lane_label in LANE_ORDER:
            widgets = self.right_lane_widgets[position]
            ours = our_map.get(position)
            enemy = enemy_map.get(position)

            self.update_player_side(
                widgets,
                ours,
                True,
            )
            self.update_player_side(
                widgets,
                enemy,
                False,
            )

            lane_diff = (
                visible_inventory_gold(
                    ours or {},
                    self.dd,
                )
                - visible_inventory_gold(
                    enemy or {},
                    self.dd,
                )
            )

            if position == "TOP":
                lane_name = "TOP"
            elif position == "MIDDLE":
                lane_name = "MID"
            elif position in {"BOTTOM", "UTILITY"}:
                lane_name = "BOT"
            else:
                lane_name = None

            trend = (
                lane_trend_from_history(
                    self.lane_progress_history.get(
                        lane_name,
                        [],
                    ),
                    lane_diff,
                    game_time_seconds,
                    lookback=90.0,
                )
                if lane_name
                else 0
            )
            strength, strength_color, strength_score = (
                role_strength_label(
                    ours,
                    enemy,
                    self.dd,
                    trend,
                )
            )

            # Separate from lane power: compare the active player directly with
            # this enemy to give a quick "can I 1v1 them?" visible-data signal.
            duel = duel_matchup_state(
                active_player,
                enemy,
                self.dd,
            )
            self.set_enemy_duel_visual(
                widgets,
                duel,
            )

            lane_fg, lane_bg = (
                (GOOD, POS_BG)
                if strength == "STRONG"
                else (DANGER, NEG_BG)
                if strength == "WEAK"
                else (ACCENT, TIE_BG)
            )

            widgets["center"].configure(
                bg=lane_bg,
                highlightbackground=lane_fg,
            )
            widgets["diff_label"].configure(
                bg=lane_bg,
                fg=lane_fg,
            )
            widgets["status_label"].configure(
                bg=lane_bg,
                fg=strength_color,
            )
            for child in widgets["center"].winfo_children():
                try:
                    child.configure(bg=lane_bg)
                except Exception as exc:
                    log_warning("Best-effort render_team_comparison operation failed: " + str(exc))

            widgets["diff_var"].set(
                signed_gold(lane_diff)
            )
            momentum_text = (
                momentum_descriptor(trend)
                if lane_name
                else "ROLE STATE"
            )
            widgets["status_var"].set(
                f"{strength} "
                + (
                    "↑" if trend >= 350
                    else "↓" if trend <= -350
                    else ""
                )
            )
            widgets["tooltip_var"].set(
                f"{lane_label} power: {strength}\\n"
                f"Visible item delta: {signed_gold(lane_diff)}\\n"
                f"Recent momentum: {momentum_text} ({signed_gold(trend)})\\n"
                f"Composite lane-power score: {strength_score:+.2f}\\n\\n"
                "Power state combines visible item value, level, CS and recent momentum."
            )

            self.flash_numeric_change(
                f"lane_{position}",
                lane_diff,
                widgets["diff_label"],
                lane_fg,
            )

        self.game_history_tooltip_var.set(
            f"Game State History\\n"
            f"Current team visible-item delta: {signed_gold(total_diff)}\\n"
            f"~2 minute momentum: {signed_gold(team_momentum)} ({team_momentum_label})\\n"
            f"Samples stored this game: {len(self.team_gold_history)}"
        )
        self.draw_game_state_history()


    def render_current_items(self, player_items):
        signature = tuple(str(x.get("itemID")) for x in player_items if x.get("itemID"))
        if signature == self.current_item_signature:
            return
        self.current_item_signature = signature
        self.clear_frame(self.current_icons)

        shown = 0
        for item in player_items:
            item_id = item.get("itemID")
            if not item_id:
                continue
            name = item.get("displayName") or self.dd.item_name(item_id)
            if normalize_name(name) in {
                "warding totem (trinket)",
                "oracle lens",
                "farsight alteration",
            }:
                continue
            self.add_item_icon(self.current_icons, item_id, name)
            shown += 1

        if shown == 0:
            ttk.Label(
                self.current_icons,
                text="No items to display.",
                style="Muted.Panel.TLabel",
            ).pack(side="left")

    def render_adaptive_options(
        self,
        champion,
        player_items,
        enemies,
        allies=None,
    ):
        options, metrics, per_enemy, identity = adaptive_item_options(
            champion,
            player_items,
            enemies,
            self.dd,
            allies=allies,
            strategy_mode=getattr(
                self,
                "current_strategy_mode",
                "STABLE",
            ),
        )
        options = primary_threat_adjusted_options(
            options,
            per_enemy,
            getattr(self, "current_enemy_threat_ranking", []),
        )
        options = add_option_confidence(options)

        inventory_signature = tuple(
            (
                enemy.get("championName", "?"),
                tuple(
                    sorted(
                        str(item.get("itemID"))
                        for item in (enemy.get("items") or [])
                        if item.get("itemID")
                    )
                ),
            )
            for enemy in enemies
        )
        owned_signature = tuple(
            sorted(
                str(item.get("itemID"))
                for item in (player_items or [])
                if item.get("itemID")
            )
        )
        option_signature = tuple(
            (x["name"], x["score"], x.get("confidence"), tuple(x["reasons"]))
            for x in options
        )
        signature = (
            champion,
            identity.get(
                "mode",
                "PROFILE",
            ),
            identity.get(
                "frontline",
                0,
            ),
            inventory_signature,
            owned_signature,
            option_signature,
            self.dd.version,
        )

        mode = identity.get(
            "mode",
            "PROFILE",
        )
        identity_suffix = (
            f" • ROLE {mode}"
            if mode
            in {
                "ASSASSIN",
                "BRUISER",
            }
            else ""
        )
        self.threat_summary_var.set(
            threat_summary_text(
                metrics
            )
            + identity_suffix
        )
        self.build_response_var.set(
            build_response_text(
                metrics
            )
        )
        self.current_build_identity = identity

        if signature == self.adaptive_signature:
            return options, metrics, per_enemy, identity

        self.adaptive_signature = signature
        self.enemy_inventory_signature = inventory_signature
        self.clear_frame(self.adaptive_options_frame)

        if not options:
            ttk.Label(
                self.adaptive_options_frame,
                text=(
                    "No adaptive item choices are available for this champion profile yet. "
                    "The normal build path below still works."
                ),
                style="Muted.Panel.TLabel",
                wraplength=950,
            ).pack(anchor="w", pady=4)
            return options, metrics, per_enemy, identity

        for rank, option in enumerate(options, start=1):
            card = ttk.Frame(self.adaptive_options_frame, style="Panel.TFrame")
            card.pack(side="left", fill="both", expand=True, padx=(0 if rank == 1 else 6, 0))

            top = ttk.Frame(card, style="Panel.TFrame")
            top.pack(fill="x")

            path = self.current_item_icon_path(option["item_id"])
            photo = self.load_photo(path, target_px=40)
            if photo:
                icon = ttk.Label(top, image=photo, style="Panel.TLabel")
            else:
                icon = ttk.Label(top, text="?", style="Panel.TLabel", width=6)
            icon.pack(side="left", padx=(0, 5))
            Tooltip(icon, option["name"])

            title_box = ttk.Frame(top, style="Panel.TFrame")
            title_box.pack(side="left", fill="x", expand=True)

            ttk.Label(
                title_box,
                text=f"Option {rank}: {option['name']}",
                style="Good.Panel.TLabel" if rank == 1 else "Accent.Panel.TLabel",
                wraplength=220,
                justify="left",
            ).pack(anchor="w")

            confidence_label = ttk.Label(
                title_box,
                text=(f"Fit: {option['score']:.1f}/10  •  "
                      f"Confidence: {option.get('confidence', 50)}%"),
                style="Panel.TLabel",
            )
            confidence_label.pack(anchor="w", pady=(2, 0))
            Tooltip(
                confidence_label,
                (
                    f"RiftSense recommendation for {option['name']}.\n"
                    f"Final fit: {option['score']:.1f}/10\n"
                    f"Confidence: {option.get('confidence', 50)}%\n\n"
                    f"Meta consensus: {float(option.get('meta_fit', 0.5)) * 10:.1f}/10  • 35%\n"
                    f"Team role / composition: {float(option.get('role_fit', 0.5)) * 10:.1f}/10  • 25%\n"
                    f"Enemy matchup / threats: {float(option.get('threat_fit', 0.5)) * 10:.1f}/10  • 20%\n"
                    f"Your saved history: {float(option.get('personal_fit', 0.5)) * 10:.1f}/10  • 15%\n"
                    f"Current live state: {float(option.get('live_fit', 0.5)) * 10:.1f}/10  • 5%\n\n"
                    f"Reasons: {'; '.join(option.get('reasons') or [])}\n\n"
                    "Confidence and fit are heuristics, not win-rate probabilities. "
                    "Personal-history signals are descriptive and are deliberately shrunk toward neutral."
                ),
            )

            visible_reasons = [
                reason
                for reason in option["reasons"]
                if not normalize_name(
                    reason
                ).startswith(
                    "answers primary threat"
                )
            ]
            if not visible_reasons:
                visible_reasons = list(
                    option["reasons"][:1]
                )
            reason_text = " • ".join(
                reason.capitalize()
                for reason in visible_reasons[:2]
            )
            ttk.Label(
                card,
                text=reason_text,
                style="Muted.Panel.TLabel",
                wraplength=220,
                justify="left",
            ).pack(anchor="w", pady=(2, 0))

        return options, metrics, per_enemy, identity

    def render_adaptive_full_build(
        self,
        champion,
        player_items,
        enemies,
        adaptive_options,
        allies=None,
    ):
        profile = PROFILES.get(champion)
        if not profile:
            self.full_build_status_var.set(
                f"No full-build profile is available for {champion}."
            )
            self.clear_frame(self.full_build_icons_frame)
            self.current_full_build = []
            return []

        result = adaptive_full_build(
            champion,
            profile,
            player_items,
            enemies,
            adaptive_options,
            self.dd,
            allies=allies,
        )
        items = result["items"]
        comp = result["comp"]
        self.update_meta_status_ui(
            champion,
            role=getattr(
                self,
                "current_player_role",
                "",
            ),
        )

        new_names = [x.get("name") for x in items]
        old_names = list(self.previous_full_build_names)
        self.full_build_new_names = set()
        if old_names and old_names != new_names:
            self.record_build_change(old_names, new_names, adaptive_options)
        self.previous_full_build_names = list(new_names)

        signature = (
            champion,
            tuple(
                (x["name"], x["source"], x.get("item_id"))
                for x in items
            ),
            self.dd.version,
        )

        boots_item = next(
            (item for item in items if is_boot_item_name(item.get("name", ""))),
            None,
        )
        boots_note = (
            f"Boots: {boots_item['name']} ({boots_item['source']})"
            if boots_item
            else "Boots: -"
        )
        identity = result.get(
            "identity",
            {},
        )
        self.full_build_status_var.set(
            f"{result['baseline_title']} • "
            f"{comp['AP']} AP / {comp['AD']} AD • CC {comp['CC']} • "
            f"{boots_note}"
        )

        primary_option = adaptive_options[0] if adaptive_options else None
        primary_threat = (
            self.current_enemy_threat_ranking[0]["champion"]
            if getattr(self, "current_enemy_threat_ranking", [])
            else "-"
        )
        if primary_option:
            self.game_state_build_var.set(
                f"Build adaptation: {primary_option['name']} "
                f"({primary_option.get('confidence', 50)}% heuristic confidence) "
                f"• primary enemy threat: {primary_threat}"
            )
        else:
            self.game_state_build_var.set(
                f"Build adaptation: baseline • primary enemy threat: {primary_threat}"
            )
        self.current_full_build = items

        if signature == self.full_build_signature:
            return items

        self.full_build_signature = signature
        self.clear_frame(self.full_build_icons_frame)
        self.full_build_new_label_vars = []
        self.full_build_new_holders = []

        if not items:
            ttk.Label(
                self.full_build_icons_frame,
                text="No full build could be generated for this profile.",
                style="Muted.Panel.TLabel",
            ).pack(anchor="w")
            return items

        self.full_build_icons_frame.grid_rowconfigure(
            0,
            minsize=104,
        )
        for column in range(
            6
        ):
            self.full_build_icons_frame.grid_columnconfigure(
                column,
                weight=1,
                uniform="full_build_slot",
            )

        for slot, item in enumerate(
            items,
            start=1,
        ):
            source = item[
                "source"
            ]
            source_color = (
                GOOD
                if source
                in {
                    "OWNED",
                    "OFFENSE",
                    "ASSASSIN CORE",
                    "META",
                }
                else ACCENT
                if source
                in {
                    "ADAPTIVE",
                    "ADAPTIVE BOOTS",
                    "BOOTS • LOADING DATA",
                }
                else BORDER
            )

            holder = tk.Frame(
                self.full_build_icons_frame,
                bg=PANEL_ALT,
                height=118,
                highlightthickness=1,
                highlightbackground=(
                    GOOD
                    if item["name"]
                    in self.full_build_new_names
                    else source_color
                ),
                bd=0,
            )
            holder.grid(
                row=0,
                column=slot - 1,
                sticky="nsew",
                padx=(
                    0
                    if slot == 1
                    else 3,
                    0,
                ),
            )
            holder.grid_propagate(
                False
            )

            if item["name"] in self.full_build_new_names:
                self.full_build_new_holders.append(
                    (
                        holder,
                        source,
                    )
                )

            inner = tk.Frame(
                holder,
                bg=PANEL_ALT,
            )
            inner.pack(
                fill="both",
                expand=True,
                padx=4,
                pady=4,
            )

            item_id = item.get(
                "item_id"
            )
            photo = None
            if item_id:
                path = self.current_item_icon_path(
                    item_id
                )
                photo = self.load_photo(
                    path,
                    target_px=48,
                )

            if photo:
                icon = tk.Label(
                    inner,
                    image=photo,
                    bg=PANEL_ALT,
                    bd=0,
                )
                icon._item_photo = photo
            else:
                is_boot_slot = is_boot_item_name(
                    item.get(
                        "name",
                        "",
                    )
                )
                icon = tk.Label(
                    inner,
                    text=(
                        "BOOT"
                        if is_boot_slot
                        else "?"
                    ),
                    bg=PANEL_ALT,
                    fg=(
                        ACCENT
                        if is_boot_slot
                        else FG
                    ),
                    width=5,
                    font=ui_font(
                        9
                        if is_boot_slot
                        else 16,
                        "bold",
                    ),
                )
            icon.pack(
                pady=(0, 1),
            )
            Tooltip(
                icon,
                (
                    f"Slot {slot}: {item['name']}\n"
                    f"Source: {source}"
                ),
            )

            tk.Label(
                inner,
                text=f"{slot}. {item['name']}",
                bg=PANEL_ALT,
                fg=FG,
                font=ui_font(6, "bold"),
                wraplength=96,
                justify="center",
                anchor="center",
            ).pack(
                fill="x",
                pady=(2, 0),
            )

            source_var = tk.StringVar(
                value=(
                    "NEW • "
                    + source
                )
                if item["name"]
                in self.full_build_new_names
                else source
            )
            tk.Label(
                inner,
                textvariable=source_var,
                bg=PANEL_ALT,
                fg=(
                    GOOD
                    if source
                    in {
                        "OWNED",
                        "OFFENSE",
                        "ASSASSIN CORE",
                        "META",
                    }
                    else ACCENT
                    if source
                    in {
                        "ADAPTIVE",
                        "ADAPTIVE BOOTS",
                    }
                    else MUTED
                ),
                font=ui_font(6, "bold"),
                wraplength=96,
                justify="center",
            ).pack(
                fill="x",
                side="bottom",
                pady=(1, 0),
            )

            if item["name"] in self.full_build_new_names:
                self.full_build_new_label_vars.append(
                    (
                        source_var,
                        source,
                    )
                )

        return items

    def render_jungle_companion(
        self,
        player,
        champion,
        player_items,
        enemies,
    ):
        smite = smite_spell_info(player)

        # Non-jungler: do not occupy any live-build space.
        if not smite["has_smite"]:
            self.hide_companion_block()
            self.clear_frame(self.companion_options_frame)
            self.companion_signature = None
            return []

        owned = owned_jungle_companion(
            player_items,
            self.dd,
        )

        if owned:
            self.last_known_companion_color = owned

        # Once a companion has been bought, remove this section completely.
        # Also keep it hidden after Smite evolves because that proves the jungle
        # quest is already underway even if the starter's inventory name changes.
        if owned or smite["state"] in {"evolving", "completed"}:
            self.hide_companion_block()
            self.clear_frame(self.companion_options_frame)
            self.companion_signature = (
                "hidden",
                owned,
                smite["state"],
            )
            return []

        # Base Smite + no companion: this is the only state where the choices
        # should be visible.
        self.show_companion_block()

        options = score_jungle_companions(
            champion,
            enemies,
        )

        signature = (
            champion,
            smite["state"],
            tuple(
                (option["color"], option["score"])
                for option in options
            ),
            self.dd.version,
        )

        self.companion_status_var.set(
            "Choose your jungle companion. This section disappears immediately "
            "after the selected companion is detected in your inventory."
        )

        if signature == self.companion_signature:
            return options

        self.companion_signature = signature
        self.clear_frame(self.companion_options_frame)

        for rank, option in enumerate(
            options,
            start=1,
        ):
            color = option["color"]
            name = option["name"]
            item_id = jungle_companion_item_id(
                self.dd,
                name,
            )

            card = tk.Frame(
                self.companion_options_frame,
                bg=PANEL_ALT,
                highlightthickness=(
                    2 if rank == 1 else 1
                ),
                highlightbackground=(
                    ACCENT if rank == 1 else BORDER
                ),
                bd=0,
            )
            card.pack(
                side="left",
                fill="both",
                expand=True,
                padx=(
                    0 if rank == 1 else 6,
                    0,
                ),
            )

            inner = tk.Frame(
                card,
                bg=PANEL_ALT,
            )
            inner.pack(
                fill="both",
                expand=True,
                padx=7,
                pady=7,
            )

            photo = None
            if item_id:
                path = self.current_item_icon_path(
                    item_id
                )
                photo = self.load_photo(
                    path,
                    target_px=44,
                )

            if photo:
                icon = tk.Label(
                    inner,
                    image=photo,
                    bg=PANEL_ALT,
                    bd=0,
                )
                icon._item_photo = photo
            else:
                icon = tk.Label(
                    inner,
                    text=color[0],
                    bg=PANEL_ALT,
                    fg=FG,
                    width=4,
                    font=(
                        "Segoe UI",
                        14,
                        "bold",
                    ),
                )

            icon.pack(
                side="left",
                padx=(0, 7),
            )

            Tooltip(
                icon,
                f"{color} — {name}\n"
                f"{option['description']}",
            )

            text_box = tk.Frame(
                inner,
                bg=PANEL_ALT,
            )
            text_box.pack(
                side="left",
                fill="both",
                expand=True,
            )

            tk.Label(
                text_box,
                text=(
                    f"#{rank} {color}"
                    + (
                        " • SUGGESTED"
                        if rank == 1
                        else ""
                    )
                ),
                bg=PANEL_ALT,
                fg=(
                    GOOD
                    if rank == 1
                    else FG
                ),
                font=(
                    "Segoe UI",
                    9,
                    "bold",
                ),
                anchor="w",
            ).pack(fill="x")

            tk.Label(
                text_box,
                text=(
                    f"{option['short']}  |  "
                    f"{option['score']:.1f}/10"
                ),
                bg=PANEL_ALT,
                fg=ACCENT,
                font=(
                    "Segoe UI",
                    8,
                    "bold",
                ),
                anchor="w",
            ).pack(
                fill="x",
                pady=(2, 0),
            )

            tk.Label(
                text_box,
                text=" • ".join(
                    reason.capitalize()
                    for reason in option["reasons"]
                ),
                bg=PANEL_ALT,
                fg=MUTED,
                font=(
                    "Segoe UI",
                    8,
                ),
                anchor="w",
                justify="left",
                wraplength=180,
            ).pack(
                fill="x",
                pady=(2, 0),
            )

        return options

    def render_enemy_threats(self, per_enemy):
        signature = tuple(
            (
                info.get("champion", "?"),
                tuple(str(x[0]) for x in (info.get("items") or [])),
                tuple(enemy_threat_tags(info)),
            )
            for info in per_enemy
        )
        if signature == self.enemy_threat_signature:
            return

        self.enemy_threat_signature = signature
        self.clear_frame(self.enemy_threats_frame)

        if not per_enemy:
            ttk.Label(
                self.enemy_threats_frame,
                text="No enemy data available yet.",
                style="Muted.Panel.TLabel",
            ).pack(anchor="w")
            return

        for index, info in enumerate(per_enemy[:5]):
            champion = info.get("champion", "?")
            tags = enemy_threat_tags(info)
            item_names = [name for _item_id, name in (info.get("items") or [])]

            card = tk.Frame(
                self.enemy_threats_frame,
                bg=PANEL_ALT,
                highlightthickness=1,
                highlightbackground=BORDER,
                bd=0,
            )
            card.pack(
                side="left",
                fill="both",
                expand=True,
                padx=(0 if index == 0 else 5, 0),
            )

            inner = tk.Frame(card, bg=PANEL_ALT)
            inner.pack(fill="both", expand=True, padx=6, pady=6)

            path = self.dd.champion_icon_path(champion)
            photo = self.load_photo(path, target_px=int(SETTINGS.get("champion_icon_px", 28)))

            if photo:
                icon = tk.Label(inner, image=photo, bg=PANEL_ALT, bd=0)
                icon._champion_photo = photo
            else:
                icon = tk.Label(
                    inner,
                    text="?",
                    bg=PANEL_ALT,
                    fg=FG,
                    width=4,
                )
            icon.pack(side="left", padx=(0, 6))

            text_box = tk.Frame(inner, bg=PANEL_ALT)
            text_box.pack(side="left", fill="both", expand=True)

            tk.Label(
                text_box,
                text=champion,
                bg=PANEL_ALT,
                fg=FG,
                font=ui_font(9, "bold"),
                anchor="w",
            ).pack(fill="x")

            tk.Label(
                text_box,
                text=" • ".join(tags),
                bg=PANEL_ALT,
                fg=ACCENT if any("HIGH" in x for x in tags) else MUTED,
                font=ui_font(8, "bold"),
                anchor="w",
                justify="left",
                wraplength=135,
            ).pack(fill="x", pady=(2, 0))

            tooltip_text = champion
            if item_names:
                tooltip_text += "\nVisible items:\n- " + "\n- ".join(item_names)
            else:
                tooltip_text += "\nNo visible completed items yet."
            Tooltip(icon, tooltip_text)

    def render_next_purchase(
        self,
        player,
        champion,
        player_items,
        enemies,
        gold,
        adaptive_options,
        companion_options,
        full_build,
    ):
        profile = PROFILES.get(champion)
        if not profile or not self.dd.item_data:
            self.purchase_target_var.set("Purchase planning is unavailable for this profile.")
            self.purchase_note_var.set("")
            self.clear_frame(self.purchase_plan_frame)
            return

        _path, path_title, baseline_items, _boots, _comp = chosen_baseline_path(
            profile,
            enemies,
        )
        core_items = common_core_items(profile)

        # Jungle companion is the first purchase priority for a Smite user if none
        # of the three companion starters is currently owned.
        if (
            player_has_smite(player)
            and not jungle_quest_completed(player)
            and not owned_jungle_companion(player_items, self.dd)
            and companion_options
        ):
            top_companion = companion_options[0]
            target_name = top_companion["name"]
            target_source = f"JUNGLE COMPANION — {top_companion['color']}"
        else:
            target_name = None
            target_source = None

        # After the jungle starter, follow the exact displayed adaptive full build.
        # This keeps "what to buy next" synchronized with the 6-slot target above.
        if not target_name:
            target_name = first_unowned_full_build_target(
                full_build or [],
                player_items,
                self.dd,
            )
            if target_name:
                # Report the same source label used by the full-build card.
                source_match = next(
                    (
                        item.get("source")
                        for item in (full_build or [])
                        if normalize_name(item.get("name")) == normalize_name(target_name)
                    ),
                    "ADAPTIVE FULL BUILD",
                )
                target_source = f"FULL BUILD — {source_match}"

        if not target_name:
            self.purchase_target_var.set(
                "Build target complete — no additional target item is currently available."
            )
            self.purchase_note_var.set("")
            self.clear_frame(self.purchase_plan_frame)
            return

        target_id = self.dd.item_id_for_name(target_name)
        if not target_id:
            self.purchase_target_var.set(
                f"Target: {target_name} — recipe metadata is not available."
            )
            self.purchase_note_var.set("")
            self.clear_frame(self.purchase_plan_frame)
            return

        is_companion_target = target_name in {
            data["name"] for data in JUNGLE_COMPANIONS.values()
        }

        if is_companion_target:
            total_cost = item_total_gold(self.dd, target_id)
            try:
                gold_now = max(0, int(float(gold)))
            except Exception:
                gold_now = 0

            if total_cost > 0 and total_cost <= gold_now:
                plan = {
                    "target": target_name,
                    "remaining_before": total_cost,
                    "purchases": [{
                        "item_id": target_id,
                        "name": target_name,
                        "cost": total_cost,
                        "complete": True,
                    }],
                    "gold_after": gold_now - total_cost,
                    "message": "Buy this jungle companion starter now.",
                    "save_for": None,
                }
            elif total_cost > 0:
                plan = {
                    "target": target_name,
                    "remaining_before": total_cost,
                    "purchases": [],
                    "gold_after": gold_now,
                    "message": "Save enough gold for the jungle companion starter.",
                    "save_for": {
                        "item_id": target_id,
                        "name": target_name,
                        "cost": total_cost,
                        "missing_gold": max(0, total_cost - gold_now),
                    },
                }
            else:
                plan = build_purchase_plan(
                    self.dd,
                    target_id,
                    player_items,
                    gold,
                    max_steps=3,
                )
        else:
            plan = build_purchase_plan(
                self.dd,
                target_id,
                player_items,
                gold,
                max_steps=3,
            )

        player_signature = tuple(
            sorted(
                str(item.get("itemID"))
                for item in (player_items or [])
                if item.get("itemID")
            )
        )
        signature = (
            champion,
            target_name,
            int(float(gold)) if str(gold).replace(".", "", 1).isdigit() else str(gold),
            player_signature,
            tuple((x["item_id"], x["cost"]) for x in plan["purchases"]),
            (
                plan["save_for"]["item_id"],
                plan["save_for"]["cost"],
            ) if plan["save_for"] else None,
            self.dd.version,
        )

        self.purchase_target_var.set(
            f"Target: {target_name}  |  Source: {target_source}  |  "
            f"Gold now: {int(float(gold)) if str(gold).replace('.', '', 1).isdigit() else gold}  |  "
            f"Gold needed to finish target: {plan['remaining_before']}"
        )

        if signature == self.purchase_signature:
            return

        self.purchase_signature = signature
        self.clear_frame(self.purchase_plan_frame)

        if plan["purchases"]:
            for i, purchase in enumerate(plan["purchases"], start=1):
                holder = ttk.Frame(self.purchase_plan_frame, style="Panel.TFrame")
                holder.pack(side="left", padx=(0 if i == 1 else 10, 0))

                path = self.current_item_icon_path(purchase["item_id"])
                photo = self.load_photo(path, small=False)
                if photo:
                    icon = ttk.Label(holder, image=photo, style="Panel.TLabel")
                else:
                    icon = ttk.Label(
                        holder,
                        text="?",
                        style="Panel.TLabel",
                        width=6,
                    )
                icon.pack()
                Tooltip(icon, purchase["name"])

                ttk.Label(
                    holder,
                    text=purchase["name"],
                    style="Panel.TLabel",
                    wraplength=130,
                    justify="center",
                ).pack(pady=(2, 0))

                ttk.Label(
                    holder,
                    text=(
                        f"{purchase['cost']}g"
                        + (" • COMPLETE" if purchase.get("complete") else "")
                    ),
                    style="Good.Panel.TLabel" if purchase.get("complete") else "Accent.Panel.TLabel",
                ).pack()

            self.purchase_note_var.set(
                f"{plan['message']}  Gold left after shown purchases: {plan['gold_after']}g."
            )
        elif plan["save_for"]:
            save = plan["save_for"]
            holder = ttk.Frame(self.purchase_plan_frame, style="Panel.TFrame")
            holder.pack(side="left")

            path = self.current_item_icon_path(save["item_id"])
            photo = self.load_photo(path, small=False)
            if photo:
                icon = ttk.Label(holder, image=photo, style="Panel.TLabel")
            else:
                icon = ttk.Label(holder, text="?", style="Panel.TLabel", width=6)
            icon.pack(side="left", padx=(0, 8))
            Tooltip(icon, save["name"])

            ttk.Label(
                holder,
                text=(
                    f"Save for {save['name']} — {save['cost']}g "
                    f"({save['missing_gold']}g more)"
                ),
                style="Accent.Panel.TLabel",
                wraplength=500,
            ).pack(side="left")

            self.purchase_note_var.set(plan["message"])
        else:
            self.purchase_note_var.set(plan["message"])

    def render_build(self, champion, enemies):
        profile = PROFILES.get(champion)
        if not profile:
            self.path_var.set(f"No local build profile for {champion}.")
            self.note_var.set(
                "Live detection still works. Add a profile to profiles.json to enable build icons."
            )
            self.clear_frame(self.build_icons)
            return

        path, title, item_names, boot_names, comp = chosen_baseline_path(
            profile,
            enemies,
        )
        core_items = common_core_items(profile)
        situational_items = item_names[len(core_items):]

        signature = (
            champion,
            path,
            tuple(boot_names),
            tuple(core_items),
            tuple(situational_items),
            self.dd.version,
        )

        enemy_names = ", ".join(e.get("championName", "?") for e in enemies)
        self.path_var.set(
            f"BASELINE: {title} | AP={comp['AP']} AD={comp['AD']} high-CC={comp['CC']} | "
            f"Enemies: {enemy_names}"
        )
        self.note_var.set(
            f"CORE stays stable across profile paths. SITUATIONAL BASELINE follows the "
            f"current enemy composition. Profile: {profile.get('referencePatch', '-')}. "
            f"{profile.get('note', '')}"
        )

        if signature == self.build_signature:
            return

        self.build_signature = signature
        self.clear_frame(self.build_icons)

        def render_named_row(label_text, names):
            section = ttk.Frame(self.build_icons, style="Panel.TFrame")
            section.pack(fill="x", anchor="w", pady=(0, 7))

            ttk.Label(
                section,
                text=label_text,
                style="Section.Panel.TLabel",
            ).pack(anchor="w")

            row = ttk.Frame(section, style="Panel.TFrame")
            row.pack(anchor="w", pady=(3, 0))

            if not names:
                ttk.Label(
                    row,
                    text="No items in this section.",
                    style="Muted.Panel.TLabel",
                ).pack(side="left")
                return

            valid_items = []
            for item_name in names:
                item_id = current_sr_item_id(
                    self.dd,
                    item_name,
                    require_completed=(
                        not is_boot_item_name(
                            item_name
                        )
                    ),
                )
                if item_id:
                    valid_items.append(
                        (
                            item_name,
                            item_id,
                        )
                    )

            if not valid_items:
                ttk.Label(
                    row,
                    text="No current Summoner's Rift items in this section.",
                    style="Muted.Panel.TLabel",
                ).pack(
                    side="left"
                )
                return

            for pos, (
                item_name,
                item_id,
            ) in enumerate(
                valid_items,
                start=1,
            ):
                self.add_item_icon(
                    row,
                    item_id,
                    item_name,
                    position=pos,
                )

        render_named_row("BOOTS", boot_names)
        render_named_row("CORE", core_items)
        render_named_row(f"SITUATIONAL BASELINE — {title}", situational_items)

    def copy_live_summary(self):
        if not self.last_live_summary:
            self.rs_info(
                APP_NAME,
                "There is no live-game summary to copy.",
            )
            return
        self.clipboard_clear()
        self.clipboard_append(self.last_live_summary)
        self.update()
        self.rs_info(
            APP_NAME,
            "Live-game summary copied to the clipboard.",
        )

